(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.6"]={"from":144,"a":[["\u0003מדסיפא\u0004 \u0005[מ\u0006אחר \u0005שסופה]\u0006 של הברייתא עוסק \u0003ב\u0004מקרה של \u0003מיפך\u0004 \u0005[בהפיכת\u0006 העדות\u0005]\u0006 \u0003והזמה, רישא נמי\u0004 \u0005[תחילתה גם כן]\u0006 יש לפרש \u0003במיפך\u0004 \u0005[בהפיכת\u0006 העדות\u0005]\u0006 \u0003והזמה,\u0004 ולא היו אלא שתי כתות עדים בלבד.","\u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: אמרו העדים \u0003\"מעידנו\u0004 (מעידים אנחנו) \u0003את איש פלוני שהפיל את שן עבדו\u0004 \u0003ו\u0004אחר כך \u0003סימא את עינו\", שהרי העבד אומר כן,\u0004 שגם הוא תומך בעדות זו שהרי הוא מרוויח על ידה תשלום דמי עינו שנסתמאה לאחר שיצא לחירות, \u0003ונמצאו\u0004 עדים אלה \u0003זוממין\u0004 — הרי הם \u0003משלמין דמי עין לרב\u0004 (האדון).","ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דלא קא מודו להו בתראי בחבלא\u0004 \u0005[אם\u0006 במקרה \u0005שאין מודים להם\u0006 העדים \u0005האחרונים\u0006 המזימים לעדים הראשונים \u0005בחבלה]\u0006 \u0003כלל,\u0004 שהם אומרים שלא חבל האדון בכלל בעבדו, אם כן הוזמו העדים הקודמים הזמה גמורה, ואז \u0003דמי כוליה\u0004 \u0005[כל]\u0006 ה\u0003עבד לרב בעי שלומי ליה\u0004 \u0005[צריכים\u0006 הם \u0005לשלם לו\u0006 לאדון\u0005],\u0006 שלפי עדותם היה יוצא לחירות ומפסיד את עבדו!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003דקא מודו כולהו בחבלא\u0004 \u0005[שמודים כולם,\u0006 גם העדים האחרונים, \u0005בחבלה]\u0006 שחבל האדון בעבדו המוציאה אותו לחירות,","\u0003ודקא אפכינן\u0004 \u0005[ו\u0006אולם מדובר \u0005שהפכו]\u0006 את העדות, שלדבריהם קודם הוציא את עינו ואחר כך הפיל את שינו, \u0003ואזמינהו\u0004 \u0005[ו\u0006מלבד זה, גם \u0005הזימו אותם,\u0006 את הראשונים\u0005]\u0006 ואמרו שלא היו שם כלל. ומאחר שבסוף הברייתא מדובר בהיפוך והזמה אחת על ידי כת של עדים, כך יש לפרש את תחילתה, לדברי אביי.","\u0003ו\u0004מעתה יש לברר עוד: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דקא מאחרי אחורי הני בתראי\u0004 \u0005[אם מאחרים אלה האחרונים]\u0006 את המעשה, ואומרים שהמאורעות שהעידו עליהם הראשונים שאירעו ביום מסויים, לא היו באותו יום אלא מאוחר יותר, \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003דמי עבד לרב בעי שלומי\u0004 \u0005[צריכים\u0006 הראשונים \u0005לשלם],\u0006 אף שגם השניים שהזימו טוענים שחבל בו.","\u0003דכי מחייבי ליה לגברא, אכתי גברא לאו בר חיובא הוא\u0004 \u0005[שכאשר חייבו\u0006 בעדותם \u0005את האיש\u0006 לשחרר את עבדו, \u0005עדיין האיש לא היה בן חיוב]\u0006 לשחררו, לפי עדות השניים! \u0003אלא\u0004 יש לומר \u0003דקא מקדמי קדומי הני בתראי\u0004 \u0005[שמקדימים\u0006 את זמן המאורעות \u0005אלה האחרונים]\u0006 ואומרים שהמעשה אירע מוקדם יותר,","\u0003ו\u0004עוד יש לברר כיצד בדיוק היה הדבר, \u0003אי\u0004 \u0005[אם]\u0006 מדובר ש\u0003לא עמד\u0004 האדון \u0003בדין, אכתי\u0004 \u0005[עדיין]\u0006 \u0003דמי כוליה\u0004 \u0005[כל]\u0006 ה\u0003עבד לרב בעי שלומי ליה\u0004 \u0005[\u0006הם \u0005צריכים לשלם לו,\u0006 לרב\u0005],\u0006 \u0003דאכתי גברא\u0004 \u0005[שעדיין האיש]\u0006 \u0003לא מיחייב\u0004 \u0005[היה מחוייב]\u0006 והם באים בעדותם לחייבו לשחרר את העבד, וחייבים לשלם כדין עדים זוממים.","\u0003אלא\u0004 יש לומר שמדובר כאן בסיכומו של הבירור שכבר \u0003עמד\u0004 האדון \u0003בדין,\u0004 והעידו שכבר העידו עדים אחרים שעמד האדון בדין והעבד יוצא לחירות ולאחר שנגמר דינו ברח האדון למקום אחר, ושם שוב עמד בדין ונתחייב האדון בדמי העין, אלא שבאו אחרים והעידו שאף שנתחייב לשחררו בבית דין לא כך היה מעשה אלא שנתחייב בדמי שן, וגם הזימו את הראשונים, שהעידו שלא היו במקום באותה שעה.","ושבים לדון בהוכחתו של רבא, מאותה ברייתא, לכך שהכחשה תחילת הזמה היא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא לרב אשי: דוקיא\u0004 \u0005[דיוקו]\u0006 של \u0003רבא\u0004 שדייק מכאן שהכחשה תחילת הזמה \u0003מהיכא\u0004 \u0005[מהיכן\u0006 הוא\u0005]?\u0006 \u0003אילימא מרישא\u0004 \u0005[אם תאמר מתחילתה]\u0006 של הברייתא כפי שהסביר אותה רבא, ובשלוש כיתות עדים. מכל מקום \u0003רישא מי קא מתכחשי מציעאי\u0004 \u0005[בתחילה האם\u0006 בכלל \u0005הוכחשו\u0006 העדים \u0005האמצעיים]?\u0006","אף שעדותם עומדת בסתירה לזו של הראשונים, מכל מקום \u0003כיון דאי\u0004 \u0005[שאם]\u0006 \u0003לא מתזמי\u0004 \u0005[היו מוזמים]\u0006 — בסופו של דבר \u0003סהדותא כוותייהו קא קיימא\u0004 \u0005[העדות כדבריהם היתה עומדת],\u0006 משום \u0003דדינא כוותייהו פסקינן\u0004 \u0005[שאת הדין כדבריהם אנו פוסקים],\u0006 שהרי \u0003יש בכלל מאתים מנה,\u0004 כלומר, שאף שהעדים הראשונים העידו שצריך לשחרר עבדו ולשלם דמי העין המרובים יותר, ואחרונים העידו שצריך לשלם רק דמי השן המועטים יותר, מכל מקום כולם מעידים שחבל בעבד חבלה המשחררת את העבד, וכן שהוא חייב לו גם דמי נזק שהזיקו, אלא שנחלקו מה גודל סכום זה: אם דמי עין אם דמי שן, ובמקרה כזה מחייבים אותו בפחות שבסכומים.","\u0003הלכך\u0004 \u0005[על כן]\u0006 יוצא מכאן כי \u0003קמאי הוא דקא מתכחשי\u0004 \u0005[\u0006העדים \u0005הראשונים הם שמוכחשים],\u0006 \u0003מציעאי\u0004 \u0005[\u0006העדים \u0005האמצעיים]\u0006 \u0003לא מתכחשי מידי\u0004 \u0005[מוכחשים כלל],\u0006 ואם כן לא היה כאן כלל ענין של הכחשה, ואין ללמוד מכאן שהכחשה שיש בה ביטול העדות נחשבת לתחילת הזמה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי לרב אחא: \u0003רבא סבר\u0004 \u0005[סבור]:\u0006 \u0003מדרישא\u0004 \u0005[מ\u0006כיון ש\u0005בתחילת\u0006 הברייתא\u0005]\u0006 מוכרחים להבין שמדובר \u0003בשלש כיתות\u0004 עדים, וכפי שדייק מקודם, \u0003סיפא נמי\u0004 \u0005[\u0006ב\u0005סופה גם כן]\u0006 מדובר \u0003בשלש\u0004 כיתות, שהרי ברייתא אחת היא. \u0003ו\u0004את עיקר חידושו \u0003דייק\u0004 רבא \u0003מסיפא\u0004 \u0005[מסופה]\u0006 של הברייתא, וצריכים להסביר את הענין באופן זה:","\u0003כגון דאתו בי תרי ואמרי\u0004 \u0005[שבאו שנים\u0006 עדים \u0005ואמרו]:\u0006 תחילה \u0003הפיל\u0004 האדון \u0003את שינו\u0004 של עבדו \u0003ו\u0004אחר כך \u0003סימא את עינו, ופסקיניה לדינא אפומייהו\u0004 \u0005[ופסקו את הדין על פיהם]\u0006 שצריך האדון לשחרר את העבד ולשלם לו דמי עינו,","\u0003ואתו בי תרי אחריני ואמרי\u0004 \u0005[ובאו שנים אחרים ואמרו]:\u0006 לא כך היה מעשה, אלא תחילה \u0003סימא את עינו\u0004 \u0003ו\u0004אחר כך \u0003הפיל את שינו,\u0004 ומשתחרר העבד וחייב האדון לשלם לעבד רק את דמי השן, \u0003דקא מכחשי להו להני קמאי\u0004 \u0005[שהם מכחישים אותם, את אלה\u0006 העדים \u0005הראשונים],\u0006 \u0003ונמצאו זוממין קמאי\u0004 \u0005[\u0006העדים \u0005הראשונים],\u0006 שלבסוף באה כת שלישית והעידה בעדים הראשונים שלא היו שם — על כן, \u0003קמאי\u0004 \u0005[הראשונים]\u0006 \u0003משלמין דמי עין לרב,\u0004 ודיוקו כך הוא:","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003הכחשה לאו\u0004 \u0005[לא]\u0006 \u0003תחילת הזמה היא, אמאי משלמי\u0004 \u0005[מדוע\u0006 הם \u0005משלמים]?\u0006 \u0003הא אתכחשו להו מעיקרא\u0004 \u0005[הרי\u0006 כבר \u0005הוכחשו להם מתחילה]\u0006 על ידי העדים האמצעיים, וכיון שהוכחשו — שוב אין עדותם עדות! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003הכחשה תחילת הזמה היא.\u0004","ומעירים: \u0003ואביי\u0004 שאינו סבור כן \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ולהשיב על הוכחה זו: גם לשיטתך, \u0003בשלמא רישא\u0004 \u0005[נניח\u0006 ב\u0005תחילה\u0006 בקטע הראשון \u0003לא סגי\u0004 \u0005[ייתכן]\u0006 ש\u0003לא\u0004 מדובר ב\u0003שלש כיתות, שהרי קתני\u0004 \u0005[שנה]\u0006 \u0003\"הרב אומר כן\",\u0004 וכפי שאמרנו אין הדבר מסתבר אלא כשיש כת עדים קודמת שמעידה שחייב לשחרר את העבד ולשלם דמי עינו.","\u0003אלא סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 \u0003למה לי\u0004 לפרש שמדובר ב\u0003שלש כיתות?\u0004 משום שנאמר בברייתא \u0003\"שהרי העבד אומר כן\"?\u0004","והרי זה אינו מוכיח דבר, לפי שה\u0003עבד כל דהו מימר אמר\u0004 \u0005[כל שהוא,\u0006 בכל מקרה, \u0005אומר]\u0006 ומוכן להסכים לעדות, \u0003דניחא ליה דניפוק\u0004 \u0005[שנוח לו שיצא]\u0006 \u0003לחירות.\u0004 ולכן מפרש אביי שמדובר רק בשתי כיתות ובהפיכת העדות תוך כדי הזמה, ואין מכאן הוכחה שהכחשה תחילת הזמה היא.","ועל עצם דין הברייתא \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא, אימא\u0004 \u0005[אמור]:\u0006 \u0003סימא את עינו\u0004 —"],["\u0003ניפוק\u0004 \u0005[שיצא]\u0006 \u0003בעינו, הפיל את שינו\u0004 — \u0003ניפוק\u0004 \u0005[שיצא]\u0006 \u0003בשינו, סימא את עינו והפיל את שינו\u0004 — \u0003ניפוק\u0004 \u0005[שיצא]\u0006 \u0003בעינו ושינו\u0004 יחד!","\u0003אמר\u0004 לו \u0003אביי\u0004 בתשובה: \u0003עליך אמר קרא\u0004 \u0005[הכתוב],\u0006 כלומר, כדי להוציא מסברה זו פירש ואמר הכתוב: \u0003\"\u0004לחפשי ישלחנו \u0003תחת עינו\"\u0004 (שמות כא, כו), להדגיש: \u0003ולא תחת עינו ושינו,\u0004 וכן נאמר \u0003\"\u0004לחפשי ישלחנו \u0003תחת שינו\"\u0004 (שמות כא כז), להדגיש: \u0003ולא תחת שינו ועינו.\u0004","ושבים לדון בדברי רבא, \u0003אמר רב אידי בר אבין: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 במשנה שהכחשה היא תחילת הזמה, ששנינו במשנתנו: \u0003גנב על פי\u0004 עדות \u0003שנים וטבח ומכר על פיהם, ונמצאו\u0004 עדים אלה \u0003זוממין\u0004 — \u0003משלמין לו את הכל.\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 מדובר כאן בסדר הרגיל, כלומר, ש\u0003העידו על הגניבה וחזרו והעידו על הטביחה, והוזמו על הגניבה וחזרו והוזמו על הטביחה.\u0004","ואולם, אם כן יש לשאול: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כיון שהוזמו על הגניבה,\u0004 אם כן \u0003לגבי\u0004 \u0005[אצל]\u0006 עדות \u0003טביחה הוה להו\u0004 \u0005[הרי הם]\u0006 \u0003מוכחשין, וקתני\u0004 \u0005[ושנה]\u0006 בכל זאת: \u0003משלמין לו את הכל. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003הכחשה לאו\u0004 \u0005[לא]\u0006 \u0003תחילת הזמה היא,\u0004 אם כן על ה\u0003טביחה אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלמין?\u0004 שכיון שהוכחשו אין ממש בעדותם על הטביחה וכאילו לא העידו! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003הכחשה תחילת הזמה היא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית הוכחה זו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהוזמו על הטביחה תחילה,\u0004 ובזה אין להכחיש את עדות הגניבה, ולכן אם הוזמו אחר כך גם על הגניבה משלמים על הכל.","\u0003ו\u0004בעיה זו של הכחשה והזמה שנויה \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 של אמוראים קודמים, שבענין \u0003עדים\u0004 שהעידו באדם שהוא חייב מיתה \u0003ש\u0004תחילה \u0003הוכחשו\u0004 על ידי עדים אחרים \u0003ולבסוף הוזמו,\u0004 נחלקו \u0003ר' יוחנן ור' אלעזר, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: נהרגין\u0004 על שזממו להרוג, הרי שהוא סבור שהכחשה תחילת הזמה היא, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין נהרגין,\u0004 משום שהוכחשו תחילה, ובטלה עדותם, ואין הכחשה תחילת הזמה.","ולזיהוי הדעות במחלוקת זו מעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי \u0003ר' אלעזר הוא\u0004 ש\u0003אמר אין נהרגין\u0004 — ש\u0003אמר ר' אלעזר: עדים שהוכחשו בנפש,\u0004 בעדות נפשות שהעידו — \u0003לוקין\u0004 משום עדות שקר,","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003ר' אלעזר הוא\u0004 ש\u0003אמר\u0004 שאם הוזמו עדי נפשות לאחר שהוכחשו הריהם \u0003נהרגין\u0004 — אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לוקין?\u0004 הן האיסור שעשו בעדות השקר \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003לאו\u0004 (מצוות לא תעשה) \u0003שניתן לאזהרת מיתת בית דין,\u0004 כלומר, לאו שעלול להגיע על ידו לידי מיתת בית דין, \u0003ו\u0004כלל בידינו: \u0003כל לאו שניתן לאזהרת מיתת בית דין\u0004 — \u0003אין לוקין עליו!\u0004","\u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003ר' אלעזר הוא\u0004 ש\u0003אמר אין נהרגין,\u0004 ומשום כך נמצא שלא היה צד של מיתת בית דין בכך, ולכן לוקים משום עדות שקר. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שדעת ר' אלעזר היא שאין נהרגים.","ולעצם דינו של ר' אלעזר שואלים: מדוע \u0003לוקין\u0004 אותם עדים שהוכחשו? הלא \u0003תרי ותרי נינהו\u0004 \u0005[שנים ושנים הם],\u0006 שהרי גם המכחישים שנים הם, \u0003מאי חזית דסמכת אהני\u0004 \u0005[מה ראית שסומך אתה על אלה]?\u0006 \u0003סמוך אהני\u0004 \u0003[על אלה\u0004 הראשונים\u0005]!\u0006 ומדוע מלקים אותם?","\u0003אמר אביי:\u0004 אין מדובר כאן בהכחשה על פי עדים, אלא \u0003בבא הרוג ברגליו,\u0004 שאם העידו על פלוני שהרג את חבירו, ובא לפנינו האיש שאמרו שהוא הרוג — הרי זו הכחשה שאין גדולה ממנה, ועל כן לוקים.","\u0003גנב\u0004 שור או שה\u0003על פי\u0004 עדות \u0003שנים, וטבח ומכר על פי\u0004 עדות \u0003עד אחד או על פי עצמו\u0004 שהודה — \u0003משלם תשלומי כפל ו\u0004אולם \u0003אינו משלם תשלומי ארבעה וחמשה.\u0004","\u0003גנב וטבח בשבת,\u0004 שנתחייב עונש מוות על שטבח בשבת, או \u0003גנב וטבח לעבודה זרה,\u0004 שאף טביחה זו היא עבירה שחייב עליה מיתה. וכן אם בן \u0003גנב משל אביו ומת אביו ואחר כך טבח ומכר,\u0004 שכיון שמת אביו הרי הוא בין יורשיו של כל מה ששייך לאביו, ובכלל זה השור או השה שנגנב, ונמצא שלא היתה הטביחה כולה באיסור שהרי גם את חלקו הוא טבח. וכן אם \u0003גנב והקדיש ואחר כך טבח ומכר\u0004 כאשר הבהמה כבר שייכת להקדש ואינה של הבעלים — בכל אלה הריהו \u0003משלם תשלומי כפל ואינו משלם תשלומי ארבעה וחמשה.\u0004","\u0003ר' שמעון אומר,\u0004 בענין קדשים שנגנבו יש לחלק: אם היו אלה \u0003קדשים שחייב\u0004 המקדיש \u0003באחריותם,\u0004 שהקדישם וקיבל על עצמו להקריב אחרים תחתיהם אם יאבדו אלה — הרי זה הגונבם וטובחם \u0003משלם תשלומי ארבעה וחמשה,\u0004 שנמצא שהגנב גרם נזק לאיש שנגנב ממנו. ואם גנב קדשים \u0003שאין\u0004 המקדיש \u0003חייב באחריותם\u0004 — \u0003פטור,\u0004 לפי שלא גנב מחבירו, אלא מן ההקדש.","שנינו במשנתנו שאם טבח ומכר \u0003על פי עד אחד\u0004 פטור. ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא, הלא עד אחד אינו יכול לחייב אדם בעונשים!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: עד אחד לא הוזכר כאן לגופו, אלא לצורך המקרה שהובא יחד עימו — כאשר הגנב עצמו הודה. ובכך \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003על פי עצמו דומיא\u0004 \u0005[\u0006הרי זה \u0005בדומה]\u0006 ל\u0003על פי עד אחד,\u0004 ופירושו: \u0003מה על פי עד אחד\u0004 — אמנם עכשיו הוא פטור, אבל \u0003כי אתי\u0004 \u0005[כאשר יבוא]\u0006 \u0003עד אחד\u0004 נוסף \u0003מצטרף בהדיה\u0004 \u0005[עימו]\u0006 — \u0003מיחייב\u0004 \u0005[מתחייב],\u0006 \u0003על פי עצמו נמי\u0004 \u0005[גם כן]\u0006 אמנם עתה הוא פטור, אבל \u0003כי אתו\u0004 \u0005[כאשר יבואו]\u0006 אחר כך \u0003עדים,\u0004 הרי זה \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 לשלם.","ויש בדבר זה \u0003לאפוקי\u0004 \u0005[להוציא\u0006 לשלול\u0005]\u0006 \u0003מ\u0004מה שאמר \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב:\u0004 מי שהיה \u0003מודה בקנס\u0004 והריהו פטור מתשלום עליו \u0003ואחר כך באו עדים\u0004 והעידו שאכן חייב הוא בקנס זה — בכל זאת הריהו \u0003פטור,\u0004 לפי שכבר הודה מעצמו. ומן המשנה הזו אין הדברים נראים כן.","כיון שהוזכרה הלכה זו של רב, דנים בה \u0003גופא\u0004 \u0005[לגופה].\u0006 \u0003אמר רב הונא אמר רב: מודה בקנס ואחר כך באו עדים\u0004 — \u0003פטור. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב חסדא לרב הונא\u0004 ממה ששנינו: \u0003מעשה ברבן גמליאל שסימא את עין טבי עבדו, והיה שמח שמחה גדולה,\u0004 לפי שטבי היה חביב על רבן גמליאל ושמח שיוכל להוציאו לחירות בהיתר.","\u0003מצאו\u0004 רבן גמליאל \u0003לר' יהושע, אמר לו\u0004 רבן גמליאל: \u0003אי\u0004 (אין) \u0003אתה יודע שטבי עבדי יצא לחירות? אמר לו: למה? אמר לו:\u0004 מפני \u0003שסמיתי את עינו, אמר לו\u0004 ר' יהושע: \u0003אין בדבריך כלום, שכבר\u0004 (שעדיין) \u0003אין לו עדים\u0004 שיעידו על כך. והואיל ושחרור העבד קנס הוא — דינך ככל מודה בקנס שפטור מן הקנס.","ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש לו עדים\u0004 — \u0003חייב,\u0004 וגם אם יעידו לאחר שהודה בקנס. \u0003ושמעינן מינה\u0004 \u0005[ולומדים אנו מכאן]\u0006 כי \u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003חייב!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרב חסדא בתשובה לכך: מכאן אין ראיה, \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר במקרה של \u0003רבן גמליאל,\u0004 משום ש\u0003לא בפני בית דין אודי\u0004 \u0005[הודה],\u0006 והודאה שלא בפני בית דין אינה נחשבת להודאה, ולפיכך אם יבואו עדים לבית הדין — יחייבו על פיהם. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יהושע אב בית דין הוה\u0004 \u0005[היה]\u0006 ואם כן כשסיפר רבן גמליאל לר' יהושע כי סימא את עינו של טבי עבדו היתה זו הודאה בפני בית דין!"],["ומשיבים: מכל מקום \u0003שלא בבית דין הוה קאי\u0004 \u0005[היה עומד]\u0006 אלא נפגשו סתם, וכיון שלא היה זה במושב בית דין — אין זו נחשבת הודאה.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 בנוסח אחר: \u0003אמר לו\u0004 ר' יהושע: \u0003אין בדבריך כלום, שכבר הודית,\u0004 משמע שההודאה היא שגרמה לכך, ואם כן היה זה בבית דין, ולפיכך","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בשאלה זו עצמה ובאופן זה: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 ש\u0003אמר\u0004 את הנימוק \u0003\"שכבר אין לך עדים\", סבר\u0004 \u0005[סבור]\u0006 ש\u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003חייב, והאי\u0004 \u0005[וזה]\u0006 ה\u0003תנא\u0004 ש\u0003אמר \"שכבר הודית\", סבר\u0004 \u0005[סבור]\u0006 ש\u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003פטור?\u0004","ודוחים: \u0003לא,\u0004 מכאן אין להוכיח, שאפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003מודה בקנס ואחר כך באו עדים פטור, ובהא קמיפלגי\u0004 \u0005[וב\u0006דבר \u0005זה נחלקו],\u0006 \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 ש\u0003אמר \"שכבר אין לך עדים\", סבר\u0004 \u0005[סבור]\u0006 כי \u0003חוץ לבית דין הוה\u0004 \u0005[היה]\u0006 המעשה, ולכן לא היה פוטר את עצמו בהודאה אם היו באים עדים. \u0003והך\u0004 \u0005[ואותו]\u0006 ה\u0003ת נא\u0004 ש\u0003אמר \"שכבר הודית\", סבר\u0004 \u0005[סבור]\u0006 ש\u0003בבית דין הוה\u0004 \u0005[היה]\u0006 המעשה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003מודה ב\u0004דבר שחיובו \u0003קנס ואחר כך באו עדים\u0004 שהעידו בו על כך — \u0003רב אמר: פטור, ושמואל אמר: חייב.\u0004","\u0003אמר רבא בר אהילאי: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור, לשיטתו\u0005]\u0006 של \u0003רב?\u0004 שהרי בדין גנב המשלם כפל, שהוא קנס, נאמר \"אם המצא תמצא בידו הגניבה... שנים ישלם\" (שמות כב, ג), ודרשו חכמים מכתוב זה: \u0003\"אם המצא\"\u0004 — \u0003בעדים, \"תמצא\"\u0004 — \u0003בדיינין, פרט למרשיע את עצמו\u0004 בהודאתו שהוא פטור מכפל, ונשאלת השאלה:","\u0003למה לי\u0004 דרשה זו? הלא דין זה, שאין אדם יכול לחייב עצמו בקנס \u0003מ\"אשר ירשיען\u0004 אלהים ישלם שנים\u0003\"\u0004 (שמות כא ח) \u0003נפקא\u0004 \u0005[יוצא\u0006 נלמד\u0005]\u0006 שרק זה שמרשיעים אותו הדיינים הוא שמשלם כפל, ולא מי שהרשיע את עצמו! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 מהדגשה זו שבכתוב \"אם המצא תמצא\" שבאה ללמדנו כי המרשיע עצמו (מודה בקנס) פטור בכל מקרה, ולכן אף \u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003פטור.\u0004","\u0003ושמואל אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 בדחיית אותה ראיה של רב: הכתוב \u0003ההוא\u0004 \u0003מבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004דינו של \u0003גנב עצמו\u0004 שמתחייב בכפל (ולא רק שומר הטוען טענת גנב ונמצאה הגניבה בידו). \u0003כדתנא דבי\u0004 \u0005[כמו ששנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 (כמבואר לעיל בדף סג,ב).","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב לשמואל\u0004 ממה ששנינו: \u0003ראה עדים שממשמשים ובאים\u0004 להעיד כנגדו, \u0003ואמר: \"גנבתי אבל לא טבחתי ולא מכרתי\"\u0004 — \u0003אינו משלם אלא קרן.\u0004 משמע שהמודה בקנס ואחר כך באו עדים פטור מתשלומי קנס! \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שחזרו עדים לאחוריהם\u0004 ולא העידו כלל, ונמצא שהודה בקנס בלא עדים.","הקשה לו רב: \u0003והא מדתני סיפא\u0004 \u0005[והרי מ\u0006מה \u0005ששנה\u0006 ב\u0005סופה,\u0006 בהמשכה של ברייתא זו\u0005]\u0006 \u0003ר' אלעזר בר' שמעון אומר:\u0004 למרות שהודה בקנס מצריכים אנו ש\u0003יבואו עדים ויעידו\u0004 כדי לחייבו בקנס, \u0003מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי \u0003לא\u0004 צריכים הם להעיד, כיון שממילא לא יתחייב בעדותם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל\u0004 בתשובה: \u0003לאו איכא\u0004 \u0005[\u0006האם \u0005לא ישנה]\u0006 דעת \u0003ר' אלעזר בר' שמעון דקאי כוותי\u0004 \u0005[שעומד כמותי]\u0006 ומחזיק בשיטתי? \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את שיטתי זו, אמרתיה \u0003כ\u0004דעת \u0003ר' אלעזר בר' שמעון\u0004 ולא כתנא קמא, ויכולים עדים לחייבו בקנס למרות שהודה כבר.","ומעירים, לפיכך יוצא כי \u0003לשמואל ודאי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בשאלה זו, \u0003ל\u0004שיטת \u0003רב מי לימא תנאי\u0004 \u0005[האם לומר\u0006 גם כן כי מחלוקת \u0005תנאים]\u0006 \u0003היא?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 \u0003רב: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי \u0003אפילו ל\u0004דעת \u0003ר' אלעזר בר' שמעון\u0004 אמרתים, כי \u0003עד כאן לא\u0004 שמענו כי \u0003אמר ר' אלעזר בר' שמעון התם\u0004 \u0005[שם]\u0006 שיכולים עדים לחייבו למרות שהודה \u0003אלא משום דקא מודי\u0004 \u0005[שמודה]\u0006 \u0003מחמת ביעתותא\u0004 \u0005[פחד]\u0006 ה\u0003עדים\u0004 ולא הודה מרצונו. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003מודה מעצמו\u0004 בלא פחד מפני עדים שעומדים להעיד על כך, \u0003אפילו ר' אלעזר בר' שמעון מודה\u0004 שפטור מקנס אפילו יבואו אחר כך עדים ויעידו.","\u0003אמר רב המנונא: מסתברא מילתיה\u0004 \u0005[מסתברים דבריו]\u0006 של \u0003רב באומר \"גנבתי\", ובאו\u0004 אחר כך \u0003עדים\u0004 והעידו \u0003שגנב,\u0004 שבמקרה זה \u0003פטור, שהרי\u0004 מכל מקום \u0003חייב עצמו\u0004 על פי הודאתו \u0003בקרן.\u0004","\u0003אבל\u0004 אם \u0003אמר\u0004 תחילה \u0003\"לא גנבתי\" ובאו עדים\u0004 והעידו בו \u0003שגנב\u0004 והתחייב בעדותם בתשלומי הקנס של כפל, \u0003וחזר ואמר\u0004 הוא עצמו \u0003\"טבחתי\"\u0004 או שאמר \u0003\"מכרתי\"\u0004 \u0003ו\u0004אחר כך \u0003באו עדים\u0004 והעידו \u0003שטבח\u0004 או \u0003מכר\u0004 — \u0003חייב\u0004 בתשלומי קנס של ארבעה וחמישה, \u0003שהרי\u0004 בהודאתו זו לא חייב עצמו בתשלום כל שהוא אלא \u0003פטר עצמו מכלום\u0004 ואין זו הודאה של ממש.","\u0003אמר רבא: [קפחתי]\u0004 ניצחתי בויכוח \u0003לסבי דבי\u0004 \u0005[את זקני בית]\u0006 \u0003רב,\u0004 כלומר, את רב המנונא, שאפשר להקשות עליו, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רבן גמליאל\u0004 כשהודה לפני ר' יהושע שסימא את עין עבדו \u0003פוטר עצמו מכלום הוה\u0004 \u0005[היה],\u0006 שהרי על ידי הודאתו נפטר לגמרי מלשחרר את עבדו, \u0003וקאמר ליה\u0004 \u0005[ואמר\u0006 והקשה \u0005לו]\u0006 מענין זה \u0003רב חסדא לרב הונא,\u0004 שאמר בשם רב שהמודה בקנס ואחר כך באו עדים — פטור, \u0003ולא קא משני ליה\u0004 \u0005[תירץ לו]\u0006 שאין זו נחשבת הודאה, משמע שאין תשובה זו מתאימה לשיטת רב עצמו.","ומעירים: \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כעין הסברו של רב המנונא וכשיטת רב בדברי אמורא אחר, ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן:\u0004 מי שהודה ואמר \u0003\"גנבתי\", ובאו\u0004 אחר כך \u0003עדים\u0004 והעידו \u0003שגנב\u0004 — \u0003פטור\u0004 מן הכפל, \u0003שהרי חייב עצמו בקרן, אבל אמר \"לא גנב\u0004 תי \u0003\"\u0004\u0003ו\u0004אחר כך \u0003באו עדים\u0004 והעידו בו \u0003שגנב, וחזר ואמר \"טבחתי ומכרתי\" ובאו עדים\u0004 והעידו בו \u0003שטבח ומכר\u0004 — \u0003חייב\u0004 בתשלומי ארבעה וחמישה, \u0003שהרי\u0004 בהודאתו זו לא התחייב כלל אלא \u0003פטר עצמו מכלום.\u0004","\u0003אמר רב אשי: מתניתין וברייתא נמי דיקא\u0004 \u0005[משנתנו והברייתא גם כן מדוייקת]\u0006 כהסברם של רב המנונא ור' חייא בר אבא. \u0003מתניתין, דתנן\u0004 \u0005[משנתנו, ששנינו\u0006 בה\u0005]:\u0006 \u0003גנב על פי שנים\u0004 עדים, \u0003וטבח ומכר על פי עד אחד או על פי עצמו\u0004 — \u0003משלם תשלומי כפל, ואינו משלם תשלומי ארבעה וחמשה.\u0004","ונדייק: \u0003למה לי\u0004 מה הטעם \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003גנב על פי שנים? ליתני\u0004 \u0005[שישנה]\u0006 כך: \u0003גנב וטבח ומכר על פי עד אחד או על פי עצמו\u0004 — \u0003אינו משלם אלא\u0004 את \u0003הקרן,\u0004 ונלמד מכאן אותה הלכה לפטור תשלומי קנס בהודאת עצמו או בעדות עד אחד בלשון קצרה יותר!"],["\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 לדיוק: דווקא \u0003גנב על פי שנים, וטבח על פי עד אחד או על פי עצמו,\u0004 ש\u0003הוא\u0004 מקרה ש\u0003לא מחייב עצמו בקרן\u0004 —","\u0003הוא דאמרינן\u0004 \u0005[שאנו אומרים]\u0006 שדינה של הודאה \u0003על פי עצמו דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003על פי עד אחד, מה על פי עד אחד כי אתי\u0004 \u0005[כאשר בא]\u0006 \u0003עד אחד\u0004 נוסף, הוא \u0003מצטרף בהדיה\u0004 \u0005[עמו]\u0006 עם העד הראשון — \u0003מחייב\u0004 \u0005[מתחייב],\u0006 \u0003על פי עצמו נמי\u0004 \u0005[גם כן],\u0006 \u0003כי אתו\u0004 \u0005[כאשר באים]\u0006 \u0003עדים\u0004 שיעידו על הטביחה או המכירה — \u0003מחייב\u0004 \u0005[מתחייב].\u0006","\u0003אבל גנב וטבח ומכר על פי עד אחד או על פי עצמו,\u0004 ש\u0003חייב עצמו\u0004 על כל פנים \u0003בקרן, לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003על פי עצמו דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003על פי עד אחד,\u0004 שהרי על פי עד אחד יש בו כדי לחייבו (אם יצטרף אליו עד נוסף) ואילו בהודאת עצמו הריהו נפטר בהודאתו. זו היא הראיה מדיוק לשון המשנה.","ודיוק מן ה\u0003ברייתא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ראה עדים שממשמשין ובאין\u0004 להעיד כנגדו, \u0003ואמר \"גנבתי, אבל לא טבחתי ולא מכרתי\"\u0004 — \u0003אינו משלם אלא קרן.\u0004 ויש לשאול: \u0003למה לי למיתנא\u0004 \u0005[לשנות]\u0006 את הברייתא באופן מורכב כזה: \u0003ואמר \"גנבתי אבל לא טבחתי ולא מכרתי\"? ניתני\u0004 \u0005[שישנה]\u0006 באופן פשוט יותר: \u0003או\u0004 שאמר \u0003\"גנבתי\" או\u0004 שאמר \u0003\"טבחתי ומכרתי\"!\u0004","\u0003אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 להלכה זו היא דווקא משום שהודה ו\u0003אמר \"גנבתי\" הוא,\u0004 שמפני ש\u0003חייב עצמו בקרן\u0004 — ש\u0003פטור\u0004 מתשלומי הכפל וארבעה וחמישה, \u0003אבל אמר\u0004 תחילה \u0003\"לא גנבתי\" ובאו עדים שגנב, וחזר ואמר \"טבחתי ומכרתי\" ובאו עדים שטבח ומכר,\u0004 ש\u0003לא חייב עצמו בקרן\u0004 כאשר הודה על הטביחה או המכירה — \u0003חייב\u0004 בתשלומי ארבעה וחמישה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הודאה\u0004 של \u0003טביחה לאו\u0004 \u0005[לא]\u0006 \u0003הודאה היא\u0004 שהרי בא לפטור עצמו מן הכל, וכהסברו של רב המנונא.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים את הראיה מן הברייתא: \u0003לא, היא גופה קא משמע לן\u0004 \u0005[אותה\u0006 הלכה \u0005עצמה השמיע לנו]\u0006 ואין לחדש כאן חידוש אחר, כיון שעצם הדבר יש בו צד חידוש, ש\u0003כיון\u0004 ש\u0003אמר\u0004 תחילה \u0003\"גנבתי\", אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר \"לא טבחתי ולא מכרתי\", ובאו\u0004 אחר כך \u0003עדים\u0004 והעידו בו \u0003שטבח ומכר\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר?","\u0003תשלומי\u0004 \u0003ארבע\u0004 ו\u0003חמשה אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 \u0003ולא תשלומי ארבעה\u0004 (במקום חמישה) \u0003ולא תשלומי שלשה\u0004 (במקום ארבעה), וכיון שאינו חייב לשלם כפל (שהרי הודה בגניבה) — אף אין חלים עליו תשלומי ארבעה וחמישה.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר כי\u0006 יש מחלוקת \u0005תנאים]\u0006 בשיטת רב המנונא, ששנינו בברייתא: \u0003היו שנים מעידין\u0004 אותו \u0003שגנב, והיו שנים מעידים אותו שטבח ומכר, הוזמו עדי גניבה\u0004 הרי ממילא \u0003עדות שבטלה מקצתה בטלה כולה,\u0004 שאין עוד כל משמעות לעדותם של עדי הטביחה והמכירה, שכן יתכן שטבח ומכר את הבהמה שלו.","ואולם אם \u0003הוזמו עדי טביחה\u0004 — \u0003הוא,\u0004 הגנב, \u0003משלם\u0004 לבעלים \u0003תשלומי כפל\u0004 על גניבתו, \u0003והן,\u0004 עדי הטביחה או המכירה, \u0003משלמין\u0004 לגנב \u0003תשלומי\u0004 שנים או \u0003שלשה\u0004 שרצו לחייבו בתשלום זה בנוסף על תשלומי הכפל. \u0003משום\u0004 (משם) \u0003סומכוס אמרו: הן משלמין תשלומי כפל, והוא משלם תשלומי שלשה לפר ושנים לאיל.\u0004","על דברי סומכוס אלה תוהים: \u0003אהייא קאי\u0004 \u0005[על מה עומד],\u0006 לאיזה חלק במשנה מתייחס \u0003סומכוס? אילימא ארישא\u0004 \u0005[אם תאמר על ההתחלה],\u0006 וכי \u0003לית ליה\u0004 \u0005[אין לו]\u0006 \u0003לסומכוס\u0004 הכלל ש\u0003עדות שבטלה מקצתה בטלה כולה\u0004 ומדוע הגנב משלם כלל?","\u0003ואלא\u0004 תאמר \u0003אסיפא\u0004 \u0005[על סופה]\u0006 של הברייתא — הלא \u0003שפיר קאמרי רבנן\u0004 \u0005[יפה אמרו חכמים]:\u0006 \u0003הוא משלם תשלומי כפל, והם משלמין תשלומי שלשה!\u0004","\u0003אלא\u0004 צריך לומר כי \u0003מילתא אחריתי איכא בינייהו\u0004 \u0005[דבר אחר\u0006 נוסף \u0005יש ביניהם]\u0006 שאינו נזכר בדברי חכמים בברייתא, ובו נחלקו, והוא: \u0003כגון דאתו בי תרי אמרי ליה\u0004 \u0005[שבאו שנים\u0006 ו\u0005אמרו לו]\u0006 \u0003\"גנבת\", אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"אין\u0004 \u0005[כן],\u0006 \u0003גנבתי וטבחתי ומכרתי, מיהו\u0004 \u0005[אולם]\u0006 \u0003לא בפניכם גנבתי\".\u0004 \u0003ואייתי סהדי ואזמינהו\u0004 \u0005[והביא\u0006 הגנב \u0005עדים והזים אותם,\u0006 את העדים הראשונים\u0005]\u0006 והוזמו, שמדברי העדים האחרים נודע ש\u0003לא באפייהו\u0004 \u0005[בפניהם]\u0006 של הראשונים \u0003גנב\u0004 ומעתה אין לנו אלא הודאתו בלבד. \u0003ואייתי\u0004 \u0005[והביא]\u0006 \u0003בעל הבית\u0004 (בעל הבהמה) \u0003סהדי\u0004 \u0005[עדים]\u0006 אחרים \u0003ואסהידו ביה\u0004 \u0005[והעידו בו]\u0006 ש\u0003גנב וטבח ומכר.\u0004","\u0003ובהודאת\u0004 ה\u0003טביחה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 חכמים וסומכוס,","\u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003הודאה\u0004 של \u0003גניבה מחמת עדים הוא דקא מודה\u0004 \u0005[שמודה],\u0006 ולכן לדעתם הודאה כזאת אינה נחשבת הודאה כלל, מכל מקום \u0003הודאה\u0004 של \u0003טביחה\u0004 שהודה שלא מחמת העדים — \u0003הודאה היא, ופטור\u0004 מארבעה וחמישה למרות שלא חייב עצמו על ידה, ולמרות שבאו עדים אחר כך והעידוהו על כך.","\u0003וסומכוס סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון\u0004 ש\u0003הודאה\u0004 של \u0003גניבה מחמת עדים הוא דקא מודה\u0004 \u0005[שמודה],\u0006 ואין היא נחשבת כהודאה, לפיכך הודאה של \u0003טביחה\u0004 גם כן \u0003לאו\u0004 \u0005[לא]\u0006 \u0003הודאה\u0004 היא, שהרי לא חייב עצמו על ידה וכאילו לא הודה כלל. וכדברי רב המנונא ור' יוחנן.","\u0003ו\u0004משום כך, \u0003הנך עדים קמאי דאזמינהו\u0004 \u0005[אותם עדים ראשונים שהזים אותם]\u0006 אכן \u0003משלמין\u0004 לו \u0003תשלומי כפל,\u0004 כיון שהאשימוהו בגניבה שלא כדין והוזמו, \u0003והוא משלם\u0004 לבעלים כפל זה ועוד \u0003שלשה לפר ושנים לאיל,\u0004 כלומר, ארבעה וחמישה כיון שעל כך העידו עדים אחרים. ואם כן סבור רב המנונא כסומכוס, וחכמים חלוקים בדבר.","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: לא,\u0004 אין לומר כך, אלא יש לפרש כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 במקרה שאין ההודאה על הגניבה נחשבת כהודאה — \u0003הודאה\u0004 של \u0003טביחה לאו\u0004 \u0005[לא]\u0006 \u0003הודאה היא\u0004 ואף חכמים מסכימים בזה לדברי רב המנונא ור' יוחנן.","\u0003אלא\u0004 כאן \u0003בעדות שאי\u0004 (שאין) \u0003אתה יכול להזימה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 סומכוס וחכמים, שהמקרה כך היה: \u0003כגון דאתו סהדי ואמרי ליה\u0004 \u0005[שבאו עדים ואמרו לו]:\u0006 \u0003\"גנבת\", ואמר להו\u0004 \u0005[להם]\u0006 הגנב: \u0003\"\u0004אכן \u0003גנבתי וטבחתי ומכרתי, מיהו\u0004 \u0005[אולם]\u0006 \u0003לא בפניכם גנבתי אלא בפני פלוני ופלוני\".\u0004 \u0003ו\u0004אכן, \u0003אייתי סהדי ואזמינהו\u0004 \u0005[הביא\u0006 הגנב \u0005עדים\u0006 אחרים \u0005והזים אותם],\u0006 את אלה שהעידו כנגדו והוכיח ש\u0003לא באפייהו\u0004 \u0005[בפניהם]\u0006 \u0003גנב, ואתו\u0004 \u0005[ובאו]\u0006 איתם \u0003פלוני ופלוני\u0004 שהגנב עצמו נקב בשמם \u0003ואסהידו ביה\u0004 \u0005[והעידו בו]\u0006 ש\u0003גנב וטבח ומכר.\u0004","\u0003ובהא קמיפלגי\u0004 \u0005[וב\u0006נושא \u0005זה חלוקים\u0006 הם\u0005],\u0006 \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 אותה עדות אחרונה \u0003הויא לה\u0004 \u0005[הריהי]\u0006 \u0003עדות שאי אתה יכול להזימה,\u0004 שכיון שבאו על פי הודאתו, שוב אין מקום להזימם, \u0003וכל עדות שאי אתה יכול להזימה\u0004 — \u0003לא הויא\u0004 \u0005[אינה\u0006 נחשבת\u0005]\u0006 \u0003עדות.\u0004","\u0003וסומכוס סבר: עדות שאי אתה יכול להזימה הויא\u0004 \u0005[הריהי\u0006 נחשבת\u0005]\u0006 \u0003עדות\u0004 ולפיכך משלמים לו העדים הזוממים תשלומי כפל, והוא משלם כפל זה ועוד שלושה (או שנים) לבעלים על פי העדות האחרונה.","ושואלים: \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003עדות שאי אתה יכול להזימה לא הויא\u0004 \u0005[אינה]\u0006 \u0003עדות!\u0004 ומסבירים: יש לחלק, \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 כלל זה אמור \u0003היכא דלא ידעי\u0004 \u0005[במקום שאין\u0006 העדים \u0005יודעים]\u0006 \u0003באיזה יום באיזה שעה\u0004 היה הדבר, \u0003דליכא\u0004 \u0005[שאין כאן מקום]\u0006 \u0003לעדות כלל,\u0004 והרי זה פגם בעצם העדות, ומפני שאי אפשר להזים אותה בגלל שאין העדות כוללת נתוני זמן, ולא יוכלו עדים אחרים להזימה ולומר להם: \"עמנו הייתם באותו זמן במקום אחר\" — אינה נחשבת כעדות. \u0003אבל הכא סיועי\u0004 \u0005[כאן סיוע]\u0006 \u0003הוא דקא מסייעי ליה\u0004 \u0005[שמסייעים אותו\u0006 בעדותם\u0005]\u0006 ואף שאפשר לומר שאי אפשר להזימה (מפני הודאתו), מכל מקום אין זה משום פגם שבעדות, ואפשר לומר שמצד עצמה עדות ראויה היא. ומעירים כי לפירוש זה יש לברר פרט מסויים בדברי סומכוס.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 סומכוס באותה ברייתא: \u0003הן משלמין תשלומי כפל.\u0004 ותוהים: \u0003מדקא\u0004 \u0005[מאחר ש\u0006הוא עצמו\u0005]\u0006 \u0003מודה\u0004 ש\u0003גנב\u0004 אם כן \u0003קרן בעי שלומי\u0004 \u0005[צריך\u0006 הגנב \u0005לשלם],\u0006 ומדוע הם משלמים כפל הכולל גם את הקרן? \u0003אמר ר' אלעזר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב, תני\u0004 \u0005[שנה]:\u0006"],["\u0003תשלום\u0004 של \u0003כפל.\u0004 כלומר, הם משלמים לו בהמה אחת כנגד מה שרצו לחייבו בכפל, אבל הוא עצמו נותן את הקרן.","שנינו במשנה: \u0003גנב והקדיש ואחר כך טבח ומכר\u0004 — אינו חייב תשלומי ארבעה וחמישה על הטביחה והמכירה. ועל כך \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שעל ה\u0003טביחה\u0004 וכן על המכירה אחר ההקדש הוא \u0003לא מחייב\u0004 \u0005[מתחייב],\u0006 משום \u0003דכי קא טבח\u0004 \u0005[שכאשר הוא טובח]\u0006 — של ה\u0003הקדש קא טבח\u0004 \u0005[הוא טובח],\u0006 \u0003ולא\u0004 את \u0003דמריה קא טבח\u0004 \u0005[של בעליו הוא טובח].\u0006","\u0003אלא\u0004 על ה\u0003הקדש\u0004 עצמו שהקדש \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 ותהא פעולת ההקדש נחשבת כמכירה, שהרי \u0003מה לי מכרו להדיוט\u0004 שחייב על המכירה \u0003מה לי מכרו לשמים\u0004 על ידי הקדשה?","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: קדשים ש\u0004המקדיש אותם \u0003חייב באחריותן,\u0004 כלומר, שאם נגנבו או אבדו מבית הבעלים, הריהו חייב להביא קרבן אחר תחתיהם — \u0003ברשותיה דמריה קיימי\u0004 \u0005[ברשות בעליהם\u0006 עדיין הם \u0005עומדים]\u0006 ולכן אין עצם ההקדשה נחשב כמכירה של הבהמה, ובסוג כזה של הקדש עוסקת משנתנו.","ומקשים: \u0003הא מדסיפא\u0004 \u0005[הרי מ\u0006אחר \u0005שסופה\u0006 של המשנה\u0005]\u0006 הם דברי \u0003ר' שמעון, הוי\u0004 \u0005[הרי]\u0006 נראה כי \u0003רישא\u0004 \u0005[תחילתה]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 כשיטת \u0003ר' שמעון,\u0004 אלא שיטה אחרת!","\u0003אלא\u0004 יש לדחות תירוץ זה ולומר כך: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003ב\u0004מקרה שהקדישם הגנב לשם \u0003קדשים קלים\u0004 (כגון שלמים), \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יוסי הגלילי,\u0004 ש\u0003אמר: קדשים קלים ממון בעלים הוא, וברשותיה קיימי\u0004 \u0005[וברשותו\u0006 הם \u0005עומדים].\u0006","ועל כך מקשים: לדרך זו \u0003אבל\u0004 אם הגנב הקדישם לשם \u0003קדשי קדשים מאי\u0004 \u0005[מה]\u0006 יהא דינו? — \u0003משלם תשלומי ארבעה וחמשה\u0004 על הקדשתם כמו על מכירה, שאלו כבר אינם ממונו, אם כן, \u0003אדתני רישא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005תחילה]\u0006 במשנה קודמת (לעיל בבא קמא ע,א): \u0003גנב וטבח ואחר כך הקדיש\u0004 — \u0003משלם תשלומי ארבעה וחמשה, ליפלוג וליתני בדידה\u0004 \u0005[שיחלוק וישנה ב\u0006אותה פיסקה \u0005עצמה]\u0006 בפרטי הדין במשנה שלנו, כשהקדיש ואחר כך טבח ומכר, ויאמר כך:","\u0003במה דברים אמורים\u0004 שאינו משלם ארבעה וחמישה על שהקדיש את הבהמה שגנב — \u0003בקדשים קלים, אבל בקדשי קדשים\u0004 — \u0003משלם תשלומי ארבעה וחמשה\u0004 על הקדשתם!","\u0003אלא,\u0004 יש לדחות את מה שאמרנו, ו\u0003לעולם לא שנא\u0004 \u0005[שונה]\u0006 \u0003קדשי קדשים ולא שנא\u0004 \u0005[שונה]\u0006 \u0003קדשים קלים,\u0004 שעל עצם הקדשתם של אלו ושל אלו — פטור מתשלומי ארבעה וחמישה. \u0003ודקשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך: מה לי מכרו להדיוט מה לי מכרו לשמים,\u0004 שלכאורה העברת רשות לבעלים אחרים נחשבת למכירה ומה ההבדל ביניהם — יש לחלק: אם \u0003מכרו להדיוט\u0004 — \u0003מעיקרא תורא\u0004 \u0005[מתחילה\u0006 היה זה \u0005השור]\u0006 של \u0003ראובן\u0004 המוכר, \u0003והשתא תורא\u0004 \u0005[ועכשיו\u0006 הוא \u0005השור]\u0006 של \u0003שמעון\u0004 הקונה, אולם אם \u0003מכרו לשמים\u0004 כלומר, הקדישו — \u0003מעיקרא תורא\u0004 \u0005[מתחילה,\u0006 לפני שהקדישו, היה נקרא \u0005השור]\u0006 של \u0003ראובן\u0004 \u0003והשתא תורא\u0004 \u0005[ו\u0006גם \u0005עכשיו\u0006 הוא נקרא \u0005השור]\u0006 של \u0003ראובן,\u0004 שעל ידי ההקדש לא חדל להיקרא על שמו, אלא עדיין הוא מזוהה כקרבן שלו. ולכן אין דינו של ההקדש כמכירה לאדם אחר, ואינו חייב בתשלומי ארבעה וחמישה על ההקדשה.","שנינו במשנה ש\u0003ר' שמעון אומר:\u0004 קדשים שחייב באחריותם משלם תשלומי ארבעה וחמישה. \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה על שיטה זו: \u0003נהי דסבר\u0004 \u0005[אמנם שסבור]\u0006 \u0003ר' שמעון: מה לי מכרו להדיוט מה לי מכרו לשמים,\u0004 שעצם ההקדשה הריהי כמכירה, ואולם לסברה זו \u0003איפכא מיבעי ליה\u0004 \u0005[ההיפך היה צריך לו\u0006 לומר\u0005]:\u0006","\u0003קדשים שחייב באחריותן\u0004 — \u0003פטור\u0004 הגנב מתשלומי ארבעה וחמישה משום שבהקדשה \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003לא נפק מרשותיה\u0004 \u0005[יצאו מרשותו]\u0006 כמו במכירה, לעומת זאת,","\u0003קדשים שאינו חייב באחריותן\u0004 — \u0003חייב\u0004 הגנב, \u0003דמפקי ליה מרשותיה\u0004 \u0005[ש\u0006הרי בהקדשתו \u0005הוציאם\u0006 לגמרי \u0005מרשותו]\u0006 כאילו מכרם!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003ר' שמעון אמילתא אחריתי קאי\u0004 \u0005[על דבר אחר\u0006 הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006","\u0003והכי קתני\u0004 \u0005[וכך שנה]:\u0006 שעל מה ששנינו קודם (לעיל בבא קמא סב,ב) \u0003אין הגונב אחר הגנב משלם תשלומי ארבעה וחמשה,\u0004 יש להוסיף: \u0003וכן גונב הקדש מבית בעלים\u0004 — \u0003פטור,\u0004 ומסבירים:","\u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 מקור הדבר\u0005]?\u0006 — משום גזירת הכתוב, שנאמר בדינים אלו: \u0003\"וגנב מבית האיש\"\u0004 (שמות כב, ו) להדגיש: דווקא מבית האיש הפרטי — \u0003ולא מבית הקדש.\u0004","ועל כך \u0003ר' שמעון אומר:\u0004 הגונב \u0003קדשים ש\u0004המקדישם \u0003חייב באחריותן\u0004 וטבחם — \u0003חייב\u0004 הגנב עליהם ארבעה וחמישה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 — \u0003קרינא ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"וגנב מבית האיש\",\u0004 שכיון שלאחר שנגנב הבעלים חייבים להקדיש קרבן אחר נמצא שמחסר אותו ממון, ודבר הגורם לממון נחשב כממון. \u0003ושאינו חייב באחריותן\u0004 — \u0003פטור,\u0004 ש\u0003לא קרינן ביה\u0004 \u0005[קוראים אנו בו]\u0006 \u0003\"וגנב מבית האיש\",\u0004 שבהקדש זה אין עוד קשר ממוני בין בעל הקרבן והקרבן.","ולעצם שיטתו של ר' שמעון, המחייב תשלומי ארבעה וחמישה על טביחה של קדשים, שואלים: \u0003מכדי שמעינן ליה\u0004 \u0005[הלא שמענו אותו]\u0006 את \u0003ר' שמעון,\u0004 ש\u0003אמר: שחיטה שאינה ראויה\u0004 שאינה מכשרת את הבשר לאכילה \u0003לא שמה\u0004 (אינה נחשבת) \u0003שחיטה\u0004 לכל ענין שבו שייך דין שחיטה, ומשום כך פטר במשנה לעיל (בבא קמא ע,א) את השוחט טריפה מתשלומי ארבעה וחמישה. אם כן, שחיטת \u0003קדשים נמי\u0004 \u0005[גם כן]\u0006 \u0003שחיטה שאינה ראויה היא,\u0004 שהרי אם שחט קדשים מחוץ למקדש נפסלו ואסורים בהנאה!","ומשיבים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 שמדובר כאן \u0003ב\u0004גנב ה\u0003שוחט\u0004 קרבנות \u0003תמימים\u0004 (שאינם בעלי מום, כלומר, כשרים להקרבה) \u0003מבפנים\u0004 במקדש עצמו, כלומר, במקום הראוי, ושוחט אותם \u0003לשם בעלים\u0004 הראשונים והרי זו שחיטה הראויה.","\u0003ו\u0004תוהים על כך: אם כך \u0003הרי חזרה קרן לבעלים\u0004 ונמצא שלא נגנב דבר מהם, שהרי הוקרב הקרבן לשם בעליו הראשון כפי שהיה צריך לעשות, ומדוע יתחייב הגנב? \u0003אמר ר' יצחק בר אבין:\u0004 מדובר באופן \u0003שנשפך הדם,\u0004 שאירעה תקלה בקרבן, שלא נזרק הדם ולא כיפר הקרבן על בעליו, ואולם הגנב עצמו בשעת שחיטה שחט את הקרבן כראוי לו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 הסבר אחר לשיטת ר' שמעון: כאן מדובר \u0003בשוחט\u0004 קרבנות \u0003תמימים בפנים\u0004 אלא \u0003שלא לשם בעלים\u0004 הראשונים. שאמנם הקרבן כשר ומותר והרי זו שחיטה ראויה, אלא שלא יצאו בו הבעלים ידי חובתם, ואם כן לא חזרה קרן לבעלים."],["\u0003וריש לקיש אמר\u0004 הסבר אחר בשיטת ר' שמעון: מדובר כאן \u0003ב\u0004גנב ה\u0003שוחט\u0004 קרבנות \u0003בעלי מומין\u0004 ושחטם \u0003בחוץ,\u0004 שכיון שהם בעלי מומים אינם עוד קדשים, ושחיטתם בחוץ מתירתם באכילה.","\u0003תהי\u0004 \u0005[תהה]\u0006 \u0003בה\u0004 בשמועה זו כולה \u0003ר' אלעזר: ל\u0004דעת \u0003ר' יוחנן\u0004 יש להקשות: וכי \u0003שחיטה מתרת\u0004 את הקרבן? \u0003והלא\u0004 ה\u0003זריקה\u0004 של הדם על המזבח היא ה\u0003מתרת!\u0004 ואם נשפך הדם ולא נזרק נמצא שלא הותר הקרבן על ידי שחיטתו, ונמצא שהיתה זו שחיטה שאינה ראויה.","וכן \u0003ל\u0004דעת \u0003ריש לקיש\u0004 יש לתהות: וכי \u0003שחיטה מתרת\u0004 קרבנות בעלי המומים להיאכל בחוץ? \u0003והלא פדייה מתרת,\u0004 וכאן לא נעשתה פדייה!","ומעירים: \u0003אישתמיטתיה\u0004 \u0005[נשמט ממנו,\u0006 שכח\u0005]\u0006 ר' אלעזר \u0003הא\u0004 \u0005[\u0006כלל \u0005זה]\u0006 שקבע \u0003ר' שמעון: כל\u0004 דם קרבנות \u0003העומד לזרוק\u0004 וראוי לזריקה — \u0003כזרוק\u0004 כבר \u0003דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ואף שלא נזרק בפועל — אין זה משנה את דינו של הקרבן, והריהו מותר, \u0003ו\u0004כן \u0003כל\u0004 קרבן בעל מום \u0003העומד לפדות\u0004 — \u0003כפדוי\u0004 כבר \u0003דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","ומקור לדברים אלה: \u0003כל העומד לזרוק כזרוק דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון אומר\u0004 שדבר מאכל האסור בהנאה אין דינו כאוכל, ואינו מטמא טומאת אוכלים, ובכל זאת, \u0003יש\u0004 קרבן \u0003נותר\u0004 (שלא נאכל בתוך הזמן המותר לאכילתו ונאסר בהנאה), \u0003שהוא מטמא טומאת אוכלין, ויש נותר שאינו מטמא טומאת אוכלין,\u0004","\u0003כיצד?\u0004 — אם \u0003לן\u0004 בשר הקרבן יותר מהזמן הראוי לו \u0003לפני זריקה\u0004 של דם הקרבן — \u0003אינו מטמא טומאת אוכלין,\u0004 שכיון שלא נזרק דמו לא הוכשר כלל הבשר באכילה עד שנאסר. ואולם אם לן הבשר \u0003לאחר זריקת\u0004 הדם, שהוקרב הקרבן כדינו — \u0003מטמא טומאת אוכלין.\u0004","\u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 שכך יש לפרש את דברי ר' שמעון: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לפני זריקה\"\u0004 — הכוונה: \u0003קודם שנראה\u0004 (שהיה ראוי) \u0003לזריקה. \"לאחר זריקה\"\u0004 כוונתו: \u0003לאחר שנראה לזריקה.\u0004","\u0003קודם שנראה לזריקה לן מאי היא\u0004 \u0005[מה הוא]\u0006 כיצד יכול להיות דבר זה — כגון ש\u0003לא הויא\u0004 \u0005[היתה]\u0006 \u0003שהות ביום למזרקיה\u0004 \u0005[לזרוק אותו],\u0006 \u0003דשחטיה\u0004 \u0005[ששחטו]\u0006 \u0003סמוך לשקיעת החמה,\u0004 \u0003ו\u0004משום כך \u0003אינו מטמא טומאת אוכלין\u0004 שהרי לא היה נחשב כאוכל מעיקרו.","אם \u0003לאחר שנראה לזריקה לן, דהויא\u0004 \u0005[שהיתה]\u0006 \u0003שהות ביום למזרקיה\u0004 \u0005[לזרוק אותו]\u0006 — \u0003מטמא טומאת אוכלין. אלמא\u0004 \u0005[מכאן]\u0006 נסיק שלדעת ר' שמעון: \u0003כל העומד לזרוק כזרוק\u0004 כבר \u0003דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006","\u0003ו\u0004מנין שר' שמעון סבור גם כן ש\u0003כל העומד לפדות כפדוי\u0004 כבר \u0003דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004"],["בשר \u0003פרה\u0004 אדומה \u0003מטמא טומאת אוכלין\u0004 לאחר שנשחטה, אף על פי שלא נשחטה מתחילתה לצורך אוכל, \u0003הואיל והיתה לה שעת הכושר,\u0004 שהיתה שעה מסויימת שבה היתה ראויה פרה זו להיאכל לאחר שנשחטה."],["\u0003ואמר ריש לקיש\u0004 בהסבר שיטת ר' שמעון: מדברים אלו יש ללמוד כי \u0003אומר היה ר' שמעון: פרה\u0004 אדומה \u0003נפדית\u0004 אפילו היא \u0003על גבי מערכתה,\u0004 שאפילו לאחר שנשחטה והיתה כבר מונחת על גבי מערכת העצים שהכינו לה כדי לשורפה — אפשר לפדותה. וזו היא שעת הכושר של הפרה להיות מותרת באכילה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003כל העומד לפדות כפדוי\u0004 כבר \u0003דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 שהרי אף שלא נפדתה הפרה האדומה בפועל, כיון שראויה היתה להיפדות אמר ר' שמעון שהיתה לה שעת הכושר לאכילה. ומשום כך שחיטת בעלי מומים בחוץ — שחיטה ראויה היא, שהרי עומדים הם לפדייה, ולכן מחייב ר' שמעון באלו תשלומי ארבעה וחמישה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003ר' יוחנן לא אמר\u0004 ופירש את דברי ר' שמעון \u0003כר' שמעון בן לקיש,\u0004 משום \u0003דקא בעי לאוקמה למתניתין\u0004 \u0005[שרוצה להעמיד,\u0006 להסביר, \u0005את משנתנו]\u0006 \u0003אפילו ב\u0004קרבנות \u0003תמימין, אלא ריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה\u0006 ריש לקיש \u0005לומר]\u0006 \u0003לך:\u0004 נאמר בענין תשלומי ארבעה וחמישה: \u0003\"וטבחו\u0004 או \u0003מכרו\"\u0004 (שמות כא, לז), השוה הכתוב את הדברים, ללמדנו: \u0003כל היכא דאיתיה\u0004 \u0005[היכן\u0006 במקום \u0005שישנו]\u0006 \u0003ב\u0004דין \u0003מכירה\u0004 שמשלם ארבעה וחמישה — \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003ב\u0004דין \u0003טביחה\u0004 לשלם ארבעה וחמישה, \u0003וכל היכא דליתיה\u0004 \u0005[היכן שאינו]\u0006 \u0003במכירה\u0004 — \u0003ליתיה\u0004 \u0005[אינו]\u0006 \u0003בטביחה. ו\u0004לכן \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003קדשים הואיל דכי מזבין\u0004 \u0005[שכאשר\u0006 הוא \u0005מוכר]\u0006 \u0003קדשים\u0004 תמימים \u0003לא הויא\u0004 \u0005[אין היא]\u0006 \u0003מכירה,\u0004 שהרי אין אפשרות לקנות בהמת קדשים תמימה, אף \u0003ליתנהו\u0004 \u0005[אינם]\u0006 \u0003ב\u0004דין \u0003טביחה,\u0004 ולכן היה צריך לפרש שמדובר בבעלי מומים, שאלה ניתנים למכירה, ובאלה יש גם דין טביחה.","ומעירים: \u0003ואזדו לטעמייהו\u0004 \u0005[והלכו\u0006 ר' יוחנן וריש לקיש \u0005לטעמם,\u0006 לשיטתם\u0005]\u0006 בנושא דומה. \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בענין גנב \u0003המוכר\u0004 בהמה שהיא \u0003טריפה, לדברי ר' שמעון\u0004 שפוטר על טביחתה מתשלומי ארבעה וחמישה. \u0003ר' יוחנן אמר: חייב\u0004 בתשלומי ארבעה וחמישה על מכירתה, \u0003וריש לקיש אמר: פטור.\u0004","ומסבירים את השיטות: \u0003ר' יוחנן אמר: חייב, אף על גב דליתיה\u0004 \u0005[אף על פי שאינו]\u0006 \u0003ב\u0004דין \u0003טביחה\u0004 שהרי טריפה היא, ואין שחיטתה מכשרתה, ולדעת ר' שמעון שחיטה שאינה ראויה אינה נחשבת שחיטה — מכל מקום \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003ב\u0004דין \u0003מכירה\u0004 לשלם ארבעה וחמישה, שהרי חלה המכירה. \u0003וריש לקיש אמר: פטור, כיון דליתיה\u0004 \u0005[שאינו]\u0006 \u0003בטביחה\u0004 אף \u0003ליתיה\u0004 \u0005[אינו]\u0006 \u0003במכירה.\u0004 שרק בהמה שנגנבה שיש אפשרות לעשות בה גם פעולה זו וגם פעולה זו יש בה קנס ארבעה וחמישה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש\u0004 ממה ששנינו בברייתא זו: \u0003גנב\u0004 בהמת \u0003כלאים\u0004 (שנולדה מהכלאת כבש ועז, שאינה ממש \"שה\") \u0003וטבחה,\u0004 או גנב בהמה \u0003טריפה ומכרה\u0004 — \u0003משלם תשלומי ארבעה וחמשה. מאי לאו\u0004 \u0005[האם לא]\u0006 שיטת ברייתא זו כשיטת \u0003ר' שמעון היא, אלמא\u0004 \u0005[מכאן]\u0006 ממקרה זה של טריפה נלמד ש\u0003אף על גב דליתיה\u0004 \u0005[אף על פי שאינו]\u0006 \u0003בטביחה איתיה\u0004 \u0005[ישנו]\u0006 \u0003במכירה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש בתשובה: \u0003לא,\u0004 ברייתא זו אינה כשיטת ר' שמעון אלא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא.","והקשה לו ר' יוחנן: \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים]\u0006 היא, וכי \u0003טריפה\u0004 שמפורשת בברייתא \u0003במכירה איתא\u0004 \u0005[ישנה],\u0006 \u0003בזביחה\u0004 (שחיטה) \u0003ליתא\u0004 \u0005[אינה]?\u0006 הרי לשיטת חכמים גם שחיטה שאינה ראויה שמה שחיטה, וחייב עליה!","ודחה ריש לקיש: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר, שזו שיטת \u0003ר' שמעון?\u0004 הלא גם לשיטתו אפשר לשאול שאלה זו: וכי \u0003כלאים,\u0004 שמפורשת בברייתא \u0003בטביחה איתא\u0004 \u0005[ישנה],\u0006 \u0003במכירה ליתא\u0004 \u0005[אינה]?\u0006 והלא אין הבדל בין זה לזה!","\u0003אלא\u0004 אין להבין את דברי הברייתא בדרך של דיוק, ויש להסביר אף לשיטתך כי \u0003תנא\u0004 \u0005[שנה]\u0006 החכם בענין כלאים \u0003טביחה, והוא הדין למכירה.\u0004 אם כן, \u0003אימא לרבנן נמי\u0004 \u0005[אמור ל\u0006דעת \u0005חכמים גם כן],\u0006 כך יש לפרש את הברייתא, ובאופן ש\u0003תנא\u0004 \u0005[שנה]\u0006 בענין טריפה \u0003מכירה והוא הדין לטביחה. ו\u0004בתשובה לכך","\u0003ר' יוחנן אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: האי מאי\u0004 \u0005[\u0006הסבר \u0005זה, מה\u0006 הוא\u0005]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שהברייתא כדעת \u0003ר' שמעון,\u0004 אזי יכול אני לומר בברייתא \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003טריפה בחדא\u0004 \u0005[ב\u0006דין \u0005אחד]\u0006 של מכירה, שהרי לדעתו אינה בדין טביחה, שאין זו שחיטה ראויה — \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003כלאים בחדא\u0004 \u0005[ב\u0006דין \u0005אחד]\u0006 של טביחה, אף שישנם גם במכירה, שכך היא דרך הברייתות.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהוא כדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003נערבינהו וניתנינהו\u0004 \u0005[שיערבם וישנה אותם,\u0006 את שני המקרים\u0005]\u0006 ביחד, כך: \u0003גנב כלאים וטריפה, טבחן ומכרן\u0004 — \u0003משלם תשלומי ארבעה וחמשה!\u0004 ומעירים: אכן, זה \u0003קשיא\u0004 \u0005[קשה]\u0006 לריש לקיש.","ומבררים עתה עיקרה של הלכה זו שנזכרה בברייתא: מדוע יהא דין זה של תשלומי ארבעה וחמישה ב\u0003כלאים?\u0004 הלא \u0003\"שה\" כתיב\u0004 \u0005[נאמר]\u0006 בפרשה זו (שמות כא, לז), \u0003ואמר רבא:\u0004 הכתוב בענין בהמות הכשרות לאכילה \"שה כשבים ושה עיזים\" (דברים יד, ד) \u0003זה בנה\u0004 (בנין) \u0003אב:\u0004 כלומר, מה שנתפרש בו הוא המקור להלכות רבות אחרות: \u0003כל מקום שנאמר\u0004 בתורה \u0003\"שה\", אינו\u0004 בא \u0003אלא להוציא\u0004 (למעט) \u0003את הכלאים\u0004 ולומר שאינם בכלל אותו ענין, וכיון שבדין תשלומי ארבעה וחמישה על טביחה ומכירה נאמר גם כן \"שה\", יש לומר שבא הכתוב להוציא את הכלאים!","ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דאמר קרא\u0004 \u0005[שאומר הכתוב]\u0006 \u0003\"או\"\u0004 (\"שור או שה\") — \u0003לרבות את הכלאים.\u0004","ושואלים: \u0003ו\u0004האם \u0003כל \"או\"\u0004 שבכתוב \u0003לרבות הוא? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בכשרים לקרבן \u0003\"שור או כשב\u0004 או עז... ירצה לקרבן אשה לה'\u0003\"\u0004 (ויקרא כב, כז), דרשו: \"או\" שנאמר במילים \"שור או כשב\" בא ללמד: \u0003פרט לכלאים, \"או עז\"\u0004 (ויקרא כב, כז) — \u0003פרט לנדמה,\u0004 לבעל חיים שאינו דומה לאביו ואמו, הרי ש\"או\" בא למעט ולא לרבות!","\u0003אמר רבא:\u0004 אף ש\"או\" מיעוט הוא בדרך כלל, אין לקבוע כלל בדבר, אלא \u0003הכא מענייניה דקרא, והכא מענייניה דקרא\u0004 \u0005[כאן מעניינו של הכתוב, וכאן מעניינו של הכתוב].\u0006 \u0003הכא\u0004 ל\u0003גבי\u0004 \u0005[כאן אצל]\u0006 \u0003גניבה, דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"שור או שה\",\u0004 והרי אלו בעלי חיים \u0003שאי\u0004 (שאין) \u0003אתה יכול להוציא כלאים מביניהם,\u0004 שאי אפשר שיוולד ולד כלאים משור ושה, ואי אפשר להבין \"או\" זה כממעט כלאים — יש להבין שהמילה \u0003\"או\"\u0004 באה \u0003לרבות כלאים\u0004 (של שה ועז), ואילו ל\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003קדשים דכתיב\u0004 \u0005[שנאמר]\u0006 בהם: \u0003\"כשב ו\"עז\"\u0004 (\"כשב או עז), \u0003שאתה יכול להוציא כלאים מביניהם\u0004 מהכלאת כשב ועז, הביטוי \u0003\"או\" למעט הוא.\u0004"],["ומקשים על הכלל הזה: \u0003והא גבי\u0004 \u0005[והרי אצל]\u0006 \u0003קדשים,\u0004 כלומר, בדין הכשרים לקרבנות \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003נאמר \"שור או כשב\"\u0004 (יקרא כב, כז), \u0003שאין אתה יכול להוציא כלאים מביניהם, ונרבי\u0004 \u0005[ונרבה]\u0006 גם שם את הכלאים והרי אלה מינים שכשרים להקריב! ומשיבים: \u0003מדסיפא\u0004 \u0005[מ\u0006כיון \u0005ש\u0006ב\u0005סופו\u0006 של אותו כתוב\u0005]\u0006 בא ה\"או\" \u0003למעט\u0004 (\"כשב או עז\"), שהרי שם אפשר להוציא כלאים מביניהם — \u0003רישא נמי\u0004 \u0005[\u0006ב\u0005ראשו גם כן]\u0006 בא ה\"או\" \u0003למעט.\u0004 ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 נאמר: \u0003מדרישא\u0004 \u0005[מ\u0006כיון \u0005ש\u0006ב\u0005ראשו]\u0006 בא \u0003לרבות, סיפא נמי\u0004 \u0005[\u0006ב\u0005סופו גם כן]\u0006 בא \u0003לרבות!\u0004","על קושיה זו תוהים: \u0003האי מאי\u0004 \u0005[זו מה\u0006 טענה היא\u0005]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\"או\" בא \u0003למעט,\u0004 אם כן \u0003הוא\u0004 הטעם \u0003דאיצטריך תרי מיעוטי\u0004 \u0005[שהוצרכו שני מיעוטים]\u0006 כלאים ונדמה, \u0003דאף על גב דאימעט\u0004 \u0005[שאף על פי ש\u0006כבר \u0005התמעט]\u0006 \u0003כלאים, איצטריך\u0004 \u0005[הוצרך]\u0006 מיעוט נוסף \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003נדמה,\u0004 לומר שפסול למרות שהוא מאותו מין עצמו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\"או\" בא \u0003לרבות\u0004 כלאים ונדמה, \u0003תרי ריבויי\u0004 \u0005[שני ריבויים]\u0006 אלה \u0003למה? השתא\u0004 \u0005[עכשיו\u0006 הרי\u0005]\u0006 \u0003כלאים אירבי ליה\u0004 \u0005[התרבה לו]\u0006 להכשירו לקרבן, \u0003נדמה מבעיא\u0004 \u0005[נצרכה]\u0006 ללימוד נוסף שהוא גם כן כשר?","ושואלים: אם כן, \u0003אלא הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רבא\u0004 ככלל: \u0003זה בנה\u0004 (בנין) \u0003אב,\u0004 שזהו המקור להלכות אחרות: \u0003כל מקום שנאמר \"שה\" אינו אלא להוציא את הכלאים, למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 הוא נאמר? שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003קדשים, בהדיא כתיב בהו\u0004 \u0005[במפורש נאמר בהם]\u0006 \u0003\"שור או כשב\u0004 או עז\u0003\"\u0004 (יקרא כב, כז) ולמדנו מכאן \u0003פרט לכלאים!\u0004","\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003מעשר\u0004 בהמה, שלא ניתן להפריש כלאים — הלא בגזירה שווה של המילים \u0003\"תחת\" \"תחת\"\u0004 (יקרא כב, כז, כז, לב) \u0003יליף\u0004 \u0005[למד]\u0006 \u0003מקדשים!\u0004","\u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004ענין \u0003בכור,\u0004 שכלאים שאינו קדוש בבכורה, הלא בגזירה שווה של \u0003\"העברה\" \"העברה\"\u0004 (\"והעברת כל פטר רחם\". שמות יג, יב. \"כל אשר יעבור\". ויקרא כז, לב) \u0003יליף\u0004 \u0005[למד]\u0006 \u0003ממעשר!\u0004","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר להוכיח הלכה זו בבכור בדרך אחרת: אם לענין בכור שהוא \u0003נדמה אמרת\u0004 \u0005[אומר אתה]\u0006 שהוא \u0003לא\u0004 קדוש בבכורה, משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך בכור שור\"\u0004 (במדבר יח, יז) ולמדו מכאן: \u0003עד שיהא הוא שור ובכורו שור,\u0004 ואין וולד השור מתקדש בבכורה אם אינו דומה לאביו השור, וכי \u0003כלאים מבעיא\u0004 \u0005[נצרכה]\u0006 לומר שאינו קדוש בקדושת בכור?","\u0003אלא, כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 דבריו של \u0003רבא\u0004 הם \u0003לענין\u0004 פדיון \u0003פטר חמור\u0004 שציותה התורה לפדותו בשה, \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין פודין\u0004 פטר חמור \u0003לא בעגל ולא בחיה\u0004 כגון צבי ואיל, \u0003ולא ב\u0004בהמה \u0003שחוטה ולא בטריפה\u0004 אף אם היה זה כבש, \u0003ולא בכלאים\u0004 של תיש ורחל, ששניהם מין שה, \u0003ולא בכוי.\u0004","ושואלים: \u0003ול\u0004שיטת \u0003ר' אלעזר\u0004 ש\u0003מתיר\u0004 לפדות פטר חמור \u0003בכלאים\u0004 הבא משני מיני שה, ד\u0003תנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' אלעזר מתיר בכלאים מפני שהוא שה, למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 אמר רבא את כללו?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' אלעזר: כי איתמר\u0004 \u0005[כאשר נאמר]\u0006 כלל זה של \u0003רבא\u0004 הרי זה \u0003ל\u0004ענין איסור אכילה של בעל חיים \u0003טמא שנולד מן הטהור ועיבורו מן הטמא,\u0004 כגון רחל שנתעברה מבעל חיים טמא, לומר שהוולד הנולד להם אסור באכילה. ומעירים: \u0003ו\u0004דבר זה הוא ש\u0003לא כ\u0004שיטת \u0003ר' יהושע\u0004 במסכת בכורות, \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יהושע\u0004 — דין זה \u0003מ\u0004הפסוק \u0003\"\u0004זאת הבהמה אשר תאכלו, שור \u0003שה כשבים ושה עזים\"\u0004 (דברים יד, ד) \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 הדבר, שמלשון הרבים של \"כשבים\" (כבשים) הוא לומד שאין הוולד מותר באכילה כלל \u0003עד\u0004 \u0003שיהא אביו כבש ואמו כבשה,\u0004 כלומר, בעלי חיים טהורים.","לגופו של תירוץ זה שואלים: \u0003ו\u0004בהמה \u0003טהורה מטמאה מי מיעברא\u0004 \u0005[האם\u0006 היא כלל \u0005מתעברת],\u0006 הלא שני מינים אלה נבדלים לגמרי, ואיך אפשר שיהיו כלאים מביניהם? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006"],["\u0003דאיעבר\u0004 \u0005[שהתעברה]\u0006 הבהמה הטהורה \u0003מקלוט,\u0004 מוולד שנולד לבעל חיים טהור, שפרסותיו לא היו סדוקות אלא שלימות כבהמה טמאה. ושיטת ר' יהושע בזה היא \u0003כ\u0004שיטת \u0003ר' שמעון\u0004 הסבור שבהמה כזו היא טמאה.","ועתה שבים לדון בשיטת ר' שמעון במשנה, שהגונב קדשים שחייב באחריותם מבית הבעלים — חייב. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: מי שנדר ואמר \u0003\"הרי עלי עולה\", והפריש שור\u0004 לקרבן זה, \u0003ובא אחר וגנב\u0004 את השור, \u0003מי פטר\u0004 \u0005[האם פוטר]\u0006 ה\u0003גנב נפשיה\u0004 \u0005[את עצמו]\u0006 \u0003בכבש לרבנן\u0004 \u0005[לחכמים]\u0006 שיחזיר כבש לבעלים, שהרי יכול לצאת ידי חובת נדרו גם בכבש לעולה, או שיפטור עצמו \u0003בעולת העוף ל\u0004דעת \u0003ר' אלעזר בן עזריה? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 מי שאמר סתם \u0003\"הרי עלי עולה\"\u0004 — \u0003יביא כבש, ר' אלעזר בן עזריה אומר: יביא תור או בן יונה.\u0004","ואם כן לענין שאלתנו, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003שם\u0004 (מושג) \u0003עולה קביל עילויה\u0004 \u0005[קיבל עליו]\u0006 בנדרו, ולכן יכול הגנב לומר לו: עולה אני משלם לך, אף אם אין זה שור כמו שנגנב, \u0003או דלמא מצי אמר ליה\u0004 \u0005[שמא יכול לומר לו]\u0006 מקדיש הקרבן לגנב: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003מצוה מן המובחר בעינא למיעבד\u0004 \u0005[רוצה אני לעשות]\u0006 ולכן גם הפרשתי שור לקרבן, ואף אתה החזר שור?","\u0003בתר דאיבעיא הדר פשט\u0004 \u0005[אחר ששאל\u0006 רבא את השאלה \u0005חזר\u0006 הוא עצמו ו\u0005פתרה]:\u0006 \u0003גנב\u0004 שגנב שור שהופרש לעולה \u0003פטר\u0004 \u0005[פוטר]\u0006 \u0003עצמו בכבש ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003בעולת העוף ל\u0004דעת \u0003ר' אלעזר בן עזריה.\u0004","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא מתני לה בהדיא\u0004 \u0005[היה שונה את הדבר הזה במישרין]\u0006 שלא בדרך קושיה ותירוץ אלא כפסק הלכה, \u0003אמר רבא:\u0004 אמר אדם \u0003\"הרי עלי עולה\" והפריש שור, ובא אחר וגנבו\u0004 — \u0003פטר עצמו\u0004 הגנב \u0003בכבש ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003ובעולת העוף ל\u0004דעת \u0003ר' אלעזר בן עזריה.\u0004","מי שגנב כבש או שור ו\u0003מכרו\u0004 לא את כולו, אלא אפילו \u0003חוץ מאחד ממאה שבו, או שהיתה לו בו\u0004 בדבר הגנוב \u0003שותפות\u0004 כל שהיא, ונמצא שלא מכר את כולו בעבירה — פטור מתשלומי ארבעה וחמישה. וכן \u0003השוחט\u0004 את הבהמה הגנובה \u0003ונתנבלה בידו,\u0004 ששחטה באופן שנעשתה נבילה, וכן \u0003הנוחר\u0004 (שהרג את הבהמה באופן אחר שלא כדרך שחיטה), \u0003ו\u0004כן \u0003המעקר\u0004 (שעקר את הקנה והוושט ממנה) — \u0003משלם תשלומי כפל\u0004 על הגניבה, \u0003ו\u0004אולם \u0003אינו משלם תשלומי ארבעה וחמשה,\u0004 לפי שהריגה כזו אינה בגדר טביחה (שחיטה) כלל.","ומבררים את הנאמר במשנה: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חוץ מאחד ממאה שבו\",\u0004 שאם לא מכר אף אותו הריהו פטור מתשלומי ארבעה וחמישה על המכירה? \u0003אמר רב: חוץ מדבר הניתר עמו בשחיטה,\u0004 כלומר, שהתנה שחלק מסויים מגופה, שהוא מותר באכילה על ידי שחיטה, אותו הוא משאיר לעצמו. אבל אין הדבר כן אם שייר לעצמו במכירה דבר שמותר בהנאה בלא שחיטה, כגון צמרה שאינו צריך לשחיטה להתירו. \u0003ולוי אמר:\u0004 הכוונה אפילו אם שייר לעצמו באופן שמכר \u0003חוץ מגיזותיה\u0004 (צמרה). \u0003וכן תניא במתניתא\u0004 \u0005[שנויה\u0006 בברייתא\u0005]\u0006 במפורש: \u0003\"\u0004מכרו \u0003חוץ מגיזותיה\"\u0004 (במקום \"חוץ ממאה שבו\").","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב ממה ששנינו בברייתא: \u0003מכרה\u0004 הגנב \u0003חוץ מידה, חוץ מרגלה, חוץ מקרנה, חוץ מגיזותיה\u0004 — \u0003אינו משלם תשלומי ארבעה וחמשה. רבי אומר:\u0004 אם שייר הגנב \u0003דבר המעכב בשחיטה\u0004 שאם יינטל מגוף הבהמה לא תועיל שחיטה להכשירה לאכילה — \u0003אינו משלם תשלומי ארבעה וחמשה,\u0004","\u0003ו\u0004אולם חלק בבהמה \u0003שאינו מעכב בשחיטה\u0004 אם ניטל ממנה בחייה — \u0003משלם תשלומי ארבעה וחמשה.\u0004","\u0003ר' שמעון בן אלעזר אומר:\u0004 מכרה \u0003חוץ מקרנה\u0004 — \u0003אינו משלם תשלומי ארבעה וחמשה\u0004 שהוא חלק ממנה, \u0003חוץ מגיזותיה\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטתו של \u0003לוי\u0004 הוא סבור \u0003כ\u0004דברי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 בפשטות, \u0003אלא ל\u0004שיטת \u0003רב כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר? הלא אינו הולך לפי אחת משיטות אלה!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003רב דאמר כי האי תנא\u0004 \u0005[אומר כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר: מכרה חוץ מידה וחוץ מרגלה\u0004 — \u0003אינו משלם תשלומי ארבעה וחמשה.\u0004 ואולם אם מכרה \u0003חוץ מקרנה\u0004 או \u0003חוץ מגיזותיה\u0004 — \u0003משלם תשלומי ארבעה וחמשה,\u0004 והוא כשיטת רב.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזו סברה, \u0005חלוקים]\u0006 תנאים אלה? ומסבירים: ה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי יש ללמוד מהשוואת הביטויים, שכן נאמר \"וטבחו או מכרו\" (שמות כא, לז) והשוואה זו מלמדת: כשם ש\u0003\"וטבחו\"\u0004 \u0003כולו בעינן\u0004 \u0005[צריכים אנו],\u0006 כדי לחייבו ארבעה וחמישה, שהרי לא יתכן שטובח רק מקצתו, אף \u0003מכרו כולו בעינן\u0004 \u0005[צריכים אנו],\u0006 כדי לחייבו ארבעה וחמישה, ובכלל זה אף גיזותיה צריכים להימכר.","\u0003ורבי סבר\u0004 \u0005[סבור]:\u0006 \u0003\"וטבחו\"\u0004 כוונתו: \u0003מידי דהוי\u0004 \u0005[דבר שהריהו\u0006 ישנו\u0005]\u0006 בכלל הצורך \u0003בטביחה\u0004 כדי להתירו, \u0003לאפוקי מידי דלא הויא\u0004 \u0005[להוציא דבר שאינו]\u0006 צריך היתר \u0003בטביחה,\u0004 כמו כן \u0003\"ומכרו\"\u0004 שאמר הכתוב הוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003טביחה,\u0004 שכל דבר הניתר בטביחה הוא זה שמעכב במכירה.","\u0003ור' שמעון בן אלעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003קרנא דלא למגזא קיימא\u0004 \u0005[הקרן שאינה עומדת להיגזז]\u0006 ואם כן היא חלק בלתי נפרד מגוף הבהמה, \u0003הוי\u0004 \u0005[הריהי]\u0006 \u0003שיור, ואינו משלם תשלום ארבעה וחמשה\u0004 אם עכבה בידו. ואילו \u0003גיזותיה דלמיגז קיימי\u0004 \u0005[שלגזיזה\u0006 הן \u0005עומדות]\u0006 \u0003לא הוי\u0004 \u0005[אינן]\u0006 \u0003שיור, ומשלם תשלום ארבעה וחמשה\u0004 אם עכבן הגנב לעצמו.","\u0003ואידך תנא\u0004 \u0005[והתנא האחר]\u0006 \u0003דבי\u0004 \u0005[שמבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון בן אלעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003ידיו ורגליו דצריכי\u0004 \u0005[שצריכות]\u0006 \u0003טביחה\u0004 כדי להתירן, אם שיירן לעצמו — \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003שיור, ולא משלם תשלומי ארבעה וחמשה, קרניה וגיזותיה\u0004 ש\u0003לא צריכי\u0004 \u0005[צריכות]\u0006 \u0003טביחה\u0004 כדי להתירן, שיכול להשתמש בהן גם לפני ששחט — \u0003לא הוי\u0004 \u0005[אינן]\u0006 \u0003שיור.\u0004","ומעירים: מכל מקום \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003מ\u0004דברי \u0003ר' שמעון בן אלעזר\u0004 בברייתא אחת על דברי \u0003ר' שמעון בן אלעזר\u0004 בברייתא האחרת, שהרי אין שיטתו בשתי הברייתות זהה! ומשיבים: יש לומר כי יש כאן \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 שנחלקו \u0003ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' שמעון בן אלעזר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הגונב\u0004 את הבהמה \u0003הקיטעת\u0004 חסרת רגל \u0003ואת החיגרת\u0004 חסרת יד \u0003ואת הסומא\u0004 וטבחה או מכרה, \u0003וכן הגונב בהמת השותפין\u0004 וטבחה או מכרה — \u0003חייב\u0004 בתשלומי ארבעה וחמישה, \u0003ושותפים שגנבו\u0004 וטבחו או מכרו — \u0003פטורים.\u0004 ותוהים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003שותפין שגנבו\u0004 וטבחו או מכרו — \u0003חייבין!\u0004","\u0003אמר רב נחמן, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 וכך יש לתרץ: \u0003כאן\u0004 ששנינו שפטורים מדובר \u0003בשותף שגנב מחבירו,\u0004 שכיון שגם לו יש בעלות בחפץ אינו מתחייב, שהרי לא טבח או מכר את כולו באיסור. ואילו \u0003כאן\u0004 ששנינו שחייבים מדובר \u0003בשותף שגנב,\u0004 כלומר, שותפים שגנבו \u0003מעלמא\u0004 \u0005[מן העולם,\u0006 מאנשים אחרים\u0005]\u0006 שהם חייבים.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 מברייתא ששנינו בה: \u0003יכול שותף שגנב מחבירו, ושותפים שגנבו יהו חייבין? תלמוד לומר: \"וטבחו\"\u0004 ומלשון זה נשמע כי \u0003כולו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]!\u0006","\u0003אלא אמר רב נחמן:\u0004 יש לחזור מתירוץ זה ולומר כי \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 וכך יש לומר: בשתי הברייתות מדובר בשותפים שגנבו מן העולם, ומדובר בשתי הברייתות במקרים שונים. \u0003כאן\u0004 ששנינו שחייבים, מדובר \u0003בשותף שטבח לדעת חבירו,\u0004 ואז מחייב גם את חבירו, ואילו \u0003כאן\u0004 ששנינו שפטורים, מדובר \u0003בשותף שטבח שלא לדעת חבירו,\u0004 וכיון שאז חל עליו רק חצי מתשלום ארבעה וחמישה — אינו משלם כלל.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה\u0004 שאלה זו: \u0003מכרה\u0004 הגנב \u0003חוץ משלשים יום,\u0004 שהשאיר לעצמו זכות שימוש בה למשך שלושים יום, או מכר את הבהמה לגופה \u0003חוץ ממלאכתה,\u0004 שהוא משייר לעצמו את הזכות לעשות בה מלאכה, או מכרה \u0003חוץ מעוברה,\u0004 שהעובר הנולד ממנה יהיה שייך לו, \u0003מהו\u0004 הדין? האם נחשב הדבר כמכירה גמורה לחייבו בארבעה וחמישה שהרי מכר את גופה, או לא?","ומעירים: \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטתו של מי שאומר]\u0006 \u0003עובר ירך אמו הוא\u0004 שנחשב חלק ממנה — \u0003לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה אחרונה זו, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שייר בה,\u0004 שהעובר הוא כחלק מן הבהמה. \u0003כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 שאלה זו הרי זה \u0003אליבא דמאן דאמר\u0004 \u0005[לשיטתו של מי שאומר]\u0006 ש\u0003עובר לאו\u0004 \u0005[אינו]\u0006 \u0003ירך אמו,\u0004 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? וצדדי השאלה: האם \u0003מימר אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003כיון\u0004 ש\u0003מחובר בה הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003שיור, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלמפרש מינה קאי\u0004 \u0005[שלפרוש ממנה\u0006 הוא \u0005עומד],\u0006 שבהכרח ייוולד ולא יהא חלק מגופה \u0003לא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 \u0003שיור?\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שאלה זו בלשון אחרת: האם \u0003כיון דלאו\u0004 \u0005[שלא]\u0006 \u0003ירך אמו הוא\u0004 בוודאי \u0003לא הוי\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 \u0003שיור, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003צריך לאישתרויי בהדה\u0004 \u0005[להיות ניתר יחד איתה]\u0006 \u0003בשחיטה,\u0004 שאת העובר אינו יכול לאכול (לפני שנולד) אלא אם כן ישחטו את אמו, הרי זה \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003שייר בגופה דמי\u0004 \u0005[נחשב]?\u0006 לשאלות אלה לא נמצאו תשובות, ולכן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא\u0004 שאלה זו: \u0003גנבה, קטעה\u0004 (קטע ממנה חלק) \u0003ומכרה\u0004 לאחר מכן בלי אותו חלק, \u0003מהו\u0004 הדין? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 ש\u0003גנב הא\u0004 \u0005[הרי]\u0006 \u0003לא זבין\u0004 \u0005[מכר]\u0006 וכיון שכך חייב על הגניבה אבל לא על המכירה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 בבהמה זו שלפניו, \u0003מה דזבין\u0004 \u0005[שמכר]\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא שייר,\u0004 שהרי את הבהמה שבידו מכר בשלימות. אף לשאלה זו לא נמצא פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גנב\u0004 בהמה \u0003ונתן\u0004 אותה \u0003לאחר\u0004 להיות שליחו \u0003ו\u0004אותו אחר \u0003טבח,\u0004 או ש\u0003גנב ונתן לאחר ומכר\u0004 האחר,"],["\u0003גנב והקדיש, גנב והקיף\u0004 (מכר את הבהמה בהקפה, ולא קיבל תשלום עבורה), \u0003גנב והחליף\u0004 את הגניבה בדבר אחר, \u0003גנב ונתן במתנה, גנב ופרע\u0004 בגניבה את \u0003חובו,\u0004 \u0003גנב ופרע ב\u0004גניבה את \u0003הקיפו\u0004 (מה שלקח בהקפה), \u0003גנב ושלח סבלונות\u0004 (מתנות) \u0003בבית חמיו,\u0004 בכל אלה, אף שהגנב לא ביצע פעולה של מכירה רגילה, הואיל ובפועל העביר את הבהמה לבעלותו של אדם אחר — \u0003משלם תשלומי ארבעה וחמשה.\u0004","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכל המקרים הללו? ומסבירים: \u0003אשמעינן רישא\u0004 \u0005[השמיע לנו\u0006 בדין שהביא \u0005בתחילה]\u0006 \u0003גנב ונתן לאחר וטבח,\u0004 ש\u0003יש שליח לדבר עבירה,\u0004 שעל ידי האחר שטבח מתחייב הגנב. כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003בכל התורה כולה\u0004 כלל הוא כי \u0003אין שליח לדבר עבירה,\u0004 שהמעשה של העבירה שעשה השליח אינו מתייחס לשולחו, מכל מקום \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003יש שליח לדבר עבירה,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — נאמר \u0003\"וטבחו\u0004 או \u0003מכרו\"\u0004 (שמות כא, לז) לומר: \u0003מה מכירה\u0004 שמתחייב עליה היא מעשה ש\u0003לא אפשר דלאו\u0004 \u0005[ש\u0006לא תיעשה אם \u0005לא]\u0006 \u0003על ידי אחר\u0004 שמוכר לו, \u0003אף טביחה\u0004 אף \u0003על ידי אחר מחייב\u0004 \u0005[מתחייב].\u0006","\u0003ואשמעינן סיפא\u0004 \u0005[והשמיע לנו\u0006 בדין שהוא \u0005בסוף]\u0006 \u0003גנב והקדיש,\u0004 לומר לנו כי \u0003מה לי מכרו להדיוט\u0004 במכירה פשוטה, \u0003מה לי מכרו לשמים\u0004 על ידי הקדש, שאף זה קרוי מוכר, ומתחייב.","\u0003גנב\u0004 אדם בהמה \u0003ב\u0004מקום שהוא \u0003רשות הבעלים, וטבח ומכר\u0004 אותה \u0003חוץ מרשותם, או שגנב חוץ מרשותם,\u0004 שהוציאה מרשותם, \u0003וטבח ומכר ברשותם\u0004 לאחר שהביאה שוב (לא על מנת להחזירה) אל תוך רשותם, \u0003או שגנב וטבח ומכר חוץ מרשותם\u0004 — בכל האופנים הללו \u0003משלם תשלומי ארבעה וחמשה, אבל\u0004 אם גם \u0003גנב ו\u0004גם \u0003טבח ומכר ברשותם\u0004 של הבעלים — \u0003פטור\u0004 מתשלומי ארבעה וחמישה ומכפל (אף שחייב בתשלום על הבהמה עצמה), שהרי אין נחשב גנב על כך.","\u0003היה מושכו\u0004 את בעל החיים \u0003ויוצא\u0004 \u0003ו\u0004בתוך כדי כך \u0003מת\u0004 הדבר הנגנב \u0003ב\u0004תוך \u0003רשות הבעלים\u0004 — \u0003פטור\u0004 הגנב לגמרי, כיון שלא נקנה לו עדיין החפץ. \u0003הגביהו\u0004 את הדבר הנגנב, ואף ברשות הבעלים, \u0003או הוציאו מרשות בעלים\u0004 \u0003ו\u0004אחר כך \u0003מת\u0004 הדבר הנגנב אפילו לא הכניס הגנב את הדבר לרשותו — \u0003חייב\u0004 עליו, כיון שכבר קנה אותו כגנב.","\u0003נתנו\u0004 הגנב לכהן \u0003ל\u0004צורך \u0003בכורות בנו,\u0004 כלומר, שפדה בו את בנו במקום חמישה סלעים, \u0003או\u0004 נתנו כתשלום חוב \u0003לבעל חוב,\u0004 או שנתנו לשמירה \u0003לשומר חנם,\u0004 או \u0003לשואל,\u0004 או \u0003לנושא\u0004 (שומר) \u0003שכר\u0004 או \u0003לשוכר, והיה\u0004 כל אחד מאלה שקבלו מן הגנב \u0003מושכו\u0004 מרשות הבעלים \u0003ומת\u0004 \u0003ברשות הבעלים\u0004 — \u0003פטור\u0004 הגנב. \u0003הגביהו או שהוציאו מרשות הבעלים ומת —\u0004 \u0003חייב,\u0004 שאותו אדם עשה את הקנין (של הגניבה) במקום הגנב.","ומביאים ענין בו נדונה משנתנו. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אמימר\u0004 שאלה זו: האם \u0003תיקנו משיכה בשומרים, או לא?\u0004 כלומר, האם השומר חייב באחריות לחפץ דווקא משעה שימשוך את החפץ לרשותו כעין קנין, או שמא מיד כשהוסכם הדבר בינו לבין הבעלים התחייב בו, ואין למשיכה משמעות לענין זה?","\u0003אמר רב יימר, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנתנו: \u0003נתנו\u0004 הגנב \u0003לבכורות בנו או לבעל חובו, לשומר חנם\u0004 או \u0003לשואל,\u0004 או \u0003לנושא שכר\u0004 או \u0003לשוכר, היה מושכו ויוצא ומת ברשות הבעלים\u0004 — \u0003פטור. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שמשכו ה\u0003שומר? ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי אכן \u0003תיקנו משיכה בשומרין\u0004 ומשום כך מתחייב הגנב במשיכתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003לא,\u0004 אין מכאן ראיה, שכן אפשר לומר שמדובר כאן שהבעלים נתנו תחילה לשומר, והיה מושכו ה\u0003גנב\u0004 מבית השומר.","והקשה לו רב יימר: אם המדובר כאן בגנב המושך \u0003הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו\u0006 כבר ב\u0005תחילת\u0006 המשנה\u0005],\u0006 ומה טעם יש לשנות שוב דבר זה? ותירץ לו אמימר: \u0003תנא\u0004 \u0005[שנה]\u0006 קודם \u0003גנב שגנב מבית הבעלים\u0004 עצמם, \u0003ותנא\u0004 \u0005[ושנה]\u0006 אחר כך \u0003גנב שגנב מבית שומר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי\u0004 לאמימר: \u0003לא תדחייה\u0004 \u0005[תדחנו]\u0006 על ידי תירוץ זה, כי \u0003מה לי גנב שגנב מבית שומר, מה לי גנב שגנב מבית בעלים,\u0004 ובזה אין צורך לשנות שוב, שאין הבדל בדבר.","\u0003אלא לאו\u0004 \u0005[האם אין]\u0006 הכוונה שמה שנאמר פה בזה שהיה מושך הוא ב\u0003שומר, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003תיקנו משיכה בשומרין.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 בשם אמורא אחר, ש\u0003אמר ר' אלעזר: כדרך שתיקנו משיכה בלקוחות,\u0004 שאין חפץ עובר לרשותו של הקונה עד שימשכנו, \u0003כך תיקנו משיכה בשומרין\u0004 שאינם מתחייבים באחריות לחפץ כל עוד לא משכוהו.","\u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]:\u0006 \u0003כדרך שתיקנו משיכה בלקוחות, כך תיקנו משיכה בשומרין. וכשם שהקרקע נקנית\u0004 לקונה אותה \u0003בכסף,\u0004 או \u0003בשטר,\u0004 או \u0003בחזקה, כך שכירות נקנית בכסף, בשטר,\u0004 או \u0003בחזקה.\u0004 קטע אחרון זה בברייתא צריך ביאור.","ושואלים: \u0003שכירות דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר כאן"],["ב\u0003שכירות\u0004 של \u0003מטלטלין\u0004 ששכר כלי או בהמה לשימוש לזמן מסויים, וכי \u0003מטלטלי בני שטרא נינהו\u0004 \u0005[מיטלטלים בני שטר הם]?\u0006 כלומר, והלא אין כותבים שטרות על מכירת מיטלטלים! אלא \u0003אמר רב חסדא:\u0004 מדובר כאן ב\u0003שכירות\u0004 של \u0003קרקע,\u0004 שדרכי הקנין לשכירות זו הם כדרך שנקנית הקרקע לקוניה.","\u0003אמר ר' אלעזר: ראוהו\u0004 את הגנב \u0003שהטמין\u0004 את הגניבה \u0003בחורשין\u0004 (יער קטן) \u0003וטבח ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004 ותוהים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 משלם? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא משך\u0004 ולא ראינוהו שגנב! \u0003אמר רב חסדא:\u0004 מדובר כאן שראוהו \u0003שהכישה\u0004 (היכה אותה) את הבהמה \u0003במקל\u0004 שתלך לפניו, ומעשה כזה הריהו כמשיכה.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה על הסברו של רב חסדא: \u0003וכיון\u0004 ש\u0003ראוהו\u0004 שעושה כן, הלא \u0003גזלן הוא\u0004 שעשה בגלוי, וגזלן שטבח או מכר אינו משלם תשלומי כפל ותשלומי ארבעה וחמישה! ומשיבים: \u0003כיון דקא מטמרי מנייהו\u0004 \u0005[שהוא מתחבא מהם,\u0006 מהאנשים\u0005]\u0006 ואין כוונתו לעשות זאת לעין כל, \u0003גנב הוא.\u0004","ושואלים: \u0003ואלא גזלן היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אמר ר' אבהו: כגון\u0004 האמור אצל \u0003בניהו בן יהוידע, שנאמר: \"ויגזל את החנית מיד המצרי ויהרגהו בחניתו\"\u0004 (שמואל ב כג, כא), כלומר, שנוטל במישרין מן האדם בכוח בעל כרחו של הנגזל בגלוי.","\u0003ר' יוחנן אמר: כגון\u0004 האמור אצל \u0003בעלי שכם, שנאמר: \"וישימו לו בעלי שכם מארבים על ראשי ההרים ויגזלו את כל אשר יעבר עליהם בדרך\"\u0004 (שופטים ט, כה).","ושואלים: \u0003ור' אבהו מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 ראיה \u0003מהאי\u0004 \u0005[מ\u0006כתוב \u0005זה]\u0006 בבעלי שכם שהוא מוקדם יותר? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: כיון דמטמרי איטמורי, לא גזלני נינהו\u0004 \u0005[מכיון ש\u0006הם היו \u0005מתחבאים\u0006 במארבים כדי לגזול, \u0005אין הם גזלנים]\u0006 שגזלן הוא העושה הכל בגלוי. ומן הצד השני: \u0003ור' יוחנן\u0004 מה הוא משיב על כך? לדעתו \u0003הא דקא מטמרי\u0004 \u0005[זה שהם התחבאו]\u0006 הרי זה כדי ש\u0003לא ניחזינהו אינשי וניערקו מנייהו\u0004 \u0005[יראום בני אדם ויברחו מהם]\u0006 ולא מחמת שהם בושים או מפחדים, אלא לצורך הגזילה התחבאו, ולאחר מכן היו גוזלים בגלוי ובחוזק יד את העוברים בדרך.","\u0003שאלו תלמידיו את רבן יוחנן בן זכאי: מפני מה החמירה תורה בגנב יותר מגזלן\u0004 שהגנב משלם קנסות (כפל, ארבעה וחמישה) ולא הגזלן? \u0003אמר להן: זה,\u0004 הגזלן, \u0003השוה כבוד עבד\u0004 (האדם) \u0003לכבוד קונו\u0004 (הבורא), שהרי גוזל הוא לעיני הבריות ואינו מתיירא ומתבייש אף מהם, \u0003וזה,\u0004 הגנב, \u0003לא השוה כבוד עבד לכבוד קונו,\u0004","\u0003כביכול, עשה עין של מטה\u0004 (כלומר, לשון נקיה, וכוונתו עין של מעלה, של הקדוש ברוך הוא) \u0003כאילו אינה רואה ואוזן של מטה\u0004 (בלשון נקיה, והכוונה של מעלה) \u0003כאילו אינה שומעת,\u0004 שהרי התחבא רק מבני אדם ואינו חושש מפני הקדוש ברוך הוא, \u0003שנאמר: \"הוי המעמיקים מה' לסתר עצה והיה במחשך מעשיהם\u0004 ויאמרו מי רואנו ומי יודענו\u0003\"\u0004 (ישעיהו כט, טו), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויאמרו לא יראה יה ולא יבין אלהי יעקב\"\u0004 (תהלים צד, ז), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי אמרו עזב ה' את הארץ ואין ה' ראה\"\u0004 (יחזקאל ט, ט).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' מאיר: משלו משל משום\u0004 (בשם) \u0003רבן גמליאל, למה הדבר דומה? לשני בני אדם שהיו בעיר ועשו משתה\u0004 (סעודת חתונה), \u0003אחד זימן\u0004 (הזמין) \u0003את בני העיר ולא זימן את בני המלך, ואחד לא זימן את בני העיר ולא זימן את בני המלך, איזה מהן עונשו מרובה? הוי אומר: זה שזימן את בני העיר ולא זימן את בני המלך.\u0004","ובטעמי דיני קנסות אלה של ארבעה וחמישה \u0003אמר ר' מאיר: בא וראה כמה גדול כח של מלאכה\u0004 וחשיבותה, הגונב \u0003שור, שביטלו\u0004 את בעל השור \u0003ממלאכתו,\u0004 שהרי שור בעיקר נועד לעבוד בו — משלם \u0003חמשה,\u0004 ואילו הגונב \u0003שה, שלא ביטלו ממלאכתו\u0004 — משלם רק \u0003ארבעה.\u0004","\u0003אמר רבן יוחנן בן זכאי\u0004 טעם אחר להבדל זה: \u0003בא וראה כמה גדול כבוד הבריות, שור שהלך\u0004 הגנב \u0003ברגליו\u0004 — משלם הגנב \u0003חמשה, שה שהרכיבו\u0004 הגנב \u0003על כתיפו\u0004 וכיון שביטל על ידי כך מכבודו — משלם רק \u0003ארבעה.\u0004","\u0003אין מגדלין בהמה דקה\u0004 (עזים וכבשים) \u0003בארץ ישראל\u0004 במקום ישוב, לפי שהן מזיקות את צמחיית השדות של אחרים, \u0003אבל מגדלין\u0004 בהמה דקה \u0003בסוריא,\u0004 ואף שיש דברים בה שדינה כארץ ישראל, \u0003ו\u0004כן מגדלים \u0003במדברות\u0004 שאינם מקומות של ישוב \u0003של ארץ ישראל.\u0004","\u0003אין מגדלין תרנגולין בירושלים מפני\u0004 בשר \u0003הקדשים,\u0004 שיש לחשוש שהתרנגולים יביאו דבר טמא מן האשפה ויטמאו על ידו דברים אחרים, \u0003ו\u0004כן \u0003לא\u0004 מגדלים \u0003כהנים\u0004 תרנגולים \u0003ב\u0004כל \u0003ארץ ישראל\u0004 \u0003מפני הטהרות,\u0004 כלומר, דברים הנאכלים בטהרה, כגון תרומה, שמא יטמאום התרנגולים.","\u0003אין מגדלין חזירין בכל מקום.\u0004 וכן \u0003לא יגדל אדם את הכלב, אלא אם כן היה קשור בשלשלת\u0004 באופן שלא יזיק. \u0003אין פורסין נישובים\u0004 (מלכודות) \u0003ליונים אלא אם כן היה רחוק מן הישוב שלשים ריס\u0004 (ארבעה מילים) כדי שלא יצודו יונים השייכות לבני היישוב, אלא יוני בר בלבד.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מגדלין בהמה דקה בארץ ישראל, אבל מגדלין בחורשין\u0004 (יערות) \u0003של ארץ ישראל,\u0004 ואילו \u0003בסוריא\u0004 מגדלים \u0003אפילו בישוב, ואין צריך לומר בחוצה לארץ\u0004 שמותר.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מגדלין בהמה דקה בארץ ישראל, אבל מגדלין במדבר שביהודה ובמדבר שבספר\u0004 (גבול) \u0003עכו. ואף על פי שאמרו\u0004 חכמים \u0003אין מגדלין בהמה דקה, אבל מגדלין בהמה גסה\u0004 בישוב, \u0003לפי ש\u0004כלל הוא זה: \u0003אין גוזרין גזרה על הצבור אלא אם כן רוב\u0004 ה\u0003צבור יכולין לעמוד בה,\u0004 ובענייננו:","\u0003בהמה דקה\u0004 שעיקרה נועד לאכילה — \u0003אפשר להביא מחוצה לארץ,\u0004 אבל \u0003בהמה גסה\u0004 — \u0003אי אפשר להביא מחוצה לארץ,\u0004 שהרי זקוקים לה לעבודה ולמשא בכל יום.","\u0003ו\u0004הלכה נוספת, \u0003אף על פי שאמרו אין מגדלין בהמה דקה\u0004 בארץ ישראל, \u0003אבל משהה הוא\u0004 בביתו את הבהמה הדקה שקנה \u0003קודם לרגל שלשים יום\u0004 כדי לשוחטה ברגל, \u0003ו\u0004כן \u0003קודם משתה\u0004 (סעודת נישואי) \u0003בנו שלשים יום, ובלבד שלא ישהה את האחרונה,\u0004 כלומר, בהמה אחרונה שנקנתה בתוך אותו זמן \u0003שלשים יום;\u0004","ומסבירים: \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]\u0006 \u0003דאי נפק ליה\u0004 \u0005[שאם יצא לו,\u0006 עבר\u0005]\u0006 ה\u0003רגל, ומכי זבנה\u0004 \u0005[ומאז שקנה אותה],\u0006 את האחרונה \u0003עד השתא\u0004 \u0005[עכשיו]\u0006 \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003לא מלו ליה תלתין יומין\u0004 \u0005[מלאו לה\u0006 למכירה \u0005שלושים יום],\u0006 ש\u0003לא נימא\u0004 \u0005[נאמר]:\u0006 \u0003תלתין משרא שרי ליה לשהויי\u0004 \u0005[שלושים\u0006 יום \u0005מותר לו להשהותה].\u0006 \u0003אלא כיון דנפק ליה\u0004 \u0005[שיצא לו,\u0006 שעבר\u0005]\u0006 ה\u0003רגל\u0004 — \u0003לא מבעי ליה לשהויי\u0004 \u0005[אינו צריך,\u0006 אסור לו \u0005להשהותה].\u0006"],["\u0003והטבח\u0004 (השוחט, הקצב) \u0003לוקח\u0004 (קונה) בהמה דקה \u0003ושוחט, לוקח ושוהה\u0004 בביתו עד זמן השחיטה, \u0003ובלבד שלא ישהה העגונה\u0004 (האחרונה) \u0003שבהן שלשים יום.\u0004","באותו ענין \u0003שאלו תלמידיו את רבן גמליאל: מהו לגדל\u0004 בהמה דקה בארץ ישראל? \u0003אמר להן: מותר.\u0004 ותוהים על כך: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אין מגדלין!\u0004","\u0003אלא\u0004 יש לתקן את הגרסה ולומר \u0003הכי קא בעו מיניה\u0004 \u0005[כך שאלו ממנו]:\u0006 \u0003מהו לשהות\u0004 בהמה דקה לצורך שחיטה בארץ ישראל? \u0003אמר להן: מותר, ובלבד שלא תצא ותרעה בעדר\u0004 בחוץ, \u0003אלא קושרה בכרעי המטה\u0004 בתוך ביתו.","ובענין זה מסופר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעשה בחסיד אחד שהיה גונח מלבו\u0004 (שהיה משתעל בשל חליו), \u0003ושאלו לרופאים\u0004 מה לעשות לרפואתו, \u0003ואמרו: אין לו תקנה עד שינק חלב רותח\u0004 (מבעבע) מן הבהמה \u0003משחרית לשחרית,\u0004 כלומר, בכל בוקר, \u0003ו\u0004לצורך זה \u0003הביאו לו עז וקשרו לו בכרעי המטה, והיה יונק ממנה משחרית לשחרית\u0004 במשך זמן.","\u0003לימים נכנסו חביריו לבקרו\u0004 ביקור חולים, \u0003כיון שראו אותה העז קשורה בכרעי המטה חזרו לאחוריהם\u0004 ולא נכנסו לביתו, \u0003ואמרו: לסטים \u0004(שודד) \u0003מזויין\u0004 נמצא \u0003בביתו של זה, ואנו נכנסין אצלו?!\u0004","\u0003ישבו\u0004 חכמים \u0003ובדקו\u0004 במעשיו \u0003ולא מצאו בו\u0004 כל פגם \u0003אלא\u0004 מלבד \u0003אותו עון של אותה העז\u0004 שהחזיק בביתו. \u0003ואף הוא\u0004 אותו חסיד \u0003בשעת מיתתו אמר: יודע אני שאין בי\u0004 כל \u0003עון אלא עון אותה העז\u0004 בלבד, \u0003שעברתי על דברי חברי\u0004 שאמרו שאסור להשהות בהמה דקה בארץ ישראל.","ובאותו ענין של בהמה דקה \u0003אמר ר' ישמעאל: מבעלי בתים שבגליל העליון היו בית אבא, ומפני מה\u0004 איזה עוון גרם להם ש\u0003חרבו\u0004 — \u0003שהיו מרעין\u0004 (רועים) \u0003בחורשין\u0004 (יערות) בסביבה, \u0003ודנין דיני ממונות ביחיד. ואף על פי שהיו להם חורשים סמוך לבתיהם\u0004 והיו החורשים שלהם, ולא רעו בהמותיהם בשל אחרים. מכל מקום \u0003שדה קטנה\u0004 של אחרים \u0003היתה\u0004 בדרך בין ביתם לחורשיהם \u0003ומעבירין\u0004 היו את הצאן \u0003דרך עליה\u0004 (דרכה), וזה גרם להם שנענשו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003רועה\u0004 בהמה דקה \u0003שעשה תשובה\u0004 ורוצה לנהוג מעתה כדין ולא לגדל עוד בהמה דקה, \u0003אין מחייבין אותו למכור\u0004 את כל צאנו \u0003מיד,\u0004 והרי בכך מקשים עליו ביותר, שנאלץ הוא למוכרם בפחות ממחירם, ויש לו הפסד מרובה \u0003אלא מוכר על יד על יד\u0004 (מעט מעט). \u0003וכן גר שנפלו לו\u0004 \u0003כלבים וחזירים בירושתו\u0004 מאבותיו הגויים, ואסור הוא בגידולם כמפורש במשנה, \u0003אין מחייבין אותו למכור\u0004 הכל \u0003מיד, אלא מוכר על יד על יד.\u0004","\u0003וכן מי שנדר ליקח\u0004 (לקנות) \u0003בית\u0004 או \u0003ליקח\u0004 (לשאת) \u0003אשה בארץ ישראל\u0004 ולא קבע לכך זמן מוגדר, \u0003אין מחייבין אותו ליקח מיד\u0004 בית או אשה ראשונה שיזדמנו לו, \u0003עד שימצא את ההוגנת\u0004 (הראויה) \u0003לו.\u0004","\u0003ו\u0004כיוצא בו מספרים: \u0003מעשה באשה אחת שהיה בנה מיצר\u0004 (מציק) \u0003לה,\u0004 ולא היה לה בעל שיתיירא הבן מפניו, \u0003וקפצה ונשבעה: \"כל מי שיבא\u0004 ויבקש לשאת אותי לאשה \u0003איני מחזירתו\u0004 (מסרבת לו)\", \u0003וקפצו עליה בני אדם שאינן מהוגנין\u0004 וביקשו לשאתה לאשה ולא ידעה מה לעשות שהרי נשבעה כן. \u0003וכשבא הדבר אצל חכמים, אמרו: לא נתכוונה זו אלא להגון לה\u0004 בלבד ולא ממש לכל איש ראשון שיבוא.","וממשיכה הברייתא: \u0003כשם שאמרו\u0004 חכמים \u0003אין מגדלין בהמה דקה, כך אמרו\u0004 ש\u0003אין מגדלין חיה דקה,\u0004 כגון כלבים וחתולים. \u0003ר' ישמעאל אומר: מגדלין\u0004 חיות בית שיש בהן תועלת ואינן מזיקות כגון \u0003כלבים כופרין\u0004 (כלבי ציד), \u0003וחתולים, וקופין, וחולדות סנאים, מפני שעשויים\u0004 אלה \u0003לנקר\u0004 (לנקות) \u0003את הבית\u0004 ממיני שרצים, ולכן מותר לגדלם.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הן\u0005]\u0006 \u0003חולדות סנאים\u0004 הללו? \u0003אמר רב יהודה:\u0004 קוראים להן בארמית \u0003שרצא חרצא; ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 שקוראים להן \u0003חרזא, דקטיני שקיה ורעיא ביני וורדיני\u0004 \u0005[שדקות שוקיה ורועה בין הקוצים].\u0006 \u0003ומאי שרצא\u0004 \u0005[ומה\u0006 טעם קוראים להן \u0005שרץ]?\u0006 \u0003דמתתאי שקיה\u0004 \u0005[\u0006מפני \u0005ששוקיה נמוכות]\u0006 ונגררות על הארץ ונראות כשרץ השורץ על הארץ.","ועוד בקשר לדין המשנה. \u0003אמר רב יהודה אמר רב: עשינו עצמנו בבבל\u0004 לנהוג \u0003כארץ ישראל ל\u0004ענין איסור גידול \u0003בהמה דקה.\u0004 ובענין זה מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרב הונא: דידך מאי\u0004 \u0005[\u0006צאנך \u0005שלך מה],\u0006 מדוע אין אתה נוהג כדברי רבך, רב, ומגדל אתה צאן?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 את הבהמות \u0003דידן קא מינטרא להו\u0004 \u0005[שלנו שומרת אותן]\u0006 אשתי שנקראה \u0003חובה.\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חובה תקברינהו לבנה\u0004 \u0005[תקבור את בניה].\u0006 ואומרים: כיון שיצא הדבר מפי רב אדא בר אהבה בלשון זו, היתה זו כשגגה היוצאת מפי השליט, ו\u0003כולה שניה\u0004 \u0005[כל שנותיו]\u0006 של \u0003רב אדא בר אהבה\u0004 אכן \u0003לא אקיים זרעא\u0004 \u0005[נתקיים זרע]\u0006 \u0003לרב הונא מ\u0004אשתו \u0003חובה. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר קצת \u0003אמר רב הונא אמר רב: עשינו עצמנו בבבל\u0004 לנהוג \u0003כארץ ישראל ל\u0004ענין איסור גידול \u0003בהמה דקה, מכי אתא\u0004 \u0005[מאז\u0006 ש\u0005בא]\u0006 \u0003רב לבבל\u0004 מארץ ישראל ותיקן בה כמה תקנות גדולות.","מסופר: \u0003רב ושמואל ורב אסי איקלעו לבי\u0004 \u0005[הזדמנו לבית]\u0006 \u0003שבוע הבן\u0004 שבו עשו ברית מילה, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003לבי\u0004 \u0005[לבית]\u0006 שבו עשו \u0003ישוע\u0004 (פדיון) \u0003הבן\u0004 — \u0003רב לא\u0004 היה רוצה \u0003עייל קמיה\u0004 \u0005[להיכנס לפני]\u0006 \u0003שמואל, \u0004"],["ואילו \u0003שמואל לא\u0004 היה רוצה \u0003עייל קמיה\u0004 \u0005[להיכנס לפני]\u0006 \u0003רב אסי,\u0004 שראה אותו כגדול ממנו, ו\u0003רב אסי לא\u0004 היה רוצה \u0003עייל קמיה\u0004 \u0005[להיכנס לפני]\u0006 \u0003רב\u0004 שהיה רבו, ומשום כך לא נכנסו שלושתם. \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003מאן נתרח\u0004 \u0005[מי יאחר]\u0006 וימתין בחוץ ויכנס לבדו אחרון? וסיכמו: \u0003נתרח\u0004 \u0005[יאחר]\u0006 \u0003שמואל וניתי\u0004 \u0005[ויבואו]\u0006 \u0003רב ו\u0004אחריו \u0003רב אסי.\u0004","ושואלים: \u0003ונתרח\u0004 \u0005[ושיתאחר]\u0006 \u0003רב או רב אסי?\u0004 שיכנס תחילה שמואל ואחריו אחד משניהם, והאחר ימתין! ומשיבים: משום שבאמת היה רב גדול משמואל, והיה ראוי לו להיכנס לפניו. אלא \u0003רב,\u0004 שלא רצה להיכנס לפני שמואל, \u0003מילתא בעלמא\u0004 \u0005[דבר\u0006 של כבוד \u0005לבד]\u0006 \u0003הוא דעבד ליה\u0004 \u0005[שעשה לו]\u0006 \u0003לשמואל,\u0004 ולא משום שהיה גדול ממנו, אלא \u0003משום ההוא מעשה דלטייה\u0004 \u0005[אותו מעשה\u0006 שאירע \u0005שקילל אותו]\u0006 רב לשמואל בטעות וכדי לפייסו על כך \u0003אדבריה\u0004 \u0005[הנהיגו]\u0006 \u0003רב עליה\u0004 \u0005[עליו],\u0006 שהיה נוהג כלפיו כבוד יתר.","ומספרים: \u0003אדהכי והכי\u0004 \u0005[בין כך וכך]\u0006 \u0003אתא שונרא קטעיה לידא דינוקא\u0004 \u0005[בא חתול\u0006 ו\u0005קטע את ידו של תינוק].\u0006 \u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רב ודרש\u0004 בענין זה: \u0003חתול מותר להורגו, ואסור לקיימו\u0004 בבית, \u0003ו\u0004כל הלוקח אותו והורגו \u0003אין בו משום\u0004 איסור \u0003גזל, ואין בו משום\u0004 מצוה של \u0003השב אבידה לבעלים.\u0004","ושואלים: \u0003וכיון דאמרת\u0004 \u0005[שאתה אומר]\u0006 \u0003מותר להורגו, מאי ניהו תו\u0004 \u0005[מה הוא עוד]\u0006 הצורך לומר ש\u0003אסור לקיימו?\u0004 ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003מותר\u0004 אמנם לאחרים \u0003להורגו,\u0004 אך \u0003איסורא ליכא\u0004 \u0005[איסור אין]\u0006 בהחזקתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף אסור לקיימו.","ועוד \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה על ניסוח הדברים: \u0003וכיון דאמרת\u0004 \u0005[שאתה אומר]\u0006 \u0003\"אין בו משום גזל\",\u0004 כלומר, שאין זה איסור לקחת מיד הבעלים בכח, \u0003מאי ניהו תו\u0004 \u0005[מה הוא עוד]\u0006 הצורך לומר ש\u0003\"אין בו משום השב אבידה לבעלים\"? אמר רבינא:\u0004 הכוונה היא \u0003ל\u0004ענין \u0003עורו,\u0004 שאין צורך להחזירו לבעלים.","על דברי רב בדינו של חתול \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא, \u0003ר' שמעון בן אלעזר אומר: מגדלין כלבים כופרין\u0004 (כלבי ציד), \u0003וחתולין, וקופין, וחולדות סנאים, מפני שעשויין לנקר את הבית,\u0004 הרי שמותר לגדל חתול! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 דברי ר' שמעון שאמר שמותר נאמרו \u0003באוכמא\u0004 \u0005[ב\u0006חתול \u0005שחור],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 דברי רב שאמר שאסור נאמרו \u0003בחיוורא\u0004 \u0005[ב\u0006חתול \u0005לבן].\u0006","ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 באותו \u0003מעשה\u0004 של \u0003רב, אוכמא הוה\u0004 \u0005[\u0006חתול \u0005שחור היה]!\u0006 ומשיבים: \u0003התם אוכמא בר חיורא הוה\u0004 \u0005[שם\u0006 חתול \u0005שחור בן לבן היה]\u0006 ודינו כחתול לבן. ומקשים: \u0003והא מבעיא בעיא ליה\u0004 \u0005[והרי דבר\u0006 זה \u0005נסתפק לו]\u0006 ל\u0003רבינא,\u0004","\u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבינא: אוכמא בר חיורא, מהו\u0004 \u0005[\u0006חתול \u0005שחור בן לבן מה\u0006 דינו\u0005]?\u0006 ואם כך היה המקרה, מדוע היה מסופק בדבר? ומסבירים: \u0003כי קמבעיא ליה\u0004 \u0005[כאשר נסתפק לו]\u0006 \u0003לרבינא\u0004 היה זה \u0003באוכמא בר חיורא בר אוכמא\u0004 \u0005[ב\u0006חתול \u0005שחור בן לבן בן שחור],\u0006 ואילו ה\u0003מעשה\u0004 שאירע לפני \u0003רב\u0004 — \u0003באוכמא בר חיורא בר חיורא הוה\u0004 \u0005[ב\u0006חתול \u0005שחור בן לבן בן לבן היה].\u0006","\u0003(חב\"ד בי\"ח בח\"ן: סימן\u0004 לשלוש מסורות שונות של שמות החכמים וסדר מסירת הלכות שתוזכרנה להלן, והם: ר' א \u0003ח\u0004 א, ר' א \u0003ב\u0004א, ר' א \u0003ד\u0004א. ר' א \u0003ב\u0004א, ר' ח \u0003י\u0004 יא, ר' א \u0003ח\u0004 א. ר' א \u0003ב\u0004א, ר' א \u0003ח\u0004 א, ר' ח \u0003נ\u0004 ינא). \u0003אמר ר' אחא בר פפא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אבא בר פפא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אדא בר פפא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שמסורת זו היתה כך: \u0003אמר ר' אבא בר פפא משום\u0004 \u0005[בשם]\u0006 \u0003ר' חייא בר פפא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אחא בר פפא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך היתה המסורת: \u0003אמר ר' אבא בר פפא משום\u0004 \u0005[בשם]\u0006 \u0003ר' אחא בר פפא משום\u0004 \u0005[בשם]\u0006 \u0003ר' חנינא בר פפא:\u0004","\u0003מתריעין\u0004 בתקיעת שופר \u0003על החיכוך\u0004 (מחלת שחין המתפשטת) ואפילו \u0003בשבת, ודלת הננעלת לא במהרה תפתח, והלוקח\u0004 (הקונה) \u0003בית בארץ ישראל\u0004 — \u0003כותבין עליו אונו\u0004 (שטר מכירה) \u0003אפילו בשבת.\u0004 ומבררים מאמרים אלה.","על הנאמר \"מתריעין על החיכוך\" \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 הלא שנינו בברייתא במסכת תענית: \u0003ושאר פורעניות המתרגשות ובאות על הצבור,\u0004 חוץ מאלו המנויות במשנה שם, \u0003כגון חיכוך,\u0004 או \u0003חגב,\u0004 או \u0003זבוב, צירעה ויתוש, ושילוח נחשים ועקרבים\u0004 — \u0003לא היו מתריעין\u0004 בשופרות \u0003אלא צועקים\u0004 בתפילה בלבד!","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 מדובר \u0003ב\u0004שחין \u0003לח, כאן\u0004 מדובר \u0003ב\u0004שחין \u0003יבש\u0004 שהוא קשה מן הלח ועליו אף מתריעים בשופרות. שכן מצאנו שני סוגים אלה של שחין, וכפי ש\u0003אמר ר' יהושע בן לוי: שחין שהביא הקדוש ברוך הוא על המצרים\u0004 — היה \u0003לח מבחוץ ויבש מבפנים, שנאמר: \"ויהי שחין אבעבעת פרח באדם ובבהמה\"\u0004 (שמות ט, י), כלומר, שחין זה היה יבש (\"שחין\") מבפנים ולח מבחוץ (\"אבעבועות פורח\").","ומה שאמרו \u0003\"ודלת הננעלת לא במהרה תפתח\", מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מה פירושו? \u0003מר זוטרא אמר: סמיכה,\u0004 שאם אדם לא זכה להיסמך בתואר רבי בשעת הכושר שהזדמנה לפניו וחלפה, עלול לעבור זמן רב עד שיזכה לכך. \u0003רב אשי אמר: כל המריעין לו,\u0004 מי שהורע מזלו, \u0003לא במהרה\u0004 שבים ו\u0003מטיבין לו. רב אחא מדיפתי אמר: לעולם אין מטיבין לו\u0004 עוד. ומעירים: \u0003ו\u0004דברים אלה \u0003לא\u0004 פירוש המימרא \u0003היא,\u0004 אלא \u0003רב אחא מדיפתי מילתא דנפשיה\u0004 \u0005[דבר של עצמו]\u0006 \u0003הוא\u0004 ש\u0003אמר,\u0004 שכך אירע לו בעצמו.","\u0003ו\u0004על מה שאמרו \u0003\"והלוקח בית בארץ ישראל\u0004 — \u0003כותבין עליו אונו אפילו בשבת\",\u0004 תוהים: \u0003בשבת סלקא דעתך\u0004 \u0005[עולה על דעתך]?\u0006 וכי התירו איסור מלאכה בשבת לצורך זה?!","\u0003אלא כ\u0004פי ש\u0003אמר רבא התם\u0004 \u0005[שם]\u0006 בענין אחר: \u0003אומר\u0004 בשבת \u0003לגוי\u0004 לעשות מלאכה \u0003ועושה, הכי נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה ש\u0003אומר לגוי\u0004 שיכתוב שטר על המכירה \u0003ועושה\u0004 הגוי כדבריו. \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003אמירה לגוי\u0004 לעשות מלאכה בשבת איסור \u0003שבות היא\u0004 שאסרוהו חכמים, מכל מקום במקרה זה, \u0003משום\u0004 מצוות \u0003ישוב ארץ ישראל לא גזרו ביה\u0004 \u0005[בו]\u0006 \u0003רבנן\u0004 \u0005[חכמים]\u0006 לאסור.","ובענין זה \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: הלוקח\u0004 (הקונה) \u0003עיר בארץ ישראל, כופין אותו\u0004 עם זאת \u0003ליקח\u0004 (לקנות) \u0003לה\u0004 גם \u0003דרך מארבע רוחותיה, משום ישוב ארץ ישראל,\u0004 שתהא עיר זו פתוחה לכל צד.","אגב המדובר בתקנות שנעשו משום ישוב ארץ ישראל, מביאים כמה דברים כלליים בנושא זה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עשרה תנאין התנה יהושע\u0004 בן נון עם בני ישראל בכניסתם לארץ, שינהגו זה עם זה לפנים משורת הדין, ולא יקפידו על זכויותיהם."],["\u0003שיהו\u0004 כל האנשים \u0003מרעין\u0004 (רועים) את בהמותיהם \u0003בחורשין\u0004 (יער קטן), ולא יקפיד בעל היער על כך. \u0003ומלקטין עצים בשדותיהם\u0004 של אחרים ואין בעל השדה מעכב, \u0003ומלקטים עשבים בכל מקום\u0004 להאכיל לבהמה, \u0003חוץ מ\u0004בשדה \u0003תלתן,\u0004 שבעל השדה רוצה בקיום העשבים. \u0003וקוטמים נטיעות\u0004 (קוצצים ענפים צעירים) כדי להשתמש בהם כיחורים לנטיעה חדשה או להרכבה בעץ אחר, \u0003בכל מקום\u0004 גם בלא רשות הבעלים, \u0003חוץ מגרופיות\u0004 (יחורים) \u0003של זית,\u0004 שאין לוקחים מהם. \u0003ומעין היוצא בתחילה\u0004 (מעין חדש) \u0003בני העיר\u0004 כולה \u0003מסתפקין\u0004 (משתמשים לצרכיהם) \u0003ממנו,\u0004 ולא רק בעל האדמה שממנה יצא המעין. \u0003ו\u0004הכל \u0003מחכין\u0004 (מטילים חכות לדייג) \u0003בימה של\u0004 העיר \u0003טבריא\u0004 (טבריה) ולא רק בני שבט נפתלי שבנחלתו כלול ים כנרת, \u0003ובלבד שלא יפרוס קלע\u0004 (מחיצה במים לתפוס הדגים) \u0003ו\u0004בכך גורם ש\u0003יעמיד,\u0004 יעכב, \u0003את הספינה\u0004 העוברת שם.","\u0003ונפנין\u0004 לעשות צרכים \u0003לאחורי הגדר, ואפילו בשדה מליאה כרכום\u0004 שמשתמשים בו לתבלין. \u0003ו\u0004כן \u0003מהלכים בשבילי הרשות,\u0004 כלומר, בשבילים שבשדות פרטיים, שאינם דרך הרבים, \u0003עד שתרד\u0004 הגשמים של \u0003רביעה\u0004 (עונת הגשמים) ה\u0003שניה,\u0004 שאז ההילוך יכול לקלקל את התבואה שזרעו בשדה. \u0003ו\u0004כן מותר לעוברי דרכים להיות \u0003מסתלקין לצידי הדרכים\u0004 אף על פי שדורכים על שדהו של אדם פרטי \u0003מפני יתידות\u0004 (בליטות שבקרקע) \u0003הדרכים\u0004 המקשות על אדם ללכת בדרך, \u0003ו\u0004כן \u0003התועה בין הכרמים\u0004 ואינו מוצא דרך לצאת \u0003מפסיג\u0004 (מפסק, מחתך) \u0003ועולה מפסיג ויורד,\u0004 שמותר לו לחתוך מן הזמורות המסובכות כדי לצאת משם. \u0003ו\u0004כן תיקן ש\u0003מת מצוה,\u0004 אדם שמצאוהו מוטל מת ואין לו מי שיטפל בקבורתו, \u0003קונה מקומו,\u0004 שקוברים אותו במקום שנמצא ואין בעל השדה יכול לעכב. ומעתה דנים בדברים ומפרשים אותם לפרטיהם.","מה שאמרנו שתיקן יהושע \u0003שיהו מרעין בחורשין, אמר רב פפא: לא אמרן\u0004 \u0005[אמרנו]\u0006 שהתיר יהושע \u0003אלא\u0004 דווקא בהמה \u0003דקה ב\u0004יער \u0003גסה\u0004 (יער שבו עצים גדולים), שאין הבהמה הדקה מזיקה להם הרבה, \u0003אבל\u0004 בהמה \u0003דקה ב\u0004חורשה \u0003דקה,\u0004 כלומר, ביער שעציו קטנים ודקים, או בהמה \u0003גסה ב\u0004חורשה \u0003גסה\u0004 — \u0003לא. וכל שכן\u0004 בהמה \u0003גסה ב\u0004חורשה \u0003דקה\u0004 ש\u0003לא,\u0004 שכן מזיקה אותה ביותר.","\u0003ו\u0004ביחס לתקנה שעשה שיהיו \u0003מלקטין עצים משדותיהם,\u0004 מסבירים: \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 דווקא ב\u0003היזמי והיגי\u0004 שהם מיני קוצים, \u0003אבל בשאר עצים\u0004 שיש להם חשיבות וערך — \u0003לא,\u0004 שאותם לא הפקירו בעלי השדות. \u0003ואפילו בהיזמי והיגי לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא במחוברין,\u0004 שעל ידי כך מסייע קצת לבעל השדה, שהוא מנקה את שדהו, \u0003אבל בתלושין\u0004 — \u0003לא,\u0004 שבוודאי הכינם בעל השדה לעצמו.","\u0003ואפילו במחוברין\u0004 — \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שמותר ללקטם \u0003אלא בלח, אבל ביבשים\u0004 — \u0003לא,\u0004 שהם מוכנים להסקה. \u0003ו\u0004כן מוגבל היתר זה \u0003בלבד שלא ישרש,\u0004 שלא יעקור את שורשי הקוצים הללו ממקומם.","ועוד אמרו שתיקן שיהיו \u0003מלקטין עשבים בכל מקום, חוץ משדה תלתן.\u0004 ושואלים: \u0003למימרא\u0004 \u0005[האם\u0006 מכאן אפשר \u0005לומר]\u0006 שצמח ה\u0003תלתן מעלו\u0004 \u0005[מועילים]\u0006 \u0003לה עשבים\u0004 הצומחים לידו? \u0003ורמינהי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בענין כלאים: \u0003תלתן שעלתה\u0004 (צמחה) \u0003עם מיני עשבים\u0004 — \u0003אין מחייבין אותו לעקור\u0004 את העשבים משום כלאים. וטעמו של דבר — משום שעשבים אלה מזיקים לתלתן ואינו רוצה בקיומם, ואם כן מדוע אמרו שאסור לעקור עשבים הגדלים בשדה תלתן, שאין הם בכלל תקנת יהושע?","ומשיבים: \u0003אמר רב ירמיה, לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003כאן\u0004 במקום אחד מדובר שמגדל את התלתן \u0003ל\u0004צורך \u0003זרע\u0004 התלתן, ו\u0003כאן\u0004 במקום אחר מדובר שמגדל את התלתן \u0003לזירין\u0004 (לצורך הגבעולים), ומסביר את ההבדל; אם מגדלה \u0003לזרע\u0004 — \u0003קשו\u0004 \u0005[קשים]\u0006 \u0003לה עשבים, דמכחשי לה\u0004 \u0005[שמכחישים אותה]\u0006 את היבול, ובמקרה שכזה אין מחייבים לעקור העשבים משום כלאים. ואם מגדלה \u0003לזירין\u0004 — \u0003מעלי\u0004 \u0005[מועילים]\u0006 \u0003לה\u0004 העשבים, \u0003דכי קיימי ביני\u0004 \u0005[שאם\u0006 גבעולי התלתן \u0005עומדים בין]\u0006 ה\u0003עשבים מירכבא\u0004 \u0005[\u0006התלתן \u0005רוכב,\u0006 נכרך, \u0005עליהם],\u0006 ובמקרה שכזה אסור ללקוט עשבים משדה תלתן של חבירו.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הבדל אחר: \u0003כאן\u0004 שאין העשבים מועילים לשדה תלתן, מדובר שמגדל את התלתן \u0003ל\u0004צורך \u0003אדם,\u0004 ו\u0003כאן\u0004 שהעשבים מועילים לשדה התלתן מדובר שמגדל את התלתן \u0003לבהמה,\u0004 ש\u0003כיון\u0004 ש\u0003לבהמה הוא\u0004 ש\u0003זרעה, עשבים נמי מיבעי\u0004 \u0005[גם כן צריכים]\u0006 \u0003לה\u0004 ולכן אסור לאדם לעקור משדה תלתן של חבירו את העשבים. ושואלים: \u0003ומנא ידעינן\u0004 \u0005[ומנין אנו יודעים]\u0006 אם זרע את התלתן לצורך אדם או לבהמה? \u0003אמר רב פפא:\u0004 אם \u0003שאריה משארי\u0004 \u0005[עשה ערוגות]\u0006 — הרי זה ודאי \u0003לאדם,\u0004 ואם \u0003לא שאריה משארי\u0004 \u0005[עשה ערוגות]\u0006 אלא זרע בצפיפות — הרי זה \u0003ל\u0004צורך מאכל \u0003בהמה.\u0004","עוד שנינו בין התקנות: ש\u0003קוטמין נטיעה בכל מקום, חוץ מגרופיות\u0004 (ענפים) \u0003של זית.\u0004 ואת פרטי דיניו של דבר זה \u0003פירשו ר' תנחום ור' ברייס משום\u0004 \u0005[בשם]\u0006 \u0003זקן אחד:\u0004 אף שהתירו לקטום נטיעה מאילן, התירו רק אם משאיר \u0003בזית\u0004 (לא בגרופית) \u0003כ\u0004גודל \u0003ביצה\u0004 מלמטה בסמוך לגזע, ואם חותך \u0003בקנים ובגפנים\u0004 משאיר \u0003מן הפקק\u0004 (פרק, קשר שבענף) \u0003ולמעלה, ושאר כל האילנות\u0004 נוטל ענפים \u0003מן אובו\u0004 (מעוביו, ענפים הפונים לכל עבר) \u0003של אילן ולא מן חודו של אילן,\u0004 ששם הוא עצמו מוסיף לגדול, ואף באובו, נוטל דווקא","\u0003מן\u0004 הענף ה\u0003חדש\u0004 שצמח באותה שנה \u0003שאינו עושה פירות\u0004 עדיין, \u0003ולא מן ישן שהוא עושה פירות.\u0004 ונוטל ענף \u0003ממקום שאינו רואה את החמה\u0004 ואינו עשוי לגדל פירות הרבה,"],["\u0003ולא ממקום שהוא רואה את החמה, שנאמר: \"וממגד תבואת שמש\"\u0004 (דברים לג, יד), ומכאן למדים שהשמש מבשילה ומשפרת את הפירות, ואם נוטל ענף ממקום זה גורם נזק רב יותר.","עוד נאמר בין התקנות כי יהושע תיקן ש\u0003מעין היוצא תחילה בני העיר מסתפקין ממנו.\u0004 ועל כך \u0003אמר רבה בר רב הונא: ונותן לו\u0004 המשתמש במעין לבעל הקרקע שממנה יצא המעין \u0003דמים.\u0004 ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו]\u0006 אלא הכל מסתפקים מן המעין בחינם.","ועוד נאמר בין התקנות ש\u0003מחכין\u0004 (מטילים חכות) \u0003בימה של\u0004 העיר \u0003טבריא\u0004 על מנת לדוג דגים, \u0003ובלבד שלא יפרוס קלע ויעמיד את הספינה.\u0004 ומעירים על כך: \u0003אבל צד הוא ברשתות ובמכמרות.\u0004 וכן \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003בראשונה,\u0004 בראשית התיישבותם בארץ \u0003התנו\u0004 ה\u0003שבטים\u0004 בעם ישראל \u0003זה עם זה ש\u0004אדם מישראל \u0003לא יפרוס קליעה\u0004 בימה של טבריה \u0003ויעמיד את הספינה, אבל צד הוא ברשתות ובמכמרות.\u0004","ועוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ימה של טבריא בחלקו של\u0004 שבט \u0003נפתלי היתה, ולא עוד, אלא שנטל\u0004 רצועת יבשה כמידת \u0003מלא חבל חרם\u0004 (מכמורת) \u0003בדרומה\u0004 של ים טבריה, \u0003לקיים מה שנאמר\u0004 בברכת משה לנפתלי \u0003\"ים ודרום ירשה\"\u0004 (דברים לג, כג).","ובענין דומה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן אלעזר אומר:\u0004 עצים \u0003תלושין שבהרים\u0004 — \u0003בחזקת כל השבטים הן עומדים\u0004 והכל מותרים לקחתם, \u0003ו\u0004אילו עצים \u0003מחוברים\u0004 הם \u0003בחזקת אותו השבט\u0004 בו הם נמצאים, שזו היא נחלתו.","\u0003ו\u0004עוד בענין נחלת השבטים, \u0003אין לך כל שבט ושבט מישראל שאין לו\u0004 בנחלתו חלק \u0003בהר ובשפלה ובנגב ובעמק, שנאמר\u0004 לכל השבטים: \u0003\"פנו וסעו לכם ובאו הר האמרי ואל כל שכניו בערבה בהר\u0004 ו\u0003בשפלה ובנגב ובחוף הים\u0004 ארץ הכנעני והלבנון עד הנהר הגדול נהר פרת. ראה נתתי לפניכם את הארץ באו ורשו את הארץ\u0003\"\u0004 (דברים א, ז–ח). \u0003וכן אתה מוצא בכנענים ובפריזים ובאמוריים שלפניהם,\u0004 שגם הם לקחו נחלה בכל סוגי הקרקע, \u0003שנאמר\u0004 באותו כתוב \u0003\"ואל כל שכניו\"\u0004 של האמורי, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שאף \u0003שכניו הכי הוו\u0004 \u0005[כך היו],\u0006 שהיתה נחלתם כוללת כל סוגי הקרקעות.","ועוד תיקן יהושע שיהיו \u0003נפנין לאחורי הגדר, ואפילו בשדה שהיא מלאה כרכום. אמר רב אחא בר יעקב: לא נצרכה\u0004 הלכה זו, \u0003אלא\u0004 להתיר \u0003ליטול הימנו\u0004 מאותו המקום \u0003צרור\u0004 כדי לקנח בו. \u0003אמר רב חסדא: ו\u0004מותר ליטול צרור \u0003אפילו בשבת. מר זוטרא חסידא\u0004 \u0005[החסיד]\u0006 במקרה כזה \u0003שקיל ומהדר\u0004 \u0005[היה לוקח\u0006 צרור מאותו מקום בו נפנה \u0005ו\u0006אחר כך \u0005מחזירו\u0006 למקומו\u0005],\u0006 \u0003ואמר ליה לשמעיה\u0004 \u0005[והיה אומר לו לשמשו]\u0006 \u0003למחר: זיל שירקיה\u0004 \u0005[לך והחלק אותו]\u0006 בטיט שלא יגרם נזק על ידו.","ועוד תיקן יהושע שיהיו \u0003מהלכין בשבילי הרשות עד שתרד רביעה שניה. אמר רב פפא: והאי דידן\u0004 \u0005[וזו\u0006 הקרקע \u0005שלנו\u0006 בבבל\u0005]\u0006 \u0003אפילו טל קשי\u0004 \u0005[קשה]\u0006 \u0003לה\u0004 ולכן אין לדרוך כלל בשדות זרועים לאחר שירד עליהן טל.","ועוד תיקן יהושע שיהיו \u0003מסלקין\u0004 (פונים) \u0003לצידי הדרכים מפני יתידות הדרכים.\u0004 מסופר: \u0003שמואל ורב יהודה הוו שקלי ואזלי באורחא\u0004 \u0005[היו מהלכים בדרך],\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 \u0003מסתלק שמואל לצידי הדרכים; אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה:\u0004 וכי \u0003תנאין שהתנה יהושע, אפילו בבבל\u0004 הם חלים, שעל סמך זה פנה שמואל לצידי הדרכים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שאני אומר:\u0004 תנאים אלה חלים לא רק בבבל \u0003אפילו ב\u0004שאר \u0003חוצה לארץ\u0004 שהם תנאי יישובם של בני אדם, ואינם קשורים לארץ ישראל דווקא.","מסופר: \u0003רבי ור' חייא הוו שקלי ואזלי באורחא\u0004 \u0005[היו מהלכים בדרך],\u0006 \u0003אסתלקו\u0004 \u0005[פנו]\u0006 \u0003לצידי הדרכים\u0004 מפני שקשה היה ללכת באמצע הדרך. \u0003הוה קא\u0004 \u0005[היה]\u0006 \u0003מפסיע\u0004 בפסיעות גדולות \u0003ואזיל\u0004 \u0005[והולך]\u0006 \u0003ר' יהודה בן קנוסא קמייהו\u0004 \u0005[לפניהם]\u0006 שהיה מקפיד ללכת בדרך עצמה והיה מדלג בתוכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבי לר' חייא: מי הוא זה שמראה גדולה בפנינו?\u0004 כלומר, שמראה לנו שהוא מדקדק בדברים יותר ממה שהוא מחוייב?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא: שמא ר' יהודה בן קנוסא תלמידי הוא,\u0004 \u0003ו\u0004אם זה הוא — \u0003כל מעשיו לשם שמים,\u0004 ומתוך חסידות הוא עושה ולא מיוהרה. \u0003כי מטו לגביה, חזייה\u0004 \u0005[כאשר הגיעו אליו ראה אותו]\u0006 רבי, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי לאו\u0004 \u0005[אלמלא]\u0006 \u0003יהודה בן קנוסא את\u0004 \u0005[אתה],\u0006 \u0003גזרתינהו לשקך בגיזרא דפרזלא\u0004 \u0005[הייתי חותך את שוקך במסור של ברזל],\u0006 כלומר, הייתי מחרים אותך, שאין ראוי לאדם לנהוג כך ברבים.","ועוד תיקן יהושע ש\u0003התועה בין הכרמים, מפסיג ויורד מפסיג ועולה.\u0004 ובאותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה חבירו\u0004 שהוא \u0003תועה בין הכרמים,\u0004 הריהו \u0003מפסיג ועולה מפסיג ויורד עד שמעלהו לעיר או לדרך.\u0004 \u0003וכן הוא\u0004 עצמו \u0003שתועה בין הכרמים, מפסיג ועולה מפסיג ויורד עד שיעלה לעיר או לדרך.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 מקומו של \u0003\"וכן\"\u0004 זה, במקרה שהוא עצמו תועה שמשמע שיש בדבר זה חידוש נוסף על מה שנאמר בתחילה? לכאורה היה צריך לומר להיפך, שלצורך החבר מותר פחות מאשר לצורך עצמו! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 כאשר אדם עושה עבור \u0003חבירו\u0004 שתועה, \u0003הוא\u0004 המוליכו \u0003דידע\u0004 \u0005[שיודע]\u0006 את הדרך \u0003להיכא\u0004 \u0005[להיכן]\u0006 היא מובילה — התירו לו \u0003מסלק דניפסוג\u0004 \u0005[לפנות ולפסג],\u0006 משום שוודאי ילך בדרך הקצרה ביותר, \u0003אבל הוא\u0004 עצמו שתועה \u0003דלא ידע להיכא קא סליק\u0004 \u0005[שאינו יודע להיכן הוא הולך]\u0006 — ש\u0003לא ניפסוג\u0004 \u0005[יפסג],\u0006 אלא \u0003נהדריה נהדר בי מיצרי\u0004 \u0005[יסובב סביב מיצרי\u0006 השדה\u0005]\u0006 עד שיגיע למקום ממנו יוכל לצאת וללכת לדרכו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף הוא התועה בכרם מותר לו לפסג בה.","ועל הלכה זו של חבירו התועה שואלים: מה צורך לתקנה זו של יהושע והלא \u0003הא דאורייתא הוא\u0004 \u0005[זו\u0006 מצווה \u0005מן התורה היא],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מפורש בכתוב שיש חובת השבת אבידה בחפציו של חבירו, \u0003השבת גופו מניין\u0004 שגם כן חייב אדם לסייע לאחר לצורך גופו? \u0003תלמוד לומר \"והשבותו\"\u0004 (דברים כב, ב) במובן — שישיב לו את עצמו!","ומשיבים: \u0003דאורייתא הוא דקאי בי מיצרי\u0004 \u0005[\u0006המצווה \u0005מן התורה היא\u0006 דווקא כ\u0005שעומד בין המיצרים]\u0006 ומשם מצווה הוא לעזור לו, שאין זה כרוך בנזקים של אדם אחר. \u0003אתא\u0004 \u0005[בא]\u0006 \u0003הוא\u0004 יהושע \u0003תקין\u0004 \u0005[\u0006ו\u0005תיקן]\u0006 שאף בתועה בין הכרמים, שיש משום נזק לאחר — גם כן ש\u0003מפסיג ועולה מפסיג ויורד.\u0004","ועוד תיקן יהושע ש\u0003מת מצוה קנה\u0004 את \u0003מקומו\u0004 לקבורה. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003המוצא מת מוטל באיסרטיא\u0004 (דרך ראשית) \u0003מפנהו לימין איסרטיא או לשמאל איסרטיא.\u0004 היו שם \u0003שדה בור\u0004 (שאינו חרוש) \u0003ושדה ניר\u0004 (חרוש) — \u0003מפנהו לשדה בור.\u0004","\u0003שדה ניר ושדה זרע\u0004 (זרוע) — \u0003מפנהו לשדה ניר. היו שתיהן בורות,\u0004 או שהיו \u0003שתיהן נירות,\u0004 או \u0003שתיהן זרועות\u0004 — \u0003מפנהו למקום שירצה,\u0004 משמע שלא תמיד קוברים את המת במקומו!","\u0003אמר רב ביבי:\u0004 מדובר כאן \u0003ב\u0004מת ש\u0003מוטל על המיצר,\u0004 שאי אפשר לקוברו שם באותו מקום, ו\u0003מתוך שניתן לפנותו\u0004 ממקומו הצידה קצת, \u0003מפנהו לכל מקום שירצה.\u0004","לאחר בירור הפרטים דנים ברשימה כולה. \u0003אמרי\u0004 \u0005[אומרים]:\u0006 לפי ברייתא זו \u0003עשרה\u0004 תקנות תיקן יהושע? הלא \u0003הני חד סרי הויין\u0004 \u0005[אלו\u0006 המנויות בברייתא לפנינו \u0005אחת עשרה הן]!\u0006 ומשיבים: תקנה זו ש\u0003מהלכין בשבילי הרשות —\u0004 \u0003שלמה\u0004 המלך \u0003אמרה.\u0004","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שכלו פירותיו מן השדה\u0004 והשדה עתה ריק, \u0003ו\u0004בכל זאת בעל השדה \u0003אינו מניח בני אדם ליכנס בתוך שדהו\u0004 לקצר את הדרך, \u0003מה הבריות אומרות עליו\u0004 — \u0003מה הנאה יש לפלוני\u0004 בכך שמונע מהרבים את המעבר בשדותיו, \u0003ומה\u0004 כבר היו \u0003הבריות מזיקות לו\u0004 אילו היו עוברות שם? ו\u0003עליו הכתוב אומר: \"מהיות טוב אל תקרי רע\",\u0004 אם יכול אתה להיקרא טוב אל תיקרא אדם רע. ותוהים: \u0003ומי כתיב\u0004 \u0005[והאם כתוב]\u0006 במקרא פסוק כזה \u0003\"מהיות טוב אל תקרי רע\"?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כתיב כי האי גוונא\u0004 \u0005[כתוב כעין זה],\u0006 שכן כך נאמר בדברי שלמה המלך: \u0003\"אל תמנע טוב מבעליו בהיות לאל ידך לעשות\"\u0004 (משלי ג, כז), ותקנה זו להלך בשבילי הרשות, שהיא משום \"אל תמנע טוב מבעליו\" — של שלמה המלך היא.","ושואלים: \u0003ותו\u0004 \u0005[ועוד]\u0006 תקנות אחרות שתיקן יהושע בן נון \u0003ליכא\u0004 \u0005[אין]\u0006 אלא העשר הללו בלבד? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 עוד תקנה זו שמסר \u0003ר' יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: בשעת הוצאת זבלים,\u0004 שהכל מוציאים את הזבלים לרחוב \u0003אדם מוציא זבלו לרשות הרבים וצוברו\u0004 שם \u0003כל שלשים\u0004 יום, \u0003כדי שיהא נישוף\u0004 (נדרס) \u0003ברגלי אדם וברגלי בהמה\u0004 לטייבו ולהכשירו לשם זיבול, \u0003שעל מנת כן הנחיל יהושע לישראל את הארץ!\u0004","ועוד \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 תקנה זו שמסר \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: תנאי בית דין הוא, שיהא זה\u0004 שאינו בעל השדה \u0003יורד\u0004 (נכנס) \u0003לתוך שדה חבירו וקוצץ שוכו\u0004 (ענפו) \u0003של חבירו\u0004 כדי \u0003להציל נחיל שלו\u0004 של דבורים שעלה והתישב על הענף כדי שלא ישאר שם, \u0003ונותן לו\u0004 לחבירו בתשלום \u0003דמי שוכו של חבירו. ו\u0004כן","\u0003תנאי בית דין הוא, שיהא זה\u0004 החבר \u0003שופך יינו\u0004 מתוך חביתו שלו \u0003ומציל דובשנו\u0004 (חבית דבש) \u0003של חבירו\u0004 שנשברה, ומאבד יינו בכך שמכניס לתוך חביתו את דבש חבירו (היקר יותר מן היין) \u0003ו\u0004אחר כך \u0003נוטל דמי יינו מתוך דובשנו של חבירו,\u0004 ואין החבר יכול לומר שלא התנה עמו לעשות כן. \u0003ו\u0004כן \u0003תנאי בית דין הוא, שיהא זה\u0004 החבר \u0003מפרק את עציו\u0004 מעל חמורו \u0003וטוען\u0004 על חמורו את \u0003פשתנו של חבירו\u0004 כדי להצילו, \u0003ונוטל דמי עציו מתוך פשתנו של חבירו, שעל מנת כן הנחיל יהושע לישראל את הארץ!\u0004","ומשיבים: \u0003ביחידאי\u0004 \u0005[ב\u0006דברים שאמרום חכמים \u0005יחידים]\u0006 \u0003לא קאמרינן\u0004 \u0005[אמרנו]\u0006 כתקנות של יהושע, ושנינו רק תקנות המוסכמות על דעת הכל."],["וחוזרים ומקשים: \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003ר' אבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' יוחנן: אחד אילן הנוטה לתוך שדה חבירו, ואחד אילן הסמוך למצר,\u0004 לגבול שדהו ושדה חבירו — \u0003מביא\u0004 בעל האילן מפירותיו ביכורים \u0003וקורא\u0004 במקדש את הפרשה כדרך כל מביאי ביכורים מפירות שדותיהם, \u0003שעל מנת כן הנחיל יהושע לישראל את הארץ\u0004 שלא יקפידו על כך. ואם כן יש עוד תקנה שאינה מנויה בין עשר התקנות!","\u0003אלא\u0004 יש לומר \u0003מאן תנא\u0004 \u0005[מי הוא ששנה]\u0006 \u0003עשרה תנאין שהתנה יהושע\u0004 — \u0003ר' יהושע בן לוי הוא,\u0004 ור' יוחנן חולק עליו שסבור שהיו יותר, וכן חלקו עליו חכמים אחרים שהוזכרו מקודם. ומעירים, כי \u0003רב גביהה מבי כתיל מתני לה בהדיא\u0004 \u0005[היה שונה\u0006 את הדברים \u0005במפורש]\u0006 כך: \u0003ר' תנחום ור' ברייס אמרי\u0004 \u0005[אמרו]\u0006 \u0003משום\u0004 \u0005[בשם]\u0006 \u0003זקן\u0004 (חכם) \u0003אחד, ומנו\u0004 \u0005[ומי הוא]?\u0006 — \u0003ר' יהושע בן לוי! עשרה תנאין התנה יהושע.\u0004","כיון שהזכרנו עשר תקנות לטובת הכלל שתיקן יהושע, מביאים עוד תקנות כיוצא בהן שתיקנו מנהיגי ישראל לרבים. \u0003עשרה תקנות תיקן עזרא\u0004 הסופר בימי שיבת ציון: שיהיו \u0003קורין\u0004 (קוראים) בתורה \u0003ב\u0004תפילת \u0003מנחה בשבת, וקורין\u0004 בתורה \u0003ב\u0004ימים \u0003שני ובחמישי, ודנין\u0004 בבתי דין \u0003בשני ובחמישי\u0004 בשבוע, \u0003ומכבסים\u0004 כביסה \u0003בחמישי בשבת, ואוכלין שום בערב שבת, ושתהא אשה משכמת ואופה\u0004 ביום שהיא צריכה לאפות בו, \u0003ושתהא אשה חוגרת בסינר. ושתהא אשה חופפת\u0004 את שערותיה קודם \u0003ו\u0004אחר כך \u0003טובלת\u0004 לטהרתה, \u0003ושיהו רוכלין מחזירין\u0004 (סובבים) \u0003בעיירות\u0004 ומוכרים תכשיטים וכשמים, \u0003ותיקן טבילה לבעלי קריין\u0004 (קרי) לפני שעוסקים בתורה ותפילה.","ומעתה מבארים ומפרטים את הדברים. מה שתיקן עזרא \u0003\"שיהו קוראין במנחה בשבת\"\u0004 טעמו — \u0003משום יושבי קרנות,\u0004 אנשים בטלים, שאין להם מה לעשות ואינם לומדים, תיקן להם שלא ייבטלו לגמרי וישמעו דברי תורה במנחה בשבת.","\u0003ו\u0004עוד תיקן עזרא \u0003\"שיהו קוראין בשני ובחמישי\".\u0004 ושואלים: תקנה זו \u0003עזרא תיקן? והא מעיקרא הוה מיתקנא\u0004 \u0005[והרי מתחילה,\u0006 מדורות ראשונים, \u0005היתה מתוקנת]\u0006 תקנה זו! \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על הפסוק \u0003\"וילכו שלשת ימים במדבר ולא מצאו מים\"\u0004 (שמות טו, כב), \u0003דורשי רשומות\u0004 שדרשו ברמז לשון המקרא \u0003אמרו: אין מים אלא תורה, שנאמר: \"הוי כל צמא לכו למים\"\u0004 (ישעיה נה, א),","\u0003כיון שהלכו שלשת ימים בלא תורה נלאו\u0004 (התעייפו) והתחילו להתאונן כמפורש שם, \u0003עמדו נביאים שביניהם\u0004 שהיו באותו דור \u0003ותיקנו להם שיהו קורין\u0004 בתורה \u0003בשבת, ומפסיקין\u0004 ואין קוראים בתורה \u0003באחד בשבת, וקורין\u0004 בתורה \u0003ב\u0004יום \u0003שני, ומפסיקין\u0004 בימים \u0003שלישי ורביעי, וקורין בחמישי, ומפסיקין ערב שבת, כדי שלא ילינו שלשה ימים\u0004 רצופים \u0003בלא תורה,\u0004 ואם כן תקנה זו קדומה היא, ולא של עזרא!","ומשיבים: \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003תקנו\u0004 שיקרא \u0003חד גברא תלתא פסוקי\u0004 \u0005[אדם אחד\u0006 בתורה \u0005שלושה פסוקים\u0006 בלבד\u0005],\u0006 \u0003אי נמי תלתא גברי תלתא פסוקי\u0004 \u0005[או גם כן\u0006 שיקראו \u0005שלושה אנשים שלושה פסוקים\u0006 בלבד\u0005],\u0006 ושלושה פסוקים אלה \u0003כנגד כהנים לוים וישראלים, אתא\u0004 \u0005[בא]\u0006 \u0003הוא,\u0004 עזרא, ו\u0003תיקן\u0004 שיקראו בתורה \u0003תלתא גברי\u0004 \u0005[שלושה אנשים]\u0006 \u0003ו\u0004לפחות \u0003עשרה פסוקי\u0004 \u0005[פסוקים],\u0006 \u0003כנגד עשרה בטלנין\u0004 היושבים תמיד בבית המדרש ולומדים תורה ובטלים מכל עיסוק אחר, שהם קיומה הרוחני של העיר.","ועוד תיקן עזרא שיהיו \u0003דנין בשני ובחמישי\u0004 בשבוע. ומסבירים: \u0003דשכיחי, דאתו למקרא בסיפרא\u0004 \u0005[שמצויים\u0006 אז אנשים \u0005שבאים\u0006 לעיר \u0005לקרוא בספר\u0006 התורה\u0005]\u0006 ולכן תיקן שיקבעו גם את זמני מושב בית הדין באותם ימים.","ומה שתיקן \u0003שיהו מכבסין בחמישי בשבת\u0004 — \u0003משום כבוד שבת\u0004 תיקן זאת, כדי שיהו בגדים נקיים ונאים מוכנים ללובשם, והרי זה מכבוד שבת.","ועוד תיקן \u0003שיהו אוכלין שום בערב שבת.\u0004 ומסבירים: תקנה זו היתה \u0003משום\u0004 מצות \u0003עונה\u0004 (תשמיש המיטה) בליל שבת, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 במזמור \"אשרי האיש\": \u0003\"אשר פריו יתן בעתו\"\u0004 (תהלים א, ג), \u0003ו\u0004על כך \u0003אמר רב יהודה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב נחמן, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב כהנא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן:\u0004 פסוק זה רומז ל\u0003זה המשמש מטתו מערב\u0004 (ליל) \u0003שבת לערב שבת,\u0004 ולשם כך תיקן עזרא לאכול שום בערב שבת משום שיש באכילתו תועלת לכך.","אגב כך מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003חמשה דברים נאמרו בשום: משביע\u0004 את האוכלו, \u0003ומשחין\u0004 (מחמם אותו), \u0003ומצהיל פנים, ומרבה הזרע, והורג כנים\u0004 (תולעים וטפילים) \u0003שבבני מעיים; ויש אומרים:\u0004 אף \u0003מכניס אהבה ומוציא את הקנאה\u0004 ולכן תיקן עזרא אכילת שום סמוך לזמן עונה.","עוד תיקן עזרא \u0003שתהא אשה\u0004 ביום שברצונה לאפות \u0003משכמת ואופה.\u0004 וטעם הדבר — \u0003כדי שתהא פת מצויה לעניים\u0004 המחזרים על הפתחים בבוקר.","עוד תיקן עזרא \u0003שתהא אשה חוגרת בסינר\u0004 כעין בגד תחתון בנוסף לבגדיה העליונים — \u0003משום צניעותא\u0004 \u0005[צניעות].\u0006","על מה שתיקן עזרא \u0003שתהא אשה חופפת וטובלת,\u0004 שואלים: הלא אין זו תקנה של עזרא, שכן הלכה \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003היא!\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר בטהרת טומאה \u0003\"ורחץ את בשרו במים\"\u0004 (ויקרא יד, ט), הכוונה היא: \u0003שלא יהא דבר חוצץ בין בשרו למים,\u0004 ועוד דייקו מ\u0003\"את בשרו\" —\u0004 \"את\" הוא ביטוי הבא לרבות — וכוונתו לרבות \u0003את הטפל לבשרו, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 — \u0003שער,\u0004 שאף השיער אסור שתהיה בו חציצה, ואם כן בטבילת טהרה חייבים לחפוף את השערות מדין תורה כדי שלא תהיה בו חציצה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 יש צורך רק \u0003לעיוני דלמא מיקטר\u0004 \u0005[לעיין,\u0006 לבדוק, \u0005שמא נקשרה]\u0006 השערה, \u0003אי נמי מאוס מידי\u0004 \u0005[או גם כן\u0006 אם יש שם \u0005לכלוך כלשהו],\u0006 \u0003משום חציצה,\u0004"],["\u0003ואתא איהו\u0004 \u0005[ובא הוא,\u0006 עזרא\u0005]\u0006 ו\u0003תיקן חפיפה,\u0004 שלא יסתפקו בבדיקה בלבד, אלא יחפפו ראשיהן.","עוד תיקן \u0003שיהו רוכלין מחזרין בעיירות.\u0004 וטעם הדבר — \u0003משום תכשיטי\u0004 (בשמים וקישוטים) \u0003נשים, כדי שלא יתגנו\u0004 הנשים היושבות בעיירות \u0003על בעליהם,\u0004 שאם לא תהיינה מטופחות ומבושמות יכולים הבעלים למאוס בהן.","עוד נאמר ש\u0003תיקן טבילה לבעלי קריין.\u0004 ותוהים: מה מקום יש לתקנה זו והלא דין \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא! דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואיש כי תצא ממנו שכבת זרע ורחץ את בשרו במים\"\u0004 (ראה ויקרא טו, טז)! ומשיבים: \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא\u0004 שצריך לטבול \u0003לתרומה וקדשים\u0004 שאסור לגעת בהם ולאוכלם בטומאה, \u0003אתא\u0004 \u0005[בא]\u0006 \u0003הוא,\u0004 עזרא, ו\u0003תיקן\u0004 ש\u0003אפילו לדברי תורה\u0004 צריך בעל קרי לטבול, לפני שעוסק הוא בתורה ובתפילה.","ועוד בענין תקנות: \u0003עשרה דברים נאמרו בירושלים\u0004 שמייחדים אותה משאר המקומות: \u0003אין הבית\u0004 נעשה \u0003חלוט בה,\u0004 שבית שקונה אדם בירושלים אינו נעשה קניינו המוחלט. \u0003ואינה מביאה עגלה ערופה\u0004 גם אם נמצא ליד העיר הרוג שלא נודע מי הכהו. \u0003ואינה נעשית\u0004 לעולם \u0003עיר הנדחת,\u0004 כלומר, שאין חלים עליה דיני עיר הנדחת, גם אם היו רוב יושביה עובדי עבודה זרה.","\u0003ואינה מטמאה בנגעים,\u0004 שאין חלים בה דיני נגעי צרעת הבית. \u0003ואין מוציאין בה\u0004 מן הבתים \u0003זיזין וגזוזטראות\u0004 לרשות הרבים. \u0003ואין עושין בה\u0004 בתחום העיר \u0003אשפתות\u0004 (ריכוזי אשפה). \u0003ואין עושין בה כבשונות\u0004 של סיד או כלי חרס. \u0003ואין עושין בה גנות ופרדסות, חוץ מגנות וורדין שהיו\u0004 בירושלים \u0003מימות נביאים הראשונים\u0004 ולא ביטלון. \u0003ואין מגדלים בה תרנגולין. ואין מלינין בה את המת,\u0004 אלא קוברים אותו בו ביום. ומעתה מבררים ומפרשים את פרטי הדברים הללו.","אמרנו ש\u0003אין הבית חלוט בה,\u0004 ומסבירים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין בתי ערי חומה: \u0003\"וקם הבית\u0004 אשר בעיר \u0003אשר לו חומה לצמתת לקנה אתו לדרתיו\"\u0004 (ויקרא כה, ל), \u0003וקסבר\u0004 \u0005[וסבר]\u0006 תנא זה כי \u0003לא נתחלקה ירושלים\u0004 בנחלה \u0003לשבטים\u0004 מסויימים, אלא היא שייכת לכל ישראל, וכיון שאינה אחוזת נחלה לשבט או משפחה אין אדם יכול לקנות בה אחוזה לעולם.","והטעם מדוע \u0003אינה מביאה עגלה ערופה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין עגלה ערופה: \u0003\"כי ימצא חלל באדמה אשר ה' אלהיך נתן לך לרשתה\"\u0004 (דברים כא, א), \u0003וירושלים לא נתחלקה לשבטים,\u0004 שאינה בכלל הארץ שניתנה לאחוזת שבט מסויים (\"נותן לך לרשתה\").","והטעם מדוע \u0003אינה נעשית עיר הנדחת\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדין עיר הנידחת: \"באחת \u0003עריך\u0004 אשר ה' אלהיך נותן לך לשבת שם...\" (דברים יג, יג), \u0003וירושלים לא נתחלקה לשבטים\u0004 ואם כן אינה בכלל \"עריך\" השייכות לך (\"נותן לך לשבת שם\").","\u0003ואינה מטמאה בנגעים\u0004 — מאותו טעם, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדיני נגעי בתים: \u0003\"\u0004כי תבואו אל ארץ כנען אשר אני נותן לכם לאחוזה \u0003ונתתי נגע צרעת בבית ארץ אחזתכם\"\u0004 (ויקרא יד, לד), \u0003וירושלים לא נתחלקה לשבטים,\u0004 ואינה \"אחוזה\" של אדם מסויים.","\u0003ואין מוציאין בה זיזין וגזוזטראות\u0004 — משני טעמים: \u0003מפני אהל הטומאה,\u0004 כדי שלא יאהילו הזיזים על טומאת המת ויביאו טומאה על האנשים המהלכים ברשות הרבים תחתם, וייטמאו האנשים בכך. \u0003ו\u0004עוד \u0003משום\u0004 ש\u0003לא ליתזקו\u0004 \u0005[ינזקו]\u0006 \u0003עולי רגלים\u0004 הבאים במספר רב לירושלים בזיזים הללו, אלא יוכלו ללכת בהרחבה וללא חשש.","\u0003ואין עושין בה אשפתות\u0004 — \u0003משום שקצים\u0004 שדרכם להתרבות באשפתות, וירבו טומאה במותם.","\u0003ואין עושין בה כבשונות\u0004 — \u0003משום קוטרא\u0004 \u0005[עשן],\u0006 שלא יכער את פני העיר.","\u0003ואין עושין בה גנות ופרדסין\u0004 — \u0003משום סירחא\u0004 \u0005[סירחון]\u0006 של הזבל הנחוץ לגינות.","\u0003ואין מגדלין בה תרנגולין\u0004 — \u0003משום קדשים,\u0004 לפי שמחטטים באשפה ועלולים להביא שרצים מתים במגע עם בשר הקדשים, ולטמאם.","\u0003ואין מלינין בה את המת\u0004 — הרי זה \u0003גמרא\u0004 \u0005[מסורת]\u0006 בידינו, ואין לנו טעם ברור לדבר.","וחוזרים לפירוש המשנה. שנינו בה: \u0003אין מגדלין חזירים בכל מקום.\u0004 ומביאים טעמו של דבר, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כשצרו\u0004 בני \u0003בית חשמונאי זה על זה, היה הורקנוס מבפנים\u0004 נצור בתוך ירושלים בפנים מבעד לחומה \u0003ואריסטובלוס מבחוץ. ובכל יום היו משלשים\u0004 (מורידים) הנצורים \u0003להם\u0004 לאנשי אריסטובלוס בחוץ \u0003בקופה\u0004 (בסל) \u0003דינרין, והיו מעלים להם\u0004 בתמורה לכך כבשים לצורך קרבנות \u0003תמידים\u0004 כדי שיוכלו כל יום להקריב את קרבן התמיד במקדש בבקר ובערב.","\u0003היה שם זקן אחד שהיה מכיר בחכמת יוונית, אמר להם\u0004 לצרים ברמז על ידי חכמה יוונית: \u0003כל זמן שעוסקין בעבודה\u0004 במקדש \u0003אין נמסרים בידכם. למחר שילשלו\u0004 כתמיד \u0003דינרין בקופה, והעלו להם\u0004 במקום כבש \u0003חזיר. כיון שהגיע\u0004 החזיר \u0003לחצי החומה נעץ צפרניו\u0004 (טלפיו) \u0003בחומה, ונזדעזעה ארץ ישראל\u0004 בשטח של \u0003ארבע מאות פרסה על ארבע מאות פרסה.\u0004","\u0003באותה שעה אמרו: ארור האיש שיגדל חזירים, וארור האדם שילמד את בנו חכמת יוונית. ועל אותה שעה\u0004 של מצוקה ומלחמה \u0003שנינו: מעשה שבא עומר\u0004 להקרבה במקדש \u0003מגנות הצריפין\u0004 שהוא מקום רחוק ולא רגיל, \u0003ושתי הלחם מבקעת עין סוכר,\u0004 לפי שכל השטח הסמוך לירושלים נחרב במצור.","כיון שהוזכרה הלכה זו בחכמה יוונית, שואלים: \u0003וחכמת יוונית מי אסירא\u0004 \u0005[האם\u0006 היא \u0005אסורה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר רבי: בארץ ישראל\u0004"],["השימוש ב\u0003לשון סורסי\u0004 (ארמי סורי) \u0003למה?\u0004 מדוע ידברו יהודים בלשון ארמית, שבה היו רגילים? אלא ידברו \u0003או לשון הקדש\u0004 שהוא לשונם \u0003או לשון יונית\u0004 שהיא לשון השלטון! \u0003ו\u0004כיוצא בזה \u0003אמר ר' יוסי:\u0004 ב\u0003בבל לשון ארמי\u0004 שמדברים בו יהודים \u0003למה? או\u0004 שידברו \u0003לשון הקדש\u0004 שהיא לשונם, \u0003או\u0004 שידברו \u0003לשון פרסי\u0004 שהיא לשון השלטון, והרי שחכמת יוונית מותרת! ומתרצים, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 יש להבחין בין הדברים, \u0003לשון יוני לחוד\u0004 שהוא מותר, \u0003חכמת יונית לחוד\u0004 והיא שנאסרה.","ומקשים על כך: \u0003וחכמת יונית מי אסירא\u0004 \u0005[האם\u0006 היא \u0005אסורה]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל משום\u0004 (בשם) \u0003רבן שמעון בן גמליאל,\u0004 על הכתוב \u0003\"עיני עוללה לנפשי מכל בנות עירי\"\u0004 (איכה ג, נא), אמר שכך אירע לו עצמו: \u0003אלף ילדים\u0004 (צעירים) \u0003היו בבית אבא,\u0004 בבית הנשיאים ממשפחת הלל, \u0003חמש מאות מהם למדו תורה, חמש מאות\u0004 האחרים \u0003למדו חכמת יונית, ולא נשתייר מהם\u0004 לאחר המלחמות ומפלת ביתר \u0003אלא אני כאן ובן אחי אבא בעסיא!\u0004 משמע שמותר ללמוד חכמת יוונית!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003בית רבן גמליאל, שהיו קרובים למלכות,\u0004 ומשום כך היו צריכים ללמוד חכמת יוונית. \u0003וכדתניא\u0004 \u0005[וכמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003המספר קומי\u0004 (תספורת מיוחדת לגויים) — \u0003הרי זה מדרכי האמורי\u0004 ואסור. ואולם \u0003אבטולמוס בר ראובן התירו לו\u0004 חכמים \u0003לספר קומי, מפני שהוא קרוב למלכות.\u0004 וכיוצא בזה \u0003של בית רבן גמליאל התירו להם לספר\u0004 (לעסוק) \u0003בחכמת יונית, מפני שקרובים למלכות.\u0004","שנינו במשנה ש\u0003לא יגדל אדם את הכלב אלא אם כן קשור בשלשלאות כו'.\u0004 ומביאים באותו ענין: \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003לא יגדל אדם את הכלב\u0004 — \u0003אלא אם כן קשור בשלשלת, אבל מגדל הוא\u0004 כלב \u0003בעיר הסמוכה לספר\u0004 (לגבול), \u0003וקושרו ביום ומתירו בלילה\u0004 לצורך שמירה.","ועוד באותו ענין, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' אליעזר הגדול אומר: המגדל כלבים\u0004 הרי הוא \u0003כמגדל חזירים.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מכאן]\u0006 ומה הוסיף על האיסור שבמשנה לגדל כלבים? ומשיבים: \u0003למיקם עליה\u0004 \u0005[לעמוד,\u0006 להתחייב \u0005על כך]\u0006 \u0003ב\"ארור\",\u0004 שלא רק איסור, אלא גם קללה יש בדבר.","\u0003אמר רב יוסף בר מניומי אמר רב נחמן: בבל כעיר הסמוכה לספר דמי\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 ומותר לגדל בה כלבים. ומעירים: \u0003תרגמה\u0004 \u0005[תרגם,\u0006 הסביר \u0005אותה]\u0006 שאין הדבר מתייחס לכל ארץ בבל, אלא על העיר \u0003נהרדעא\u0004 שבבבל שהיתה סמוך לספר.","ומעין הסבר לאיסור לגדל כלב, \u0003דריש\u0004 \u0005[דרש]\u0006 \u0003ר' דוסתאי\u0004 ש\u0003מן\u0004 העיר \u0003בירי:\u0004 מה שנאמר \u0003\"ובנחה יאמר שובה ה' רבבות אלפי ישראל\"\u0004 (במדבר י, לו), הרי זה בא \u0003ללמדך, שאין שכינה שורה על ישראל\u0004 אם היו \u0003פחות משני אלפים ושני רבבות,\u0004 שהוא \"רבבות\" ו\"אלפי\", ומיעוט רבים שנים. ואם היה \u0003חסר\u0004 נפש \u0003אחת\u0004 מביניהם, \u0003והיתה אשה מעוברת ביניהם וראויה להשלים\u0004 מספר זה, \u0003ונבח בה\u0004 עליה \u0003כלב\u0004 ונבהלה \u0003ו\u0004כתוצאה מכך \u0003הפילה\u0004 את עוברה, \u0003נמצא זה\u0004 בעליו של הכלב \u0003גורם לשכינה שתסתלק מישראל,\u0004 ומטעם זה אסרו לגדל כלבים.","וכעין זה מסופר: \u0003ההיא איתתא דעלת למיפא בההוא ביתא\u0004 \u0005[אשה אחת\u0006 שהיתה הרה \u0005שנכנסה לאפות\u0006 לחם \u0005בבית אחד],\u0006 \u0003נבח בה כלבא\u0004 \u0005[הכלב]\u0006 ונבהלה מאד. \u0003אמר לה מריה\u0004 \u0005[בעליו\u0006 של הכלב\u0005]:\u0006 \u0003לא תיסתפי מיניה, שקולי ניביה\u0004 \u0005[אל תפחדי ממנו\u0006 כי \u0005נטולות שיניו]\u0006 ואינו יכול לנשוך, \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003שקילי טיבותיך ושדיא אחיזרי\u0004 \u0005[קח\u0006 את \u0005טובתך וזרוק\u0006 אותה \u0005לקוצים],\u0006 כלומר, אין כבר תועלת בטובה זו שאתה מודיעני בה, שכן כבר נגרם נזק, ו\u0003כבר נד ולד\u0004 ממקומו, ועומדת אני להפיל.","שנינו במשנה ש\u0003אין פורסין נישבין\u0004 (מלכודות) \u0003ליונים\u0004 במרחק של שלושים ריס (ארבעה מילין) מן העיר. ושואלים: \u0003ומי אזלי כולי האי\u0004 \u0005[האם\u0006 היונים \u0005הולכות\u0006 רחוק \u0005כל כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מרחיקין את השובך מן העיר חמשים אמה\u0004 כדי שלא יזיקו היונים לגני העיר. נמצא שאין תחום מעופן אלא בחמישים אמה! \u0003אמר אביי: מישט שייטי טובא\u0004 \u0005[לשוט,\u0006 לעוף, \u0005שטות הן הרבה]\u0006 יותר מזה, ולכן אסור לפרוס מלכודות בתוך שלושים ריס מן העיר, ואולם \u0003כרסייהו\u0004 \u0005[כרסן]\u0006 \u0003בחמשים אמה מליא\u0004 \u0005[מלאה],\u0006 ולכן כשמרחיקן יותר מחמישים אמה אינן מזיקות הרבה, ולא גזרו על כך.","ושואלים: \u0003ומישט\u0004 \u0005[ו\u0006כי \u0005לשוט]\u0006 שטות הן רק \u0003שלשים ריס ותו\u0004 \u0005[ויותר]\u0006 \u0003לא?\u0004 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003בישוב\u0004 (איזור מיושב) \u0003אפילו מאה מיל לא יפרוס\u0004 את הנישבין ליונים! \u0003רב יוסף אמר\u0004 בתשובה לכך: מדובר בברייתא \u0003בישוב כרמים,\u0004 שיש בו כרמים סמוכים זה לזה, והיונים עוברות מכרם לכרם. \u0003רבה אמר:\u0004 מדובר כאן \u0003בישוב שובכין\u0004 ודרך היונים לעוף למרחקים גדולים משובך לשובך.","ומקשים על רבה: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו שאין פורסים \u0003משום שובכין גופייהו\u0004 \u0005[עצמם]\u0006 שהרי עלול הוא לצוד את היונים שמאותם השובכים! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר כאן \u0003ב\u0004שובכים שהם של \u0003גוי. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003ב\u0004שובכים שהם של יוני \u0003הפקר. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003ב\u0004שובכים \u0003דידיה\u0004",""],["\u0003החובל בחבירו\u0004 עשוי שיהא \u0003חייב עליו משום חמשה דברים,\u0004 שעשוי להתחייב בחמישה סוגים של תשלום עבור נזקים שונים שגורם בחבלה זו. והם: \u0003ב\u0004תשלום ה\u0003נזק, ב\u0004פיצוי עבור \u0003צער\u0004 (כאב), \u0003ב\u0004דמי ה\u0003ריפוי, ב\u0004פיצוי על \u0003שבת\u0004 (השבתה ממלאכה), \u0003ו\u0004בפיצוי עבור ה\u0003בושת.\u0004","ומפרטים, \u0003בנזק כיצד?\u0004 בכל מקרה של נזק גופני כגון: \u0003סימא\u0004 (עיוור) \u0003את עינו\u0004 של חבירו, או ש\u0003קטע את ידו,\u0004 או ש\u0003שיבר את רגלו, רואין אותו,\u0004 את הניזוק, \u0003כאילו הוא\u0004 הינו \u0003עבד\u0004 ה\u0003נמכר בשוק, ושמין\u0004 (מעריכים) \u0003כמה היה יפה\u0004 (שווה) לפני הנזק \u0003וכמה הוא יפה\u0004 לאחר הנזק, ואת ההפרש ישלם החובל בנזקו.","תשלומי \u0003צער\u0004 כיצד? \u0003כואו\u0004 (עשה בו כויה) \u0003בשפוד או במסמר\u0004 חם, \u0003ואפילו\u0004 עשה כויה \u0003על ציפורנו\u0004 ב\u0003מקום שאינו עושה חבורה\u0004 ולא גרם בכך להפחתת כושר עבודתו, \u0003אומדין\u0004 (מעריכים) \u0003כמה\u0004 כסף \u0003אדם כיוצא בזה\u0004 כמו זה הניזוק היה \u0003רוצה\u0004 (מוכן) \u0003ליטול\u0004 כדי \u0003להיות מצטער כך,\u0004 וסכום זה משלם המזיק.","תשלומי \u0003ריפוי\u0004 כיצד? שאם \u0003הכהו חייב\u0004 לדאוג \u0003לרפאותו\u0004 וישלם דמי רפואתו עד שיתרפא מהנזקים שגרם לו. ובאלו רפואות הוא חייב? \u0003עלה בו צמחים\u0004 (פריחה, מוגלה) בפצע, \u0003אם מחמת המכה\u0004 עלו — \u0003חייב,\u0004 אם \u0003שלא מחמת המכה\u0004 — \u0003פטור. חייתה\u0004 (הבריאה) המכה \u0003ונסתרה\u0004 (נפתחה), \u0003חייתה ונסתרה\u0004 שנית — \u0003חייב לרפאותו,\u0004 שכל זה הוא תוצאה של הנזק שגרם. \u0003חייתה\u0004 המכה \u0003כל צורכה\u0004 — שוב \u0003אינו חייב לרפאותו,\u0004 שכבר שילם דמי ריפוי על המכה שהיכהו.","תשלומי \u0003שבת\u0004 כיצד? — \u0003רואין אותו,\u0004 את הניזוק, \u0003כאילו הוא שומר קישואין\u0004 שמקבל שכר מועט עבור עבודתו, ומשלם לו שכר זה עבור אותם הימים שאינו יכול לעבוד אפילו עבודה זו מפני החבלה. ומפני מה אינו משלם לו את כל ההפסד שנגרם לו בפועל על ידי שבטל ממלאכתו שלו — \u0003שכבר נתן לו דמי ידו ודמי רגלו,\u0004 ובהערכה זו מעריכים גם את מקצועו ויכולתו להרוויח.","תשלומי \u0003בושת\u0004 כיצד? — מעריכים \u0003הכל לפי המבייש והמתבייש,\u0004 שיש הבדל מי גרם את הבושת ולמי נגרמה הבושת.","על עיקר ההלכה במשנה, שאדם משלם בכסף עבור נזק גופני שגרם לחבירו, שואלים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 הלא בתשלום נזקים שגרם אדם לחבירו \u0003\"עין תחת עין\"\u0004 (שמות כא, כד) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]?\u0006 ואם כן \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003עין ממש!\u0004","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך\u0006 לומר כן\u0005],\u0006 וטעמו של דבר כפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול סימא את עינו\u0004 של חבירו — \u0003מסמא\u0004 בית הדין \u0003את עינו\u0004 של המזיק, \u0003קטע את ידו\u0004 — \u0003מקטע את ידו, שיבר את רגלו\u0004 — \u0003משבר את רגלו\u0004 וכיוצא באלה? — \u0003תלמוד לומר: \"מכה אדם\" ו\"מכה בהמה\",\u0004 והשוואה זו מלמדת אותנו: \u0003מה מכה בהמה\u0004 הכוונה \u0003לתשלומין\u0004 של ממון, \u0003אף מכה אדם לתשלומין\u0004 ולא לעונש אחר.","\u0003ואם נפשך\u0004 (רצונך) \u0003לומר\u0004 שאפשר לדחות טעם זה, אביא טעם אחר — ש\u0003הרי הוא אומר\u0004 בכתוב אחר: \u0003\"\u0004ו\u0003לא תקחו כפר\u0004 (תשלומי ממון) \u0003לנפש רצח אשר הוא רשע למות\"\u0004 (במדבר לה, לא), ומכאן נלמד: \u0003לנפש רוצח אי\u0004 (אין) \u0003אתה לוקח כופר, אבל אתה לוקח כופר ל\u0004מי שקוטע \u0003ראשי אברים\u0004 של חבירו, אף על פי \u0003שאין חוזרין\u0004 (גדלים שוב), והרי זה כעין מיתה לאותו איבר.","ומבררים את דברי הברייתא, תחילה הובאה שם ראייה מהשוואת מכה אדם ומכה בהמה, ושואלים: \u0003הי\u0004 \u0005[איזה]\u0006 \u0003מכה,\u0004 לאיזה כתוב הכוונה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא לכתוב \u0003\"\u0004ו\u0003מכה בהמה ישלמנה ומכה אדם יומת\"\u0004 (ויקרא כד, כא), הלא הכתוב \u0003ההוא בקטלא כתיב\u0004 \u0005[במיתה\u0006 הוא ש\u0005נאמר],\u0006 בהכאה הגורמת למות, ולא בחבלה סתם, ובמקרה זה בוודאי אינו נפטר בתשלומים!","\u0003אלא\u0004 תאמר כי הדבר נלמד \u0003מהכא\u0004 \u0005[מכאן],\u0006 מכתוב זה: \u0003\"\u0004ו\u0003מכה נפש בהמה ישלמנה נפש תחת נפש\"\u0004 (ויקרא כד, יח), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 הפסוק: \u0003\"ואיש כי יתן מום\u0004 \u0003בעמיתו כאשר עשה כן יעשה לו\"\u0004 ((ויקרא כד, יט), והרי \u0003האי\u0004 \u0003לאו\u0004 \u0005[זה לא]\u0006 \u0003מכה הוא,\u0004 שהרי לא נאמרה בכתוב זה לשון \"מכה\" באדם! ומשיבים: בגזירה שווה של \u0003הכאה הכאה קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שלא היתה הכוונה ללמוד מן המלה כדיוקה אלא מתוכנה, וכך היא ההשוואה: \u0003מה הכאה האמורה בבהמה\u0004 הרי היא \u0003לתשלומין, אף הכאה האמורה באדם\u0004 הרי היא \u0003לתשלומין.\u0004","ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 בהכאה האמורה באדם: \u0003\"ואיש כי יכה כל נפש אדם מות יומת\"\u0004 (ויקרא כד, יז)! ומשיבים: הכוונה היא \u0003בממון\u0004 ולא במיתה ממש. ושואלים: \u0003ממאי\u0004 \u0005[ממה\u0006 מנין\u0005]\u0006 אתה לומר ש\u0003בממון? אימא\u0004 \u0005[אמור]\u0006 \u0003במיתה ממש!\u0004","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, משום שני טעמים: \u0003חדא\u0004 \u0005[האחד]\u0006 — \u0003דהא איתקש\u0004 \u0005[שהרי הוקש,\u0006 הושווה\u0005]\u0006 מכה אדם \u0003ל\"מכה\u0004 נפש \u0003בהמה ישלמנה\"\u0004 שנאמר אחריו ((ויקרא כד, יח). ושם מדובר בתשלומים, \u0003ועוד, כתיב בתריה\u0004 \u0005[נאמר אחריו]\u0006 \u0003\"\u0004שבר תחת שבר עין תחת עין שן תחת שן \u0003כאשר יתן מום באדם כן ינתן בו\"\u0004 ((ויקרא כד, כ), \u0003ושמע מינה\u0004 \u0005[ולמד כאן]\u0006 מלשון \"ינתן\" שמשלם \u0003ממון.\u0004 וממשיכים לדון בפירוש הברייתא. על הראיה שהובאה בתחילת הברייתא נאמר \"אם נפשך לומר\".","ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"אם נפשך לומר\"\u0004 זה? כלומר, כאן רומזת הברייתא שיש מקום לדחות ראיה זו, ולכן היא מציעה ראיה נוספת, אבל לא נאמר מה הקושי שיש בראיה הראשונה! ומסבירים: \u0003תו קא קשיא\u0004 \u0005[עוד\u0006 עדיין \u0005היה קשה]\u0006 \u0003לתנא:\u0004 \u0003מאי חזית דילפת\u0004 \u0005[מה ראית שלמדת]\u0006 דין זה \u0003ממכה בהמה\u0004 להענישו ממון, \u0003לילף\u0004 \u0005[שילמד]\u0006 \u0003ממכה אדם\u0004 ושמא הפירוש שעונשו עונש גוף, כמו מיתה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחייה להצעה זו: אין זה כלל קושי, שהרי \u0003דנין ניזקין מניזקין, ואין דנין ניזקין ממיתה.\u0004 ועל כך מקשים: \u0003אדרבה\u0004 \u0005[להיפך]\u0006 יש מקום להעדיף לימוד ממכה אדם שהרי \u0003דנין אדם מאדם, ואין דנין אדם מבהמה!\u0004","ואומרים: אכן, \u0003היינו דקתני\u0004 \u0005[זה הוא ששנה]\u0006 \u0003\"אם נפשך לומר\",\u0004 שאם יש מקום לדחות את הראיה הראשונה, ומטעם זה יש להביא ראיה אחרת: \u0003הרי הוא אומר, \"\u0004ו\u0003לא תקחו כפר לנפש רצח אשר הוא רשע למות כי מות יומת\"\u0004 (במדבר לה, לא), ומדייקים מכאן: \u0003לנפש רוצח אי\u0004 (אין) \u0003אתה לוקח כופר\u0004 (תשלומי ממון), \u0003אבל אתה לוקח כופר\u0004 אפילו \u0003לראשי אברים שאינן חוזרין.\u0004","ושואלים על ראיה זו: \u0003והאי\u0004 \u0005[ו\u0006פסוק \u0005זה]\u0006 \u0003\"לא תקחו כפר לנפש רצח\" למעוטי\u0004 \u0005[למעט]\u0006 \u0003ראשי אברים הוא דאתא\u0004 \u0005[שבא]?\u0006 הלא \u0003האי מבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו]\u0006 למיעוט אחר: \u0003דאמר רחמנא\u0004 \u0005[שאמרה תורה]\u0006 \u0003לא תעביד ביה תרתי\u0004 \u0005[אל תעשה בו\u0006 באדם הנידון בבית דין \u0005שתים,\u0006 שני עונשים\u0005],\u0006 \u0003לא תשקול מיניה\u0004 \u0005[תקח ממנו]\u0006 \u0003ממון ותקטליה\u0004 \u0005[ו\u0006גם \u0005תהרגנו]!\u0006 ומשיבים: אין צורך למיעוט זה שהרי \u0003האי\u0004 \u0005[\u0006דין \u0005זה]\u0006 \u0003מ\u0004מה שנאמר \"והכהו לפניו \u0003כדי רשעתו\"\u0004 (דברים כה, ב) \u0003נפקא\u0004 \u0005[יוצא\u0006 נלמד\u0005],\u0006 ללמדנו: משום \u0003רשעה אחת אתה מחייבו\u0004 (מענישו), \u0003ואי\u0004 (אין) \u0003אתה מחייבו\u0004 משום \u0003שתי רשעיות\u0004 אלא עונש אחד בלבד על עבירה אחת.","ושואלים: \u0003ואכתי מבעי ליה\u0004 \u0005[ועדיין נצרך לו]\u0006 המיעוט שבכתוב \"לא תקחו כופר לנפש רוצח\" לענין אחר, \u0003דקאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003לא תשקול\u0004 \u0005[תקח]\u0006 \u0003ממון\u0004 ככופר \u0003ותפטריה\u0004 \u0005[ותפטרנו]\u0006 מן העונש. ואם כן, אין לנו לימוד לענין תשלומי ממון על נזקי גוף באדם! ומשיבים: \u0003אם כן,\u0004 אם זה בלבד רצה הכתוב ללמדנו, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"לא תקחו כופר לאשר הוא רשע למות\", \"לנפש רצח\" למה לי?\u0004 הלא יש בכך ייתור! \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר להדגיש: \u0003לנפש רוצח\u0004 בלבד \u0003אי אתה לוקח כופר, אבל אתה לוקח כופר לראשי אברים שאינן חוזרין.\u0004","ושואלים: \u0003וכי מאחר דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לא תקחו כפר\"\u0004 שמכאן למדים היטב דין זה, הראיה הראשונה של \u0003\"מכה\" \"מכה\" למה לי\u0004 ולמה הובאה כלל ראיה זו שיש עליה פירכה? \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003אי מהאי\u0004 \u0005[אם מ\u0006פסוק \u0005זה]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שכך הוא הדין: \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 ליתן את \u0003עינו\u0004 — \u0003ניתיב\u0004 \u0005[שיתן],\u0006 \u0003ואי בעי\u0004 \u0005[ואם רוצה]\u0006 ליתן את \u0003דמי עינו\u0004 — \u0003ניתיב\u0004 \u0005[שיתן],\u0006 שהתורה נותנת אפשרות לשלם כופר עבור כל חבלה (שאינו מיתה) — על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 השוואה זו \u0003מבהמה, מה מכה בהמה לתשלומין\u0004 ולא עונש הגוף, \u0003אף מכה אדם לתשלומין\u0004 בלבד.","ובענין זה \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' דוסתאי בן יהודה אומר: \"עין תחת עין\"\u0004 (ויקרא כד, ב) כוונתו תשלומי \u0003ממון\u0004 ולא עין ממש. והוא דן בדבר: \u0003אתה אומר ממון, או אינו אלא עין ממש? אמרת\u0004 \u0005[אומר אתה]\u0006 כנגד הסבר זה \u0003הרי ש\u0004אכן \u0003היתה עינו של זה גדולה ועינו של זה קטנה, היאך אני קורא ביה\u0004 \u0005[בו]\u0006 \u0003\"עין תחת עין\"?\u0004","\u0003וכי תימא\u0004 \u0005[תאמר]:\u0006 ב\u0003כל\u0004 מקרה \u0003כי האי\u0004 \u0005[כזה]\u0006 \u0003שקיל מיניה ממונא\u0004 \u0005[יקח ממנו כסף]\u0006 אבל כאשר הם שווים יקח ממנו את עינו ממש, והרי \u0003התורה אמרה\u0004 שם בסמוך: \u0003\"משפט אחד יהיה לכם\"\u0004 (שם כב), ללמד: \u0003משפט השוה לכולכם.\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מאי קושיא\u0004 \u0005[מה קושיה]\u0006 היא זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 תאמר כך: \u0003נהורא שקיל מיניה, נהורא אמר רחמנא נישקול מיניה\u0004 \u0005[\u0006את \u0005אור\u0006 עיניו \u0005לקח ממנו,\u0006 את \u0005אור\u0006 עיניו \u0005אמרה התורה שיקח\u0006 בית הדין \u0005ממנו]\u0006 ואין מחלקים בין עין גדולה וקטנה. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006"],["\u0003קטן\u0004 (אדם קטן בקומתו) \u0003שהרג את הגדול ו\u0004כן \u0003גדול שהרג את הקטן, היכי קטלינן ליה\u0004 \u0005[איך הורגים אנו אותו]?\u0006 הלא \u0003התורה אמרה: \"משפט אחד יהיה לכם\"\u0004 (ויקרא כד, כב), \u0003משפט השוה לכולכם,\u0004 ובמשפט כזה אין שויון בעונשם של כל הרוצחים! \u0003אלא\u0004 אומרים שאף במקרים אלה נחשב הדבר למשפט שווה כי \u0003נשמה שקיל מיניה\u0004 \u0005[לקח ממנו]\u0006 הרוצח מהנרצח, \u0003נשמה אמר רחמנא נשקול מיניה\u0004 \u0005[אמרה התורה שיקחו ממנו],\u0006 \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 במקרה של עין \u0003נהורא שקיל מיניה, נהורא אמר רחמנא נשקול מיניה\u0004 \u0005[\u0006את \u0005אור\u0006 עיניו \u0005לקח ממנו,\u0006 לכן את \u0005אור\u0006 עיניו \u0005אמרה התורה שיקחו ממנו].\u0006","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו ענין, \u0003ר' שמעון בן יוחי אומר: \"עין תחת עין\"\u0004 (שמות כא, כד) כוונתו לתשלומי \u0003ממון,\u0004 והוא נושא ונותן בדבר. \u0003אתה אומר\u0004 שכוונתו לתשלומי \u0003ממון, או אינו אלא\u0004 הכוונה לתשלום \u0003עין ממש?\u0004 לכן יש להשיב: \u0003הרי שהיה סומא וסימא\u0004 אדם אחר, או שהיה \u0003קיטע\u0004 יד — \u0003וקיטע\u0004 ידו של אחר, או שהיה \u0003חיגר — וחיגר\u0004 את רגלו של אחר, \u0003היאך אני מקיים בזה עין תחת עין?\u0004 והרי אי אפשר לעשות לו כן, \u0003והתורה אמרה: \"משפט אחד יהיה לכם\", משפט השוה לכולכם!\u0004","על דרך זו של הוכחה \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחייה: \u0003ומאי קושיא\u0004 \u0005[ומה הקושי\u0006 שבדבר]? \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אפשר\u0004 להעניש באברי גופו — \u0003אפשר\u0004 ומענישים אותו בכך, \u0003היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא אפשר —\u0004 \u0003לא אפשר, ופטרינן ליה\u0004 \u0005[ופוטרים אנו אותו]\u0006 לגמרי. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך], איש\u0006 \u0003טרפה\u0004 (מי שעומד למות בשל מחלה או פגיעה קשה) \u0003שהרג את השלם, מאי עבדינן ליה\u0004 \u0005[מה אנו עושים לו]?\u0006 הרי רוצח זה נחשב כבר כאדם הרוג, שאי אפשר להרוג אותו!","\u0003אלא\u0004 מוכרחים לומר \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003אפשר — אפשר, היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא אפשר — לא אפשר ופטרינן ליה\u0004 \u0005[ופוטרים אנו אותו].\u0006 ועוד בהוכחה שחובל בחבירו משלם ממון ולא באיברי גופו.","\u0003דבי ר' ישמעאל תנא\u0004 \u0005[\u0006התנא \u0005של בית מדרשו של ר' ישמעאל שנה],\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כאשר יתן מום באדם \u0003כן ינתן בו\"\u0004 (ויקרא כד, כ), \u0003ואין\u0004 מובנה של \u0003נתינה\u0004 זו \u0003אלא ממון.\u0004 ומקשים: \u0003אלא מעתה\u0004 (לפי זה), שאתה מפרש את הפועל נתן האמור כאן כמתייחס לממון בלבד, הרי נאמר באותו הכתוב \u0003\"כאשר יתן מום באדם\"\u0004 (שם), \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003ממון הוא?\u0004 והרי בוודאי אינך יכול לפרש כך!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003דבי ר' ישמעאל קרא יתירא דרשי\u0004 \u0005[של בית מדרשו של ר' ישמעאל מקרא יתר\u0006 באותה פרשיה \u0005דרשו],\u0006 \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]\u0006 בפסוק הקודם: \u0003\"ואיש כי יתן מום בעמיתו כאשר עשה כן יעשה לו\"\u0004 (שם יט), \u0003\"כן ינתן בו\"\u0004 האמור בפסוק הבא אחריו \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]:\u0006 שעונש זה הוא בנתינת \u0003ממון.\u0004 ושואלים: אם כן שאתה דורש ייתור לשון נתינה שבמקרא זה מה שנאמר \u0003\"כאשר יתן מום באדם\" למה לי\u0004 לכתוב בלשון \"יתן\" ומה בא זה ללמדנו? ומשיבים: אין אנו למדים דבר, שכן \u0003איידי דבעי מיכתב\u0004 \u0005[משום שרצה לכתוב]\u0006 \u0003\"כן ינתן בו\",\u0004 שלשון נתינה בענין זה היא מדוייקת והכרחית, \u0003כתב נמי\u0004 \u0005[גם כן] \"\u0006\u0003כאשר יתן מום באדם\".\u0004","\u0003דבי ר' חייא תנא\u0004 \u0005[\u0006התנא \u0005של בית מדרשו של ר' חייא שנה]\u0006 באותו ענין, \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לענין עונש עדים זוממים: \"לא תחוס עינך נפש בנפש... \u0003יד ביד\u0004 רגל ברגל\" (דברים יט, כא), לומר: \u0003דבר הניתן מיד ליד, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 \u0003ממון.\u0004 ומקשים: \u0003אלא מעתה,\u0004 לפי זה, מה שנאמר באותו פסוק \u0003\"רגל ברגל\" נמי הכי הוא\u0004 \u0005[גם כן כך הוא]\u0006 לשון מדוייקת וכוונתה: דבר הנעשה ברגל?!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003דבי\u0004 \u0005[\u0006החכמים של בית מדרשו של] \u0003ר' חייא קרא יתירא קא דרשי\u0004 \u0005[מקרא יתר הם דורשים],\u0006 וכך הם דורשים: \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]\u0006 בפסוק הקודם: \u0003\"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (שם יט), \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר] שהכוונה שמענישים אותו באותו דבר \u0003ממש,\u0004 אם כן הפירוט \u0003\"יד ביד\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]:\u0006 שהכוונה היא \u0003ממון.\u0004 שואלים אם כן, \u0003\"רגל ברגל\" למה לי?\u0004 ומשיבים: \u0003איידי דכתיב\u0004 \u0005[מתוך שכתוב]\u0006 \u0003\"יד ביד\", כתב נמי\u0004 \u0005[גם כן]\u0006 \u0003\"רגל ברגל\".\u0004","\u0003אביי אומר: אתיא\u0004 \u0005[באה\u0006 הלכה זו] ש\"עין תחת עין\" — ממון, \u0003מדתני דבי חזקיה\u0004 \u0005[ממה ששנה\u0006 החכם \u0005בבית\u0006 מדרשו \u0005של חזקיה],\u0006 \u0003דתנא\u0004 \u0005[ששנה]\u0006 החכם \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו של] \u0003חזקיה:\u0004 כתוב \u0003\"עין תחת עין\"\u0004 (שמות כא, כד) ובפסוק קודם כתוב \u0003\"נפש תחת נפש\"\u0004 (שם, כג), להדגיש: \u0003ולא נפש ועין תחת עין; ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר] שנוטלים ממנו עין \u0003ממש, זימנין דמשכחת לה\u0004 \u0005[פעמים שאתה מוצא אותה\u0006 אפשרות מתקיימת] שיהיה עונש \u0003עין ונפש תחת עין, דבהדי דעויר ליה נפקא ליה נשמתיה\u0004 \u0005[שבתוך שמעוור אותו\u0006 גם \u0005יוצאת נשמתו]\u0006 שמפני חולשתו של הנאשם גורמת הוצאת העין למותו.","ושואלים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה\u0006 שבדבר\u0005]?\u0006 \u0003דלמא מימד אמדינן ליה\u0004 \u0005[שמא אומדים אנו אותו],\u0006 \u0003אי מצי מקבל\u0004 — \u0003עבדינן\u0004 \u0005[אם\u0006 הוא \u0005יכול לקבל\u0006 עונש \u0005זה\u0006 — \u0005עושים אנו\u0006 לו], \u0003ואי לא מצי מקבל\u0004 — \u0003לא עבדינן\u0004 \u0005[ואם אינו יכול לקבל\u0006 עונש זה — \u0005אין אנו עושים].\u0006 \u0003ואי אמדינן דמצי מקבל ועבדינן ביה ונפק רוחיה\u0004 \u0005[ו\u0006גם \u0005אם אמדנו\u0006 אותו \u0005שיכול לקבל ועשינו בו\u0006 את העונש \u0005ויצאה נשמתו\u0006 בתוך כך\u0005]\u0006 בכל זאת על ידי מעשה זה, \u0003אי מיית\u0004 — \u0003לימות\u0004 \u0005[אם מת — שימות],\u0006 \u0003מי לא תנן\u0004 \u0005[האם לא שנינו]\u0006 כיוצא בזה \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מלקות:\u0004 מי ש\u0003אמדוהו\u0004 למספר מסויים של מלקות \u0003ומת תחת ידו\u0004 של המלקה בתוך המספר הזה — \u0003פטור,\u0004 שאף על פי שעונשו הוא למלקות בלבד כיון שעשה המלקה כדין — אינו חייב עליו.","\u0003רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבה אמר\u0004 הסבר נוסף: \u0003אמר קרא\u0004 \u0005[הכתוב\u0006 באותה פרשיה]: \u0003\"פצע תחת פצע\"\u0004 (שם כד), וכתוב זה שהוא מיותר בא ללמדנו: \u0003ליתן\u0004 לחייב תשלומי \u0003צער\u0004 גם \u0003במקום\u0004 שמשלם \u0003נזק.\u0004 ומעתה נברר: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\"עין תחת עין\" \u0003ממש,\u0004 ועושים לחובל מה שעשה לחבירו, הרי \u0003כי היכי דלהאי הוי ליה צערא, להאי נמי אית ליה צערא\u0004 \u0005[כמו שלזה\u0006 לנחבל \u0005יש לו צער, לזה\u0006 לחובל \u0005גם כן יש לו צער]\u0006 בהוצאת עינו, ואם כן מפני מה צריך הוא גם לשלם דמי צער בנוסף לכך?","ודוחים: \u0003ומאי קושיא\u0004 \u0005[ומה הקושיה]\u0006 שבכך? \u0003דלמא איכא איניש דמפנק אית ליה צערא טפי\u0004 \u0005[שמא יש אדם ש\u0006הוא מפונק יש לו צער יותר], \u0003ואיכא איניש דלא מפנק לית ליה צערא\u0004 \u0005[ויש אדם שאינו מפונק\u0006 שאין לו צער], ואם כן, אף אם נקיים \"עין תחת עין\" כפשוטו עדיין יש צורך לחייב צער במקום נזק, ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 שכתבה התורה \"פצע תחת פצע\" ללמדנו שמשלם דמי צער? הרי זה כדי \u0003למתבי ליה היאך דביני ביני\u0004 \u0005[לתת לו את\u0006 ההבדל \u0005שבין זה לזה],\u0006 שאם הנחבל הוא אדם מפונק והחובל אינו מפונק צריך להוסיף לו דמי צערו היתר.","\u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר\u0004 ראייה נוספת, \u0003אמר קרא\u0004 \u0005[הכתוב\u0006 עוד באותה פרשיה\u0005]:\u0006 \u0003\"ורפא ירפא\"\u0004 (שמות כא, יט) ובא זה ללמדנו, \u0003ליתן,\u0004 כלומר, לחייב תשלום \u0003רפואה\u0004 גם \u0003במקום\u0004 שמשלם \u0003נזק; ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\"עין תחת עין\" \u0003ממש,\u0004 אם כן, מדוע ישלם החובל דמי רפואה והרי \u0003כי היכי דהאי בעי אסייא, האי נמי בעי אסייא\u0004 \u0005[כמו שזה,\u0006 הנחבל, \u0005צריך רופא, זה,\u0006 החובל, \u0005גם כן צריך רופא]\u0006 לרפואת עינו שנעקרה ממנו כעונש.","ודוחים: \u0003מאי קושיא\u0004 \u0005[מה הקושיה\u0006 בדבר\u0005]?\u0006 \u0003דלמא איכא דסליק בשריה הייא\u0004 \u0005[שמא יש\u0006 מי \u0005שמתרפא בשרו במהרה],\u0006 \u0003ואיכא\u0004 \u0005[ויש]\u0006 מי ש\u0003לא סליק בשריה הייא\u0004 \u0005[מתרפא בשרו במהרה],\u0006 ונמצא שגם אם נפרש \"עין תחת עין\" ממש, יש צורך לחייב גם על ריפוי. \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 שכתבה התורה \"ורפא ירפא\" לתשלום דמי רפואה? — הרי זה כדי \u0003למיתב ליה היאך דביני ביני\u0004 \u0005[לתת לו מה שיש בין זה לזה]\u0006 בהבדל בזמן הריפוי.","\u0003רב אשי אמר\u0004 ראיה נוספת שתשלום על חבלת גוף הוא ממון ולא ממש: \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שווה \u0003\"תחת\" \"תחת\" משור. כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"עין תחת עין\"\u0004 (שמות כא, כד), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בשור מועד שנגח שור חבירו: \u0003\"שלם ישלם שור תחת השור\"\u0004 (שמות כא, לו), \u0003מה להלן\u0004 בשור הכוונה שמשלם \u0003ממון,\u0004 ולאו דווקא שנותן תחתיו שור ממש, \u0003אף כאן\u0004 בחבלות הגוף \u0003ממון.\u0004","ושואלים: \u0003מאי חזית\u0004 \u0005[מה ראית]\u0006 \u0003דילפת\u0004 \u0005[שאתה לומד]\u0006 \u0003\"תחת\" \"תחת\" משור? נילף\u0004 \u0005[נלמד]\u0006 \u0003\"תחת\" \"תחת\" מאדם, דכתיב\u0004 \u0005[שנאמר]\u0006 באדם ההורג אדם אחר: \u0003\"ונתת נפש תחת נפש\"\u0004 (שמות כא, כג), \u0003מה להלן\u0004 עונשו הוא נפש \u0003ממש, אף כאן\u0004 בענין חבלת הגוף הכוונה לעונש אבר \u0003ממש!\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 עדיף הלימוד משור משום ש\u0003דנין\u0004 (לומדים) \u0003נזקין מנזקין, ואין דנין נזקין ממיתה.\u0004 ודוחים: \u0003אדרבה,\u0004 להיפך: עדיף הלימוד מאדם ההורג משום ש\u0003דנין אדם מאדם, ואין דנין אדם מבהמה!\u0004","\u0003אלא\u0004 חזר בו רב אשי מראיה זו ו\u0003אמר רב אשי\u0004 ראיה אחרת: \u0003מ\"תחת אשר ענה\"\u0004 (דברים כב, כט) \u0003יליף ליה\u0004 \u0005[לומד\u0006 את \u0005זאת],\u0006 שהמפתה נערה נותן כסף במקום העינוי, ונמצא שיש פה לימוד של \"תחת\" \"תחת\" שהוא של \u0003אדם מאדם ונזיקין מנזיקין.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 באותו ענין, \u0003ר' אליעזר אומר:\u0004 מה שנאמר \u0003\"עין תחת עין\",\u0004 הכוונה היא — \u0003ממש.\u0004 ותוהים: \u0003ממש סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? וכי \u0003ר' אליעזר לית ליה ככל הני תנאי\u0004 \u0005[אין לו,\u0006 אינו מקבל את שיטתם של \u0005כל התנאים הללו]\u0006 הסוברים כולם שהכוונה לממון?","\u0003אמר רבה:\u0004 הכוונה היא \u0003לומר, שאין שמין אותו\u0004 את הניזק לצורך תשלום הנזק \u0003כעבד\u0004 לצורך חישוב תשלום הנזק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא כמאן\u0004 \u0005[כמי\u0006 יעשו\u0005],\u0006 כיצד יאמדו אותו? אם תאמר \u0003כבן חורין, בן חורין מי אית ליה דמי\u0004 \u0005[האם יש לו מחיר]?\u0006 ואם כן באיזו דרך נקצוב את המחיר של הנזק שלו? \u0003אלא אמר רב אשי:\u0004 כוונת ר' אליעזר \u0003לומר, שאין שמין אותו\u0004 כעבד — \u0003בניזק\u0004 לאמוד כמה הוזק הנחבל, \u0003אלא במזיק,\u0004 כמה שוויו עכשיו כעבד, ויפחת מחירו אם באמת היו עושים בו את העונש ממש, והיו מוציאים ממנו עין. ואת הסכום הזה משלם.","מסופר: \u0003ההוא חמרא דקטע ידא דינוקא\u0004 \u0005[\u0006מעשה ב\u0005חמור אחד שקטע\u0006 את \u0005ידו של ילד],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רב פפא בר שמואל, אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו שומו ליה\u0004 \u0005[לכו\u0006 ו\u0005העריכו לו]\u0006 \u0003ארבעה דברים\u0004 שצריך לשלם בעליו של החמור. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 בשאלה: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003חמשה תנן\u0004 \u0005[שנינו]\u0006 במשנתנו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 ארבעה דברים \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מנזק קאמינא\u0004 \u0005[אמרתי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 בשאלה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חמור הוא\u0004 שהזיק, \u0003וחמור אינו משלם אלא נזק! אמר להו\u0004 \u0005[להם]\u0006 רב פפא בר שמואל: \u0003זילו שומו ליה נזקיה\u0004 \u0005[לכו העריכו לו\u0006 את \u0005נזקו\u0006 בלבד\u0005].\u0006 אמרו לו: \u0003והא כעבדא בעי למשיימיה\u0004 \u0005[והרי\u0006 צריך \u0005להעריך אותו כ\u0006אילו היה \u0005עבד\u0006 נמכר בשוק\u0005]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו שיימוהו כעבדא\u0004 \u0005[לכו העריכו אותו כעבד].\u0006","\u0003אמר להו אבוה דינוקא\u0004 \u0005[אמר להם אביו של התינוק]:\u0006 \u0003לא בעינא, דזילא ביה מילתא\u0004 \u0005[אינני רוצה, שמזולזל בו הדבר]\u0006 שיעריכו אותו כאילו היה עבד. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 לאב: \u0003והא קא מחייבת ליה לינוקא\u0004 \u0005[והרי\u0006 בכך \u0005אתה מחייב אותו, את הילד],\u0006 שהרי כסף זה שייך לילד, ומגיע לו סכום זה ואין אתה יכול לוותר על המגיע לו! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003לכי גדיל מפייסנא ליה מדידי\u0004 \u0005[כאשר יגדל, אפייס,\u0006 אפצה, \u0005אותו מ\u0006כספי \u0005שלי]\u0006 ואינני רוצה שיתבזה עכשיו.","עוד מסופר: \u0003ההוא תורא דאלס ידיה דינוקא\u0004 \u0005[\u0006מעשה ב\u0005שור אחד שלעס\u0006 וחיבל \u0005ידו של ילד],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003רבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו שיימוהו כעבדא\u0004 \u0005[לכו\u0006 ו\u0005העריכו אותו כעבד].\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא מר\u0004 \u0005[אדוני]\u0006 עצמו \u0003הוא דאמר\u0004 \u0005[שאומר]:\u0006 \u0003כל\u0004 תשלום שאומדנו הוא \u0003הנישום כעבד\u0004 — \u0003אין גובין אותו\u0004 בית דין \u0003בבבל! אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הערכה זו שיעריכוהו אלא \u0003דאי תפס\u0004 \u0005[שאם יתפוס]\u0006 הניזק סכום זה מן המזיק לא יוציאו מידו.","ומעירים: \u0003רבא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רבא: נזקי שור בשור,\u0004 כלומר, שור שניזוק על ידי שור, \u0003ו\u0004כן \u0003נזקי שור באדם,\u0004 כלומר, שור שניזוק על ידי אדם — \u0003גובין אותו בבבל,\u0004 אבל \u0003נזקי אדם באדם ונזקי אדם בשור\u0004 שור שהזיק אדם — \u0003אין גובין אותו בבבל.\u0004","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003נזקי אדם באדם ונזקי אדם בשור\u0004 ש\u0003לא?\u0004 — שאתה אומר ש\u0003\"אלהים\",\u0004 כלומר, דיינים סמוכים, \u0003בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003וליכא\u0004 \u0005[ואין]\u0006 בבבל, ואולם \u0003נזקי שור בשור ושור באדם נמי\u0004 \u0005[גם כן]\u0006"],["\u0003\"אלהים\" בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין\u0006 בבבל\u0005]!\u0006","\u0003אלא\u0004 תאמר: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003שור\u0004 שהוזק \u0003ב\u0004ידי \u0003שור ושור\u0004 שהוזק \u0003ב\u0004ידי \u0003אדם?\u0004 — \u0003דשליחותייהו קא עבדינן\u0004 \u0005[ש\u0006את \u0005שליחותם\u0006 של דייני ארץ ישראל הסמוכים \u0005אנו\u0006 דייני בבל \u0005עושים],\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לגבי דיני \u0003הודאות והלואות\u0004 שאנו דנים בהן בבבל מכוח שליחות זו אף שאיננו דיינים סמוכים, אם כן \u0003אדם באדם ואדם בשור נמי\u0004 \u0005[\u0006נאמר \u0005גם כן]\u0006 שאת \u0003שליחותייהו קא עבדינן\u0004 \u0005[שליחותם אנו עושים],\u0006 \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 לגבי \u0003הודאות והלואות!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך כי יש לחלק: \u0003כי קא עבדינן שליחותייהו\u0004 \u0005[כאשר אנו עושים\u0006 את \u0005שליחותם]\u0006 הרי זה — \u0003במידי דקים לן בגויה\u0004 \u0005[בדבר שברור לנו\u0006 הדין ש\u0005בו],\u0006 \u0003במידי\u0004 \u0005[בדבר]\u0006 ש\u0003לא קים לן בגויה\u0004 \u0005[ברור לנו\u0006 דין ש\u0005בו]\u0006 כגון זה שצריך הערכה ואומדן שלנו — \u0003לא עבדינן שליחותייהו\u0004 \u0005[עושים אנו\u0006 את \u0005שליחותם].\u0006","על כך \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה: \u0003שור בשור ושור באדם\u0004 שאנו דנים בהם בבבל \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא קים לן בגויה\u0004 \u0005[ברור לנו\u0006 הדין ש\u0005בו]\u0006 מעצמו, וחייבים להעריך ולאמוד את הנזק, \u0003אלא\u0004 איך עושים — \u0003פוק חזי היכא מזדבני תורא בשוקא\u0004 \u0005[צא\u0006 ו\u0005ראה איך נמכר שור בשוק],\u0006 ולפי זה קובעים את שיעור הנזק, ואם כן \u0003אדם באדם ואדם בשור נמי\u0004 \u0005[גם כן]\u0006 \u0003פוק חזי היכא מזדבני עבדי בשוקא\u0004 \u0005[צא\u0006 ו\u0005ראה איך נמכרים עבדים בשוק]\u0006 ומדוע אין דנים בהם בבבל?","\u0003ועוד, תשלום כפל\u0004 בגנב \u0003ותשלום ארבעה וחמשה\u0004 בגונב שה או שור וטובחו או מוכרו, \u0003דקיצי\u0004 \u0005[ש\u0006הם \u0005קצובים]\u0006 ואין כאן מקום לאומדן, \u0003נעבד שליחותייהו\u0004 \u0005[נעשה\u0006 את \u0005שליחותם]\u0006 ונדונם בבבל!","על הקושיה האחרונה \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003כי קא עבדינן שליחותייהו\u0004 \u0005[כאשר אנו עושים\u0006 את \u0005שליחותם]\u0006 הרי זה רק \u0003בממונא\u0004 \u0005[ב\u0006דבר שהוא חיוב \u0005ממון],\u0006 שאדם משלם לחבירו ממון שהפסידו, \u0003בקנסא לא עבדינן שליחותייהו\u0004 \u0005[בקנס,\u0006 שהוא עונש, \u0005אין אנו עושים את שליחותם]\u0006 ואין דנים בבבל.","ושוב מקשים: \u0003אדם באדם דממונא\u0004 \u0005[ש\u0006חיוב \u0005ממון]\u0006 \u0003הוא, נעבד שליחותייהו\u0004 \u0005[נעשה\u0006 את \u0005שליחותם]!\u0006 ומשיבים: \u0003כי קא עבדינן שליחותייהו\u0004 \u0005[כאשר אנו עושים\u0006 את \u0005שליחותם]\u0006 הרי זה רק \u0003במילתא דשכיחא\u0004 \u0005[בדבר המצוי],\u0006 ולכן נזקי \u0003אדם באדם דלא שכיחא\u0004 \u0005[שאין\u0006 זה דבר \u0005מצוי]\u0006 — \u0003לא עבדינן שליחותייהו\u0004 \u0005[אין אנו עושים\u0006 את \u0005שליחותם].\u0006","ומקשים: \u0003הרי בושת ופגם\u0004 שמשלמים אונס ומפתה \u0003דשכיח\u0004 \u0005[שמצוי\u0006 הדבר\u0005],\u0006 \u0003נעביד שליחותייהו\u0004 \u0005[נעשה\u0006 את \u0005שליחותם]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 באמת, שבאמת אנו דנים דיני בושת ופגם גם בבבל, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003רב פפא אגבי\u0004 \u0005[היגבה]\u0006 \u0003ארבע מאה זוזי\u0004 \u0005[ארבע מאות זוז]\u0006 בעבור \u0003בושת.\u0004 ומקשים: \u0003והא ליתיה\u0004 \u0005[והרי אין]\u0006 הלכה כמעשה זה של \u0003רב פפא\u0004 ואין נוהגים כן! שכן \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרב נחמן\u0004 שאלה בענין זה של בושת ופגם, \u0003ושלח ליה\u0004 \u0005[לו]\u0006 רב נחמן בתשובה: \u0003חסדא, חסדא, קנסא קא מגבית\u0004 \u0005[קנס אתה מגבה]\u0006 \u0003בבבל?\u0004","\u0003אלא\u0004 כך צריכים לומר: \u0003כי עבדינן שליחותייהו\u0004 \u0005[כאשר אנו עושים\u0006 את \u0005שליחותם]\u0006 הרי זה דווקא \u0003במילתא דשכיחא ואית ביה\u0004 \u0005[בדבר המצוי ויש בו]\u0006 גם \u0003חסרון כיס\u0004 שהניזק הפסיד כסף מכיסו, \u0003אבל מילתא דשכיחא ולית ביה\u0004 \u0005[דבר ש\u0006הוא \u0005מצוי ואין בו]\u0006 \u0003חסרון כיס, אי נמי מילתא דלא שכיחא ואית ביה\u0004 \u0005[או גם כן דבר שאינו מצוי ויש בו]\u0006 \u0003חסרון כיס, לא עבדינן שליחותייהו\u0004 \u0005[אין אנו עושים\u0006 את \u0005שליחותם].\u0006 \u0003הלכך\u0004 \u0005[על כן]\u0006 נזקי \u0003אדם באדם, אף על גב דאית ביה\u0004 \u0005[אף על פי שיש בו]\u0006 \u0003חסרון כיס, כיון\u0004 ש\u0003לא שכיחא\u0004 \u0005[מצוי\u0006 הדבר\u0005]\u0006 — \u0003לא עבדינן שליחותייהו\u0004 \u0005[אין אנו עושים\u0006 את \u0005שליחותם],\u0006 \u0003בושת אף על גב דשכיחא\u0004 \u0005[אף על פי ש\u0006היא \u0005מצויה],\u0006 \u0003כיון דלית ביה\u0004 \u0005[שאין בה]\u0006 \u0003חסרון כיס,\u0004 שהרי לא הפסידה כסף בכך — \u0003לא עבדינן שליחותייהו\u0004 \u0005[אין אנו עושים\u0006 את \u0005שליחותם].\u0006","ולעצם מה שנאמר בשם רב שואלים: \u0003ו\u0004דין \u0003שור\u0004 שניזוק \u0003ב\u0004ידי \u0003שור גובין בבבל? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: שור שהזיק\u0004 — \u0003אין גובין אותו בבבל.\u0004 ומעתה נברר: \u0003דאזיק מאן\u0004 \u0005[שהזיק\u0006 את \u0005מי]?\u0006 \u0003אילימא דאזיק\u0004 \u0005[אם תאמר שהזיק]\u0006 \u0003אדם, מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003שור דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם? אפילו אדם דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003אדם\u0004 שהוא מקרה מצוי יותר \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003אין גובין אותו בבבל,\u0004 שאין דנים דיני חבלות בבבל! \u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמדובר בשור \u0003דאזיק\u0004 \u0005[שהזיק]\u0006 \u0003שור\u0004 אחר, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003אין גובין אותו בבבל!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003ב\u0004שור \u0003תם\u0004 שנוגח, שמה שמשלם קנס הוא, ואין דנים דיני קנסות בבבל, \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר \u0003ב\u0004שור \u0003מועד\u0004 שנוגח שאין התשלום שבו קנס. ומקשים על כך: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: אין\u0004 שור תם נעשה \u0003מועד בבבל,\u0004 שאין בית דין סמוך בבבל הראוי לקבל עדות זו! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה \u0005:\u0006 מדובר כאן \u0003דאייעד התם ואייתוה להכא\u0004 \u0005[שהועד שם\u0006 בארץ ישראל \u0005והביאו אותו לכאן,\u0006 לבבל\u0005].\u0006","ומקשים: \u0003והא מילתא דלא שכיחא היא\u0004 \u0005[והרי דבר שאינו מצוי הוא]\u0006 שיביאו שור מועד מארץ ישראל לבבל, \u0003ומילתא דלא שכיחא הא אמרת דלא עבדינן שליחותייהו\u0004 \u0005[ודבר שאינו מצוי הרי אמרת שאין אנו עושים\u0006 את \u0005שליחותם]!\u0006 ומשיבים, מדובר במקרה אחר: \u0003דאתו רבנן דהתם וייעדוה הכא\u0004 \u0005[שבאו חכמים משם,\u0006 שהם חכמים סמוכים, \u0005ו\u0006הם \u0005עשו אותו מועד כאן].\u0006 ומקשים: \u0003סוף סוף מילתא דלא שכיחא היא\u0004 \u0005[דבר שאינו מצוי הוא],\u0006 \u0003ואת\u0004 \u0005[ואתה]\u0006 \u0003אמרת\u0004 כי \u0003מילתא דלא שכיחא לא קא עבדינן שליחותייהו\u0004 \u0005[דבר שאינו מצוי אין אנו עושים\u0006 את \u0005שליחותם]!\u0006","\u0003אלא\u0004 צריך לומר, \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רבא\u0004 שגובים נזקי שור בבבל הרי זה \u0003בשן ורגל,\u0004 ש\u0003מועדין מתחילתן נינהו\u0004 \u0005[הם],\u0006 ובמקרה כזה הכל מודים שמכיון שהוא נזק מצוי (ויש בו חסרון כיס) עושים בבבל את שליחותם של חכמי ארץ ישראל.","ומכאן שבים לביאור המשנה, שנינו בה: מהו תשלום על \u0003צער\u0004 — כגון ש\u0003כוואו בשפוד או במסמר\u0004 ואפילו על ציפורנו מקום שאינו עושה חבורה — אומדין כמה אדם כיוצא בזה רוצה ליטול להיות מצטער כך. ומעירים: מדוגמאות אלה שהביא התנא למדים ש\u0003צער\u0004 אפילו \u0003שלא במקום נזק,\u0004 כלומר, גם במקום שלא נגרם כל נזק אלא רק צער — גם כן \u0003משתלם\u0004 (משלמים עבורו). ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רבא:\u0004 שיטת \u0003בן עזאי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 על הכתוב \"כויה תחת כויה פצע תחת פצע חבורה תחת חבורה\" (שמות כא, כה), \u0003רבי אומר: כויה נאמרה תחילה, בן עזאי אומר: חבורה נאמרה תחילה.\u0004","נחלקו חכמים בדבר: ומסבירים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה ענין \u0005הם\u0006 \u0005חולקים]?\u0006 והרי בוודאי אין בן עזאי הופך את הפסוק! \u0003רבי סבר\u0004 \u0005[סבור]:\u0006 \u0003\"כויה\"\u0004 שנאמרה תחילה (בפסוק כד) — אף כזו \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה חבורה משמע,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה]\u0006 אחרי כן \u0003\"חבורה\", לגלויי עלה\u0004 \u0005[לגלות עליה]\u0006 ש\u0003כויה דאית\u0004 \u0005[שיש]\u0006 \u0003בה חבורה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלמים עליה גם דמי צער, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא,\u0004 שאין בה חבורה — \u0003לא\u0004 משלמים דמי צער.","\u0003ובן עזאי סבר\u0004 \u0005[סבור]:\u0006 \u0003\"כויה\"\u0004 שנאמרה תחילה בפסוק — \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה חבורה משמע,\u0004 ומשום כך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"חבורה\", לגלויי עלה\u0004 \u0005[לגלות עליה]\u0006 ש\u0003\"כויה\"\u0004 שנאמר בתורה שמשלם עליה היא אף זו \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה חבורה,\u0004 וכשיטת משנתנו, שאף שלא במקום נזק משלם צער.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא:\u0004 מנין שמשנתנו כבן עזאי ולא כרבי, \u0003אדרבה, איפכא מסתברא\u0004 \u0005[ההיפך מסתבר\u0006 לומר\u0005],\u0006 ש\u0003רבי\u0004 ש\u0003אומר\u0004 ש\u0003כויה נאמרה תחילה,\u0004 הוא \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003\"כויה\"\u0004 — \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 \u0003חבורה משמע,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"חבורה\", לגלויי עלה\u0004 \u0005[לגלות עליה]\u0006 ש\u0003כויה\u0004 היא זו \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה חבורה,\u0004 וכשיטת משנתנו.","\u0003בן עזאי\u0004 ש\u0003אומר\u0004 ש\u0003חבורה נאמרה תחילה,\u0004 הוא ש\u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003\"כויה\"\u0004 — \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה חבורה משמע,\u0004 ועל כן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה]\u0006 \u0003\"חבורה\", לגלויי עלה\u0004 \u0005[לגלות עליה]\u0006 ש\u0003כויה דאית\u0004 \u0005[שיש]\u0006 \u0003בה חבורה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא, ואמסקנא קיימי\u0004 \u0005[ולפי המסקנה\u0006 של הפסוק הם \u0005עומדים],\u0006 כלומר, נאמרו דעותיהם בברייתא כפי שמשמע מסוף הפסוק, שמסוף הפסוק יש להבין אחרת את תחילתו,","\u0003אי נמי\u0004 \u0005[או גם כן],\u0006 ניתן לפרש באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 \u0003\"כויה\"\u0004 — \u0003בין דאית\u0004 \u0005[שיש]\u0006 \u0003בה חבורה בין דלית\u0004 \u0005[שאין]\u0006 \u0003בה חבורה משמע, והכא\u0004 \u0005[וכאן] ג\u0006"],["אם למדים \u0003ב\u0004מקום ש\u0003כלל ופרט המרוחקים זה מזה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 לפי שהכתוב אומר \"כויה תחת כויה פצע תחת פצע חבורה תחת חבורה\" (שמות כא, כד) ש\"כויה\" היא כלל, שיש בו גם כויה שיש בה חבורה וגם כויה שאין בה חבורה, ולאחריה בא פרט בענין חבורה.","\u0003רבי סבר\u0004 \u0005[סבור]:\u0006 כיון שאין הכלל והפרט סמוכים זה לזה (שהרי \"פצע תחת פצע\" מפסיק ביניהם), \u0003אין דנין אותו בכלל ופרט,\u0004 לומר לפי כללי ההלכה שאין בכלל אלא מה שבפרט ויהיה חייב רק על כויה שיש בה חבורה, ולכן לשיטתו על כל כויה משלם, ואף על זו שאין בה חבורה. \u0003ובן עזאי סבר\u0004 \u0005[סבור]:\u0006 \u0003דנין אותו בכלל ופרט.\u0004 ואין בכלל אלא מה שבפרט, ואין משלמים עבור כויה אלא אם כן יש בה חבורה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 אם כן \u0003\"חבורה\" לרבי למה לי?\u0004 שהרי בכלל \"כויה\" נאמר הכל! דבר זה בא ללמד \u0003לדמים יתרים,\u0004 שאם גרם נוסף לכוויה גם חבורה — עליו להוסיף תשלום כסף על מה שהזיק לו.","שנינו במשנה כיצד משלם צער — \u0003אומדין כמה אדם כיוצא בזה\u0004 (כמוהו) \u0003רוצה ליטול\u0004 להיות מצטער כך. ושואלים: \u0003צער במקום\u0004 שהיה בו גם \u0003נזק, היכי שיימינן\u0004 \u0005[איך אנו מעריכים\u0006 אותו\u0005],\u0006 איך מעריכים את הצער בנפרד מהנזק?","\u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל:\u0004 \u0003אומדין כמה אדם רוצה ליטול לקטוע לו ידו.\u0004 ותוהים על כך: \u0003לקטוע לו ידו?\u0004 הרי \u0003לא צער לחודיה\u0004 \u0005[בלבד]\u0006 \u0003הוא, הא כולהו\u0004 \u0005[הרי כל]\u0006 ה\u0003חמשה דברים איכא\u0004 \u0005[יש כאן]!\u0006 \u0003ועוד,\u0004 וכי \u0003בשופטני עסקינן\u0004 \u0005[בשוטים אנו עוסקים],\u0006 באדם שמוכן לקבל שכר על מנת שיקטעו לו את ידו? \u0003אלא,\u0004 השאלה היא כמה מוכן לקבל כדי \u0003לקטוע\u0004 לו לגמרי את \u0003ידו הקטועה\u0004 כבר (שאינה פועלת). ותוהים: \u0003ידו הקטועה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא צער לחודיה איכא\u0004 \u0005[בלבד יש כאן],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003צער ובושת איכא\u0004 \u0005[יש כאן]\u0006 גם כן, שהרי \u0003כסיפא ליה מילתא\u0004 \u0005[מבוזה לו הדבר]\u0006 \u0003למשקל\u0004 \u0005[לקחת]\u0006 \u0003מבשרו למשדייה\u0004 \u0005[לזורקו]\u0006 \u0003לכלבים!\u0004","\u0003אלא\u0004 כך עושים: \u0003אומדין כמה אדם רוצה ליטול לקטוע לו ידו המוכתב למלכות,\u0004 שהמלכות גזרה עליו שיקטעו את ידו, כאשר הברירה היא בידו \u0003בין\u0004 קטיעה על ידי \u0003סם\u0004 שאין הדבר מלווה בכאב, \u0003ל\u0004בין קטיעה ב\u0003סייף\u0004 שיש בו צער, בעד איזה סכום יהא מוכן לעשות זאת בסייף. \u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחייה לכך: \u0003הכא נמי לא שקיל\u0004 \u0005[כאן גם כן אין\u0006 אדם \u0005נוטל\u0006 כסף\u0005]\u0006 \u0003ומצער נפשיה\u0004 \u0005[\u0006את \u0005עצמו]\u0006 בצער זה, ובוודאי יעדיף שיחתכו בסם ולא ניתן לאמוד דבר כזה!","\u0003אלא\u0004 כך עושים: \u0003אומדין כמה אדם\u0004 כמוהו \u0003רוצה ליתן\u0004 (לשלם) כדי \u0003לקטוע לו ידו המוכתב למלכות בין\u0004 קטיעה ב\u0003סייף ל\u0004קטיעה ב\u0003סם,\u0004 כלומר, על מנת שיעשו זאת בסם ולא בסייף.","ותוהים: אם כן \u0003האי\u0004 \u0005[זה]\u0006 הלשון \u0003\"ליטול\"\u0004 אינה נכונה, \u0003\"ליתן\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]:\u0006 כמה אדם רוצה ליתן כדי לא להצטער! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 הכוונה היא \u0003ליטול זה מזה\u0004 הניזק מהמזיק \u0003מה שנתן,\u0004 כלומר, שהיה נותן, \u0003זה,\u0004 הניזק למלך כדי שלא יצטער בצער זה.","שנינו במשנה: \u0003רפוי\u0004 מהו? — אם \u0003הכהו חייב לרפאותו.\u0004 עלו בו צמחים (מוגלה וגידולים אחרים), אם מחמת המכה — חייב, שלא מחמת המכה — פטור. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003עלו בו צמחים מחמת המכה ונסתרה\u0004 (ונפתחה) \u0003המכה\u0004 — \u0003חייב לרפאותו\u0004 שוב \u0003וחייב ליתן לו דמי שבתו,\u0004 שביטל מזמן עבודתו בריפוי המכה שנפתחה. אבל אם עלו בו \u0003שלא מחמת המכה\u0004 — \u0003אינו חייב לרפאותו ואינו חייב ליתן לו דמי שבתו,\u0004 זאת דעה אחת.","ואילו \u0003ר' יהודה אומר: אף מחמת המכה\u0004 — אכן \u0003חייב לרפאותו, ו\u0004אולם \u0003אינו חייב ליתן לו דמי שבתו.\u0004 \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 במקרה זה אינו חייב כלל, כי \u0003שבתו ורפואתו\u0004 נאמרו כאחד, והרי זה בא ללמד כי \u0003כל שחייב בשבת\u0004 — \u0003חייב בריפוי, ו\u0004כל \u0003שאינו חייב בשבת\u0004 — \u0003אינו חייב בריפוי.\u0004","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם חלוקים]?\u0006 \u0003אמר רבה: אשכחתינהו לרבנן בבי רב דיתבי וקאמרי\u0004 \u0005[מצאתי את החכמים בבית המדרש שיושבים ואומרים]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003מכה ניתנה לאגד\u0004 (לחבישה) \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 כלומר, האם מותר לאדם לחבוש את מכתו כדי שלא יסבול בכך אף שבכך הוא גורם לתוצאות לוואי מזיקות ביצירת מוגלה וכיוצא בה.","\u0003רבנן סברי\u0004 \u0005[חכמים\u0006 כלומר, התנא הראשון בברייתא \u0005סבורים]:\u0006 \u0003מכה ניתנה לאגד,\u0004 וגם אם גרמה התחבושת להוצאות כספיות נוספות בשל תוצאות הלוואי, הרי אף אלה נחשבות כנגרמות מחמת המכה. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003מכה לא ניתנה לאגד,\u0004 ומשום כך על \u0003ריפוי דתנא ביה קרא\u0004 \u0005[ששנה בו הכתוב]\u0006 בלשון \"רפא ירפא\" (שמות כא, יט) — הרי זה ריבוי מיוחד, ולכך \u0003מיחייב\u0004 \u0005[חייב]\u0006 המכה לשלם לו, אבל \u0003שבת\u0004 ש\u0003לא תנא ביה קרא\u0004 \u0005[שנה בו הכתוב]\u0006 — \u0003לא מיחייב\u0004 \u0005[חייב].\u0006 כך הסבירו חכמי בית המדרש את המחלוקת.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני,\u0006 רבה\u0005]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 לדעת ר' יהודה \u0003מכה לא ניתנה לאגד\u0004 ואסור לו לעשות כן, \u0003ריפוי נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מיחייב\u0004 \u0005[יהיה חייב]!\u0006 \u0003אלא\u0004 ההסבר למחלוקת כך הוא: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003מכה ניתנה לאגד ו\u0004אולם \u0003לא ניתנה לאגד יתירה\u0004 \u0005[יתר],\u0006 להוסיף בה תחבושת יתירה, והוא עשה זאת לנוחיותו.","\u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון\u0004 ש\u0003לא ניתנה לאגד יתירה\u0004 \u0005[יתר]\u0006 ומכל מקום ניתנה לאגד, לכן \u0003ריפוי דתנא ביה קרא\u0004 \u0005[ששנה בו הכתוב]\u0006 — \u0003מיחייב\u0004 \u0005[חייב]\u0006 בו, \u0003שבת\u0004 ש\u0003לא תנא ביה קרא\u0004 \u0005[שנה בו הכתוב]\u0006 — \u0003לא מיחייב\u0004 \u0005[חייב]\u0006 בו. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003כיון דתנא ביה קרא\u0004 \u0005[ששנה בו הכתוב]\u0006 \u0003בריפוי, אשבת נמי מיחייב\u0004 \u0005[על שבת גם כן חייב],\u0006 \u0003דאיתקש\u0004 \u0005[שהוקש\u0006 בכתוב\u0005]\u0006 \u0003לריפוי.\u0004","ומעירים: \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 אף שהוקשו זה לזה, מכל מקום \u0003שבת לא מיחייב\u0004 \u0005[חייב],\u0006 משום \u0003דמעטיה רחמנא\u0004 \u0005[שמיעט אותו הכתוב]\u0006 שנאמר \u0003\"רק\u0004 שבתו יתן\u0003\"\u0004 (שמות כא, יט), ו\"רק\" לשון מיעוט היא. ומן הצד השני \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם אומרים? — לדעתם \u0003\"רק\"\u0004 זה \u0003ל\u0004עלו בו צמחים \u0003שלא מחמת המכה הוא דאתא\u0004 \u0005[שבא]\u0006 למעט שפטור מלשלם.","ושואלים: \u0003ולרבנן בתראי דאמרי\u0004 \u0005[ולחכמים האחרונים שאומרים]\u0006 ש\u0003כל שחייב בשבת חייב בריפוי, וכל שאינו חייב בשבת אינו חייב בריפוי, ריפוי דתנא ביה קרא\u0004 \u0005[ששנה בו הכתוב]\u0006 \u0003למה לי?\u0004 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003לכדתנא דבי\u0004 \u0005[לכפי ששנה\u0006 החכם \u0005של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 התנא \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל אומר: \"ורפא ירפא\"\u0004 (שמות כא, יט) — \u0003מכאן שניתן רשות לרופא לרפאות,\u0004 ואין אומרים שצריך לסמוך על הקדוש ברך הוא בלבד.","ובענין זה מביאים את מה ששנינו בברייתא נוספת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאם עלו בו צמחים מחמת המכה ונסתרה המכה, שחייב\u0004 החובל בחבירו \u0003לרפאותו\u0004 שוב \u0003וחייב ליתן לו שבתו\u0004 על הימים הנוספים לשביתתו ממלאכה? — \u0003תלמוד לומר: \"רק שבתו יתן ורפא ירפא\". יכול\u0004 שיהא הדין כן \u0003אפילו\u0004 עלו בו \u0003שלא מחמת המכה?\u0004 — \u0003תלמוד לומר: \"רק\",\u0004 למעט. והרי זה כדעת חכמים ראשונים שבברייתא. \u0003ר' יוסי בר יהודה אומר: אף\u0004 אם עלו בו צמחים \u0003מחמת המכה\u0004 — \u0003פטור, שנאמר: \"רק\".\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בדעת ר' יוסי בר' יהודה: \u0003אף מחמת המכה\u0004 — \u0003פטור לגמרי\u0004 בלי לשלם כל דבר, לא ריפוי ולא שבת, והרי זה \u0003כ\u0004דעת \u0003רבנן בתראי\u0004 \u0005[חכמים אחרונים].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אף מחמת המכה\u0004 — \u0003פטור מ\u0004תשלום על ה\u0003שבת ו\u0004אולם \u0003חייב בריפוי, כמאן\u0004 \u0005[כמי]\u0006 הוא אומר זאת? — \u0003כאבוה\u0004 \u0005[כ\u0006דעת \u0005אביו\u0006 ר' יהודה\u0005],\u0006 כן גם דעתו.","ושבים לדון בדעת חכמים ראשונים שבברייתא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יכול אפילו\u0004 עלו בו צמחים \u0003שלא מחמת המכה\u0004 חייב לרפאותו? — \u0003תלמוד לומר: \"רק\".\u0004 ותוהים: \u0003שלא מחמת המכה בעי קרא\u0004 \u0005[צריך כתוב]\u0006 מיוחד להשמיענו שהחובל אינו חייב לשלם, וכי מדוע שישלם אם הוא לא גרם לכך?","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"שלא מחמת המכה\"? כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שעבר\u0004 הניזוק \u0003על דברי\u0004 ה\u0003רופא ואכל דבש או כל מיני מתיקה\u0004 שאסר עליו לאוכלם, \u0003מפני שדבש וכל מיני מתיקה קשין\u0004 (מזיקים) \u0003למכה, והעלה מכתו גרגותני\u0004 \u0005[נמק]\u0006 מחמת כך, \u0003יכול יהא חייב\u0004 החובל \u0003לרפאותו? — תלמוד לומר: \"רק\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003גרגותני? אמר אביי: נאתא כריכתא\u0004 \u0005[בשר מת].\u0006 \u0003מאי אסותיה\u0004 \u0005[מה רפואתו]?\u0006 — \u0003אהלא וקירא וקלבא\u0004 \u0005[אהל ושעווה ושמרים].\u0006","ומביאים מספר הלכות בפרטי תשלום הריפוי: \u0003ואי אמר ליה\u0004 \u0005[ואם אומר לו]\u0006 המזיק: \u0003אסייך אנא\u0004 \u0005[ארפאך אני],\u0006 שהוא עצמו רופא, \u0003אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 הניזק: \u0003דמית\u0004 \u0005[דומה אתה]\u0006 \u0003עלי כאריא ארבא\u0004 \u0005[כאריה אורב]\u0006 ואני מפחד ממך ואיני רוצה להתרפא ממך. \u0003ואי אמר ליה\u0004 \u0005[ואם אומר לו]\u0006 המזיק: \u0003מייתינא אסיא דמגן במגן\u0004 \u0005[אני אביא רופא של חינם ש\u0006ירפא אותך \u0005בחינם]\u0006 ולא אצטרך לשלם, \u0003אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 הניזק: \u0003אסיא דמגן במגן\u0004 \u0005[רופא ש\u0006מרפא \u0005בחינם]\u0006 — \u0003מגן\u0004 \u0005[חינם,\u0006 לא כלום\u0005]\u0006 הוא \u0003שוה.\u0004","\u0003ואי אמר\u0004 \u0005[ואם אומר]\u0006 המזיק: \u0003מייתינא\u0004 \u0005[אביא]\u0006 \u0003לך אסיא רחיקא\u0004 \u0005[רופא\u0006 ממקום \u0005רחוק]\u0006 שיוריד מן המחיר בשבילי, \u0003אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 הניזק: \u0003אסיא רחיקא עינא עוירא\u0004 \u0005[רופא רחוק מעוור\u0006 את \u0005העין],\u0006 כי רופא הדר באותו מקום דואג שהחולה יתרפא, ורופא הגר במקום רחוק לא איכפת לו לאחר שמקבל שכרו.","ומן הצד השני \u0003ואי אמר ליה היאך\u0004 \u0005[ואם אומר לו האחר,\u0006 הניזק\u0005]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי לדידי\u0004 \u0005[לעצמי]\u0006 את הכסף \u0003ואנא מסינא נפשאי\u0004 \u0005[ואני\u0006 אדאג \u0005לרפא את עצמי],\u0006 \u0003אמר ליה\u0004 \u0005[יכול לומר לו\u0006 המזיק\u0005]:\u0006 \u0003פשעת בנפשך ושקלת מינאי טפי\u0004 \u0005[תתרשל בעצמך ו\u0006בסוף \u0005תיקח ממני יותר]\u0006 משום שלא תתרפא כראוי. \u0003ואי אמר ליה\u0004 \u0005[ואם אומר לו\u0006 הניזק\u0005]:\u0006 \u0003קוץ לי מקץ\u0004 \u0005[קצוב לי קיצבה]\u0006 סכום מסויים לריפוי ואני אטפל בדבר, \u0003אמר ליה\u0004 \u0005[יכול לומר לו]\u0006 המזיק: \u0003כל שכן דפשעת בנפשך\u0004 \u0005[שתתרשל בעצמך]\u0006 שתרצה להרויח ולא תשלם לרופא כראוי ותישאר חולה, \u0003וקרו\u0004 \u0005[ויקראו]\u0006 \u0003לי\u0004 הבריות \u0003\"שור המזיק\",\u0004 שאני גרמתי לך לנזק שאינו מתרפא.","על המשנה המסבירה את תשלומי הצער והריפוי השבת והבושת \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וכולן,\u0004 כל אלה, \u0003משתלמין במקום\u0004 שמשלם \u0003נזק.\u0004 כלומר, בנוסף לתשלום הנזק. ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 מה מקורם? \u0003אמר רב זביד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"פצע תחת פצע\"\u0004 (שמות כא, כה) — \u0003ליתן צער במקום נזק,\u0004 שצריך להוסיף גם תשלום צער במקום שמשלם על הנזק.","ותוהים: הלא \u0003האי מבעי ליה\u0004 \u0005[\u0006הכתוב \u0005הזה צריך אותו]\u0006 ללימוד אחר:"],["\u0003לרבות\u0004 מי שהזיק ב\u0003שוגג כמזיד ואונס כרצון,\u0004 שחייב בכל דרך שהזיק! ומשיבים: \u0003אם כן,\u0004 אם רק בשביל כך בלבד בא המקרא, \u0003נכתוב קרא\u0004 \u0005[שיכתוב הכתוב]\u0006 רק \u0003\"פצע בפצע\", מאי\u0004 \u0005[מה\u0006 פירוש\u0005],\u0006 מדוע כתבה התורה בלשון \u0003\"פצע תחת פצע\"?\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 גם לענין זה שהחובל משלם בכל דרך שהזיק, וגם לענין זה שצריך להוסיף תשלומי צער נוסף לנזק. זהו המקור לתשלום צער במקום נזק.","ובאשר לתשלום ריפוי במקום נזק \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ורפא ירפא\"\u0004 (שמות כא, יט), והדגשה זו באה לחייב את החובל \u0003ליתן\u0004 דמי \u0003רפואה במקום\u0004 שמשלם דמי \u0003נזק.\u0004","ושואלים: \u0003האי מבעי ליה לכדתנא דבי\u0004 \u0005[\u0006דבר \u0005זה צריך אותו לכמו ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 מה שנאמר \u0003\"ורפא ירפא\"\u0004 — \u0003מכאן שניתנה רשות לרופא לרפאות!\u0004 ומשיבים: \u0003אם כן, נכתוב קרא\u0004 \u0005[שיכתוב הכתוב]\u0006 \u0003\"ורופא ירפא\",\u0004 ומדוע נאמר \"ורפא ירפא\"? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 את הלכה זו \u0003ליתן רפואה במקום נזק.\u0004","ומקשים: \u0003ואכתי מבעי ליה\u0004 \u0005[ועדיין צריך אותו]\u0006 \u0003לכדאמרן\u0004 \u0005[לכפי שאמרנו\u0006 קודם\u0005],\u0006 \u0003למיתני ביה קרא\u0004 \u0005[לשנות בו הכתוב]\u0006 זה \u0003בריפוי,\u0004 שהרי למדו מכפילות זו של המלים כמה הלכות! ומשיבים: \u0003אם כן, לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק אותן מילים בהכפלה: \u0003או \"רפא רפא\" או \"ירפא ירפא\", מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"ורפא ירפא\"\u0004 בשינוי? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שבא הדבר \u0003ליתן\u0004 חיוב תשלומי \u0003רפואה במקום נזק.\u0004","שואלים: מתוך ששנינו בברייתא שתשלומי צער, ריפוי, שבת ובושת משולמים גם במקום שיש תשלום נזק \u0003מכלל דמשכחת להו\u0004 \u0005[מכאן שאתה מוצא אותם]\u0006 את חיובי התשלומים הללו גם \u0003שלא במקום נזק, שלא במקום\u0004 שעשה \u0003נזק היכי משכחת להו\u0004 \u0005[כיצד אתה מוצא אותם]?\u0006","ומשיבים: \u0003צער\u0004 שלא במקום נזק, \u0003כדקתני\u0004 \u0005[כמו ששנה]\u0006 במשנה במפורש: \u0003צער\u0004 — ש\u0003כוואו בשפוד או במסמר, ואפילו על צפורנו מקום שאינו עושה חבורה,\u0004 אלא רק כאב בלבד. \u0003ריפוי\u0004 שלא במקום נזק — \u0003דהוה כאיב ליה מידי\u0004 \u0005[שהיה כואב לו דבר],\u0006 \u0003וסליק ואייתי ליה סמא חריפא\u0004 \u0005[ובא\u0006 זה המזיק \u0005והביא לו סם חריף]\u0006 \u0003ואחווריה לבישריה\u0004 \u0005[והלבין את בשרו]\u0006 על ידי כך, \u0003דצריך לאותבי ליה סמא לאנקוטיה גוונא דבישריה\u0004 \u0005[שצריך לתת לו סם\u0006 תרופה כדי \u0005להחזיר לו\u0006 את \u0005גוון הבשר]\u0006 ואף שלא גרם לו נזק, אבל עדיין צריך ריפוי.","\u0003שבת\u0004 שלא במקום נזק — \u0003דהדקיה באינדרונא ובטליה\u0004 \u0005[ששם אותו במקום סגור וביטל אותו\u0006 מעבודתו\u0005]\u0006 ולא גרם לו כל נזק בגופו. \u0003בושת\u0004 שלא במקום נזק — כגון \u0003דרק ליה באפיה\u0004 \u0005[שירק לו בפניו]\u0006 אף על פי שלא גרם לו נזק.","שנינו במשנה: \u0003שבת\u0004 — \u0003רואין אותו כאילו הוא שומר קישואין.\u0004 ובאותו ענין \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבת\u0004 — \u0003רואין אותו כאילו הוא שומר קישואין. ואם תאמר: לקתה\u0004 בכך \u0003מדת הדין,\u0004 ומסבירים: \u0003דכי מיתפח האי גברא, לאו אגרא\u0004 \u0005[שכאשר מתרפא אדם זה, לא שכר]\u0006 של \u0003שומר קישואין הוא שקיל\u0004 \u0005[\u0006ש\u0005לוקח],\u0006 \u0003אלא דלי דוולא ושקיל אגרא\u0004 \u0005[דולה דליים ומקבל שכר]\u0006 מרובה יותר, \u0003אי נמי אזיל בשליח ושקיל אגרא\u0004 \u0005[או גם כן הולך כשליח ונוטל שכר]\u0006 או דברים חשובים יותר!","יש לענות על כך שבכל זאת \u0003מדת הדין לא לקתה, שכבר נתן לו דמי ידו ודמי רגלו\u0004 ושילם לו עבור ההפחתה בדמיו שנוצרה על ידי החבלה.","ובפרטי הדברים בענין זה \u0003אמר רבא: קטע את ידו\u0004 — \u0003נותן לו דמי ידו\u0004 כתשלום הנזק, \u0003ושבת\u0004 — \u0003רואין אותו כאילו הוא שומר קישואין,\u0004 שמהלך סביב הקישואים ושומר אותם. אם \u0003שיבר את רגלו\u0004 — \u0003נותן לו דמי רגלו, ושבת\u0004 — \u0003רואין אותו כאילו הוא שומר את הפתח,\u0004 לפי שאם הוא קטוע רגל אינו יכול לשמש כשומר קישואים, משום ששומר קישואים צריך ללכת מסביב לשדה כדי לשומרו.","אם \u0003סימא את עינו\u0004 — \u0003נותן לו דמי עינו, ושבת\u0004 — \u0003רואין אותו כאילו הוא מטחינו,\u0004 נותן לו עבודה כטוחן \u0003בריחים,\u0004 שגם עיוור יכול לעשות זאת (וראה שופטים טז, כא). אם \u0003חירשו\u0004 — \u0003נותן לו דמי כולו,\u0004 משום שהוא נחשב אז כמי שאינו ראוי לכל מלאכה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: אם \u0003קטע את ידו ולא אמדוהו\u0004 בית דין כמה הוא צריך לתת לו, ואחר כך הוסיף ו\u0003שיבר את רגלו ולא אמדוהו\u0004 אף על כך, ואחר כך \u0003סימא את עינו ולא אמדוהו, ולבסוף חירשו, מהו\u0004 דינו? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003לא אמדוהו\u0004 בכל פעם, \u0003בחד אומדנא סגי ליה\u0004 \u0005[באומדן אחד די לו],\u0006 \u0003ויהיב ליה\u0004 \u0005[ויתן לו]\u0006 את \u0003דמי כוליה בהדי הדדי\u0004 \u0005[כולו ביחד],\u0006 \u0003או דלמא חדא חדא אמדינן\u0004 \u0005[שמא אחת אחת אנו אומדים]\u0006 \u0003ויהבינן ליה\u0004 \u0005[ונותנים אנו לו]?\u0006","\u0003נפקא מיניה\u0004 \u0005[ויוצא מזה]\u0006 מדרך זו של ההערכה הנפרדת שוני מההערכה אחת על הכל משום שכך \u0003דבעי למיתב ליה\u0004 \u0005[צריך לתת לו]\u0006 \u0003צער ובושת\u0004 של \u0003כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 מן הפגיעות שפגע בו. שכן \u0003נהי\u0004 \u0005[\u0006אם \u0005אמנם]\u0006 ש\u0003נזק וריפוי ושבת\u0004 של \u0003כל חדא וחדא לא יהבינן ליה\u0004 \u0005[אחת ואחת אין אנו נותנים לו],\u0006 ש\u0003כיון דקא יהיב ליה דמי כוליה כמאן דקטליה דמי\u0004 \u0005[שנותן לו\u0006 לבסוף את \u0005דמי כולו\u0006 משום שחירשו, \u0005כמי שהרגו נחשב],\u0006 \u0003והא יהיב ליה\u0004 \u0005[והרי נותן לו]\u0006 את \u0003דמי כוליה\u0004 \u0005[כולו],\u0006 אבל \u0003צער ובושת מיהת\u0004 \u0005[בכל זאת]\u0006 של \u0003כל חדא וחדא יהיב\u0004 \u0005[אחת ואחת נותן],\u0006 \u0003דהא הוה ליה\u0004 \u0005[שהרי היה לו]\u0006 \u0003צער ובושת\u0004 בכל פעם.","\u0003ואם תימצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 בפתרון שאלה זו כי \u0003כיון\u0004 ש\u0003לא אמדוהו\u0004 בזמנו \u0003קא יהיב ליה\u0004 \u0005[נותן לו]\u0006 את \u0003דמי כוליה בהדי הדדי\u0004 \u0005[כולו ביחד],\u0006 יש לשאול עוד: אם \u0003אמדוהו\u0004 על ידו, רגלו ועינו קודם לכן, ולא שילם לו לפני שחירשו \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003אמדוהו חדא חדא בעי למיתב ליה\u0004 \u0005[אחת אחת צריך לתת לו],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003לא שלים\u0004 \u0005[שילם]\u0006 עדיין לפני שחירשו — \u0003יהיב ליה\u0004 \u0005[נותן לו]\u0006 את \u0003דמי כוליה\u0004 \u0005[כולו]?\u0006 לשאלות אלה לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003בעי רבה:\u0004 המכה את חבירו הכאה המביאתו לידי \u0003שבת\u0004 (בטלה ממלאכה) \u0003הפוחתתו בדמים, מהו\u0004 \u0005[דינו]?\u0006 ומסבירים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 — \u0003כגון שהכהו על ידו וצמתה\u0004 (התכווצה, שותקה) \u0003ידו\u0004 ואינו יכול עתה לעבוד עבודתו \u0003וסופה לחזור\u0004 למצבה הרגיל, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם נאמר \u0003כיון\u0004 ש\u0003סופה לחזור לא יהיב ליה\u0004 \u0005[נותן לו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 \u0003או דלמא השתא מיהת אפחתיה\u0004 \u0005[שמא עכשיו\u0006 עד שתחזור ידו לפעילותה \u0005על כל פנים הפחית אותו\u0006 מערכו\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003המכה\u0004 את \u0003אביו ואמו ולא עשה בהן חבורה\u0004 (פצע שיש בו דימום) ואין עליו באופן זה חיוב מיתה אלא אם כן עושה בהם חבורה, \u0003והחובל בחבירו ביום הכפורים\u0004 שחייב כרת בידי שמים ואינו נענש בידי אדם —"]]};
